var e={id:`k1-48-vulva-vajen-ve-serviks-hastaliklari`,sira:48,kurul:1,ders:`Tıbbi Patoloji`,konu:`Vulva, Vajen ve Serviks Hastalıkları`,ogretim_uyesi:`Prof. Dr. Hikmet Keleş`,tarih:`2026-10-07`,soru_sayisi:176,kazanimlar:[{no:1,metin:`Vulva, vajina ve serviksin sık görülen lezyonlarını özetleyebilmek`,sorular:[{id:`k1-48-q01`,kazanim:1,zorluk:`kolay`,soru:`Vulvada en sık görülen lezyon grubu hangisidir?`,secenekler:{A:`Konjenital anomaliler`,B:`Malign tümörler`,C:`İnflamatuvar lezyonlar`,D:`Metastatik tümörler`,E:`Sarkomlar`},dogru:`C`,aciklama:`Vulva hastalık spektrumunda en sık inflamatuvar lezyonlar görülür; malign tümörler nadir ama önemlidir.`,sik_aciklamalari:{A:`Konjenital anomaliler daha çok vajinada ve nadiren görülür.`,B:`Malign tümörler nadirdir.`,C:`Doğru: vulvit gibi inflamatuvar durumlar en sıktır.`,D:`Metastatik tümörler vulvada sık değildir.`,E:`Sarkomlar çok nadirdir.`},bilgi:[1],benzer_cikmis:[]},{id:`k1-48-q02`,kazanim:1,zorluk:`orta`,soru:`Serviks lezyonları ile ilgili aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`Servikal lezyonların çoğu maligndir`,B:`Servikal lezyonların çoğu inflamatuvar niteliktedir (servisit)`,C:`Servikal karsinom HPV ile ilişkili değildir`,D:`Taramada yalnızca serum tümör belirteçleri kullanılır`,E:`Gelişmekte olan ülkelerde mortalitesi düşüktür`},dogru:`B`,aciklama:`Servikal lezyonların çoğu servisit gibi inflamatuvar süreçlerdir; skuamöz hücreli karsinom HPV ile ilişkilidir.`,sik_aciklamalari:{A:`Malign lezyonlar daha azdır.`,B:`Doğru: servisit en sık servikal lezyondur.`,C:`Servikal SCC'nin HPV ile ilişkisi belirgindir.`,D:`Tarama Pap testi ve HPV testi ile yapılır.`,E:`Gelişmekte olan ülkelerde mortalite yüksektir.`},bilgi:[40],benzer_cikmis:[]},{id:`k1-48-q03`,kazanim:1,zorluk:`zor`,soru:`Vajina hastalıkları ile ilgili aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`Vajinal tümörlerin çoğu HPV ile ilişkisizdir`,B:`Vajinanın en sık tümörü primer adenokarsinomdur`,C:`Yetişkinlerde vajina nadiren primer hastalık yeridir; komşu organ kanserlerinin sekonder tutulumu daha sıktır`,D:`Gartner kanal kisti malign bir tümördür`,E:`Vajinit genellikle kalıcı ve kronik seyirlidir`},dogru:`C`,aciklama:`Vajina yetişkinde nadiren primer hastalık yeridir; serviks, mesane ve rektum kanserlerinin sekonder tutulumu daha sıktır.`,sik_aciklamalari:{A:`Primer vajinal SCC'ler yüksek riskli HPV ile ilişkilidir.`,B:`Primer karsinomların neredeyse tamamı skuamöz hücreli karsinomdur.`,C:`Doğru: sekonder tutulum primer tümörden sıktır.`,D:`Gartner kisti benign bir Wolffian kalıntısıdır.`,E:`Vajinit çoğunlukla enfeksiyöz ve geçicidir.`},bilgi:[31,33,38],benzer_cikmis:[]},{id:`k1-48-vulva-vajen-ve-serviks-hastaliklari-k01-q04`,kazanim:1,zorluk:`orta`,soru:`Poliklinikte vulvar kaşıntılı hasta ile servisitli hasta ve vajinitli hasta aynı günde görülüyor. Bu üç bölgeye ilişkin aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`Vulvada en sık inflamatuvar lezyonlar, servikste servisit ve vajinada geçici enfeksiyöz vajinit sıktır; maligniteler nadir ama önemlidir`,B:`Her bölgede malignite en sıktır`,C:`Vulvit nadirdir`,D:`Servisit hiç görülmez`,E:`Vajinit hep kroniktir`},dogru:`A`,aciklama:`Üç bölgede de inflamatuvar/enfeksiyöz tablolar sık; malignite nadir-önemlidir.`,sik_aciklamalari:{A:`Doğru: Üç bölgede de inflamatuvar/enfeksiyöz tablolar sık; malignite nadir-önemlidir.`,B:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Vulvada en sık inflamatuvar lezyonlar, servikste servisit ve vajinada geçici enfeksiyöz vajinit sıktır; maligniteler nadir ama önemlidir' seçeneğidir.`,C:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Vulvada en sık inflamatuvar lezyonlar, servikste servisit ve vajinada geçici enfeksiyöz vajinit sıktır; maligniteler nadir ama önemlidir' seçeneğidir.`,D:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Vulvada en sık inflamatuvar lezyonlar, servikste servisit ve vajinada geçici enfeksiyöz vajinit sıktır; maligniteler nadir ama önemlidir' seçeneğidir.`,E:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Vulvada en sık inflamatuvar lezyonlar, servikste servisit ve vajinada geçici enfeksiyöz vajinit sıktır; maligniteler nadir ama önemlidir' seçeneğidir.`},bilgi:[1,2,33,40],benzer_cikmis:[]},{id:`k1-48-vulva-vajen-ve-serviks-hastaliklari-k01-q05`,kazanim:1,zorluk:`zor`,soru:`Vajinanın primer hastalık yeri olma sıklığı ile servikal lezyonların doğası soruluyor. Aşağıdakilerden hangisi yanlıştır?`,secenekler:{A:`Vajina yetişkinde nadiren primer hastalık yeridir; komşu kanserlerin sekonder tutulumu daha sıktır`,B:`Vulvada inflamatuvar lezyonlar sıktır`,C:`Servikal lezyonların çoğu inflamatuvar (servisit) niteliktedir`,D:`Vajina hep primer hastalık yeridir ve servikal lezyonların çoğu maligndir`,E:`Erken tanı ve biyopsi önemlidir`},dogru:`C`,aciklama:`Vajina nadiren primer yerdir; servikste inflamasyon sıktır.`,sik_aciklamalari:{A:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Servikal lezyonların çoğu inflamatuvar (servisit) niteliktedir' seçeneğidir.`,B:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Servikal lezyonların çoğu inflamatuvar (servisit) niteliktedir' seçeneğidir.`,C:`Doğru: Vajina nadiren primer yerdir; servikste inflamasyon sıktır.`,D:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Servikal lezyonların çoğu inflamatuvar (servisit) niteliktedir' seçeneğidir.`,E:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Servikal lezyonların çoğu inflamatuvar (servisit) niteliktedir' seçeneğidir.`},bilgi:[1,31,40],benzer_cikmis:[]},{id:`k1-48-vulva-vajen-ve-serviks-hastaliklari-k01-q06`,kazanim:1,zorluk:`orta`,soru:`Vulva, vajina ve servikste lezyon sıklığının genel dağılımı nasıldır?`,secenekler:{A:`Her üç bölgede malignite en sıktır`,B:`İnflamatuvar tablolar sık; malignite nadir-önemlidir`,C:`Vulvit ve vajinit hiç görülmez`,D:`Servikal lezyonların çoğu maligndir`,E:`Vajinit hep kronik ve kalıcıdır`},dogru:`B`,aciklama:`Üç bölgede de inflamatuvar ve enfeksiyöz tablolar sıktır; maligniteler nadir ama klinik olarak önemlidir. Vulvada vulvit, servikste servisit ve vajinada geçici vajinit baskındır. Bu dağılım ilk basamak yaklaşımı belirler.`,sik_aciklamalari:{A:`Yanlış: Maligniteler nadirdir, inflamasyon baskındır.`,B:`Doğru: Üç bölgede de enfeksiyöz-inflamatuvar lezyonlar sıktır.`,C:`Yanlış: Vulvit ve vajinit sık görülen tablolardır.`,D:`Yanlış: Servikal lezyonların çoğu servisit gibi inflamatuardır.`,E:`Yanlış: Vajinit genellikle geçici enfeksiyöz tablodur.`},bilgi:[2,33,40],benzer_cikmis:[]},{id:`k1-48-vulva-vajen-ve-serviks-hastaliklari-k01-q07`,kazanim:1,zorluk:`orta`,soru:`Vajinanın primer hastalık yeri olma sıklığı ve servikal lezyonların doğası nedir?`,secenekler:{A:`Vajina hep primer hastalık yeridir`,B:`Servikal lezyonların çoğu maligndir`,C:`Sekonder tutulum hiç görülmez`,D:`Vajina nadiren primer; servikste servisit sıktır`,E:`Servisit erişkinde hiç görülmez`},dogru:`D`,aciklama:`Vajina yetişkinde nadiren primer hastalık yeridir; komşu kanserlerin sekonder tutulumu daha sıktır. Servikal lezyonların çoğu inflamatuvar (servisit) niteliktedir. Bu nedenle vajinal kitlede önce komşu organ yayılımı araştırılır.`,sik_aciklamalari:{A:`Yanlış: Vajina nadiren primer hastalanır.`,B:`Yanlış: Servikste inflamatuvar lezyonlar baskındır.`,C:`Yanlış: Komşu organ yayılımı vajinada sıktır.`,D:`Doğru: Sekonder tutulum primerden sık, servisit yaygındır.`,E:`Yanlış: Servisit serviksin en sık lezyon grubudur.`},bilgi:[31,40],benzer_cikmis:[]},{id:`k1-48-vulva-vajen-ve-serviks-hastaliklari-k01-q08`,kazanim:1,zorluk:`kolay`,soru:`Aşağıdakilerden "Vajinal intraepiteliyal neoplazi (VAIN)" ile ilgili doğru olan seçeneği işaretleyiniz.`,secenekler:{B:`Skuamöz hücreli karsinomun öncü lezyonudur ve displazi derecesine göre sınıflanır.`,C:`VIN seyri yüksek dereceli atipi ve karsinoma in situ gelişimidir; invaziv karsinom riski 45 yaşından büyük kadınlarda ve immün sistemi baskılanmış hastalarda artar.`,E:`1) Bazaloid/siğil benzeri karsinom yüksek riskli HPV ile ilişkilidir. 2) Keratinize skuamöz hücreli karsinom HPV ile ilişkili değildir ve liken skleroz veya skuamöz hücre hiperplazisi zemininde gelişir.`,D:`HPV pozitif tümörler sıklıkla multifokal, siğil benzeri ve genellikle kötü diferansiye; HPV negatif tümörler genellikle unifokal ve iyi diferansiye, keratinize skuamöz hücreli karsinomdur.`,A:`Vajinanın inflamatuar durumudur; genellikle enfeksiyona bağlı ve geçicidir, temel bulgu vajinal akıntıdır (lökore). Etkenler bakteri, mantar, parazit olup pek çoğu normal kommensal flora üyesidir.`},dogru:`B`,aciklama:`Doğru: Skuamöz hücreli karsinomun öncü lezyonudur ve displazi derecesine göre sınıflanır.`,sik_aciklamalari:{B:`Doğru. Skuamöz hücreli karsinomun öncü lezyonudur ve displazi derecesine göre sınıflanır.`,C:`Yanlış. VIN seyri yüksek dereceli atipi ve karsinoma in situ gelişimidir; invaziv karsinom riski 45 yaşından büyük kadınlarda ve immün sistemi baskılanmış hastalarda artar.`,E:`Yanlış. 1) Bazaloid/siğil benzeri karsinom yüksek riskli HPV ile ilişkilidir. 2) Keratinize skuamöz hücreli karsinom HPV ile ilişkili değildir ve liken skleroz veya skuamöz hücre hiperplazisi zemininde gelişir.`,D:`Yanlış. HPV pozitif tümörler sıklıkla multifokal, siğil benzeri ve genellikle kötü diferansiye; HPV negatif tümörler genellikle unifokal ve iyi diferansiye, keratinize skuamöz hücreli karsinomdur.`,A:`Yanlış. Vajinanın inflamatuar durumudur; genellikle enfeksiyona bağlı ve geçicidir, temel bulgu vajinal akıntıdır (lökore). Etkenler bakteri, mantar, parazit olup pek çoğu normal kommensal flora üyesidir.`},bilgi:[37],benzer_cikmis:[]},{id:`k1-48-vulva-vajen-ve-serviks-hastaliklari-k01-q09`,kazanim:1,zorluk:`orta`,soru:`"HPV negatif vulvar karsinom ve dVIN" ile ilgili eşleştirmelerden hangisi doğrudur?`,secenekler:{E:`Genellikle yaşlı kadınlarda (ortalama yaş ~75), uzun süreli liken skleroz ve skuamöz hücre hiperplazisi zemininde görülür ve HPV ile ilişkili değildir; ön lezyonu dVIN'dir (bazal tabakaya sınırlı anormal keratinizasyon ve sitolojik atipi).`,C:`En yaygın kondilom tipidir; etkeni düşük riskli HPV tip 6 ve 11'dir, cinsel temasla bulaşır ve sıklıkla genç erişkinlerde görülür.`,D:`Vulvit vulvanın inflamasyonudur; sık görülen, çok nedenli bir durumdur ve sıklıkla yoğun kaşıntı ile seyreder.`,A:`HSV-1 ve HSV-2 genital herpes etkenidir; ağrılı vezikül ve ülserler ile tekrarlayıcı seyir yapar.`,B:`HPV pozitif tümörler sıklıkla multifokal, siğil benzeri ve genellikle kötü diferansiye; HPV negatif tümörler genellikle unifokal ve iyi diferansiye, keratinize skuamöz hücreli karsinomdur.`},dogru:`E`,aciklama:`Doğru: Genellikle yaşlı kadınlarda (ortalama yaş ~75), uzun süreli liken skleroz ve skuamöz hücre hiperplazisi zemininde görülür ve HPV ile ilişkili değildir; ön lezyonu dVIN'dir (bazal tabakaya sınırlı anormal keratinizasyon ve sitolojik atipi).`,sik_aciklamalari:{E:`Doğru. Genellikle yaşlı kadınlarda (ortalama yaş ~75), uzun süreli liken skleroz ve skuamöz hücre hiperplazisi zemininde görülür ve HPV ile ilişkili değildir; ön lezyonu dVIN'dir (bazal tabakaya sınırlı anormal keratinizasyon ve sitolojik atipi).`,C:`Yanlış. En yaygın kondilom tipidir; etkeni düşük riskli HPV tip 6 ve 11'dir, cinsel temasla bulaşır ve sıklıkla genç erişkinlerde görülür.`,D:`Yanlış. Vulvit vulvanın inflamasyonudur; sık görülen, çok nedenli bir durumdur ve sıklıkla yoğun kaşıntı ile seyreder.`,A:`Yanlış. HSV-1 ve HSV-2 genital herpes etkenidir; ağrılı vezikül ve ülserler ile tekrarlayıcı seyir yapar.`,B:`Yanlış. HPV pozitif tümörler sıklıkla multifokal, siğil benzeri ve genellikle kötü diferansiye; HPV negatif tümörler genellikle unifokal ve iyi diferansiye, keratinize skuamöz hücreli karsinomdur.`},bilgi:[26],benzer_cikmis:[]},{id:`k1-48-vulva-vajen-ve-serviks-hastaliklari-k01-q10`,kazanim:1,zorluk:`orta`,soru:`"Vulvitin alerjik ve irritan nedenleri" kavramı hakkında verilen aşağıdakilerden hangisi doğrudur?`,secenekler:{D:`Reaktif inflamasyon alerjen veya irritan temasına yanıttır; losyon ve sabun katkı maddeleri, antiseptikler ve giysi kimyasalları rol oynar.`,A:`Lateral vajinal duvarda yerleşir ve kalıcı Wolffian kanal kalıntısından gelişir.`,B:`Nadir bir vajinal tümördür (sarkoma botryoides); histogenezi malign embriyonel rabdomiyoblastlardır ve 5 yaşından küçük bebek ve çocuklarda görülür.`,C:`Vulvit vulvanın inflamasyonudur; sık görülen, çok nedenli bir durumdur ve sıklıkla yoğun kaşıntı ile seyreder.`,E:`En yaygın kondilom tipidir; etkeni düşük riskli HPV tip 6 ve 11'dir, cinsel temasla bulaşır ve sıklıkla genç erişkinlerde görülür.`},dogru:`D`,aciklama:`Doğru: Reaktif inflamasyon alerjen veya irritan temasına yanıttır; losyon ve sabun katkı maddeleri, antiseptikler ve giysi kimyasalları rol oynar.`,sik_aciklamalari:{D:`Doğru. Reaktif inflamasyon alerjen veya irritan temasına yanıttır; losyon ve sabun katkı maddeleri, antiseptikler ve giysi kimyasalları rol oynar.`,A:`Yanlış. Lateral vajinal duvarda yerleşir ve kalıcı Wolffian kanal kalıntısından gelişir.`,B:`Yanlış. Nadir bir vajinal tümördür (sarkoma botryoides); histogenezi malign embriyonel rabdomiyoblastlardır ve 5 yaşından küçük bebek ve çocuklarda görülür.`,C:`Yanlış. Vulvit vulvanın inflamasyonudur; sık görülen, çok nedenli bir durumdur ve sıklıkla yoğun kaşıntı ile seyreder.`,E:`Yanlış. En yaygın kondilom tipidir; etkeni düşük riskli HPV tip 6 ve 11'dir, cinsel temasla bulaşır ve sıklıkla genç erişkinlerde görülür.`},bilgi:[3],benzer_cikmis:[]},{id:`k1-48-vulva-vajen-ve-serviks-hastaliklari-k01-q11`,kazanim:1,zorluk:`zor`,soru:`"Vajina genel özellikler ve anomaliler" ile ilgili bir hastada bulunacak aşağıdaki bulgulardan hangisi beklenmez?`,secenekler:{B:`Yetişkinlerde nadiren primer hastalık yeridir; daha sık komşu organ kanserlerinin (serviks, mesane, rektum) sekonder tutulumu görülür. Nadir konjenital anomaliler: vajinanın tam yokluğu, septalı veya çift vajina.`,A:`Her yaşta görülebilir (menopoz sonrası kadınlar, ergenlik öncesi kızlar); patogenezi belirsizdir, subepiteliyal aktif T hücre infiltrasyonu ve otoimmün bozukluklarla birliktelik vardır.`,E:`İki temel tablo liken skleroz ve skuamöz hücre hiperplazisidir; klinik olarak genellikle lökoplaki şeklinde görülürler.`,C:`Tüm kadın genital sistem kanserlerinin ~%3'ü; 60 yaş üstü kadınlarda görülür; histolojik tiplerin ~%90'ı skuamöz hücreli karsinom, diğerleri adenokarsinom ve bazal hücreli karsinomdur.`,D:`Vulva dış kadın genital organıdır; kıllı deri (labia majora) ve mukoza (labia minora) içerir.`},dogru:`B`,aciklama:`Doğru: Yetişkinlerde nadiren primer hastalık yeridir; daha sık komşu organ kanserlerinin (serviks, mesane, rektum) sekonder tutulumu görülür. Nadir konjenital anomaliler: vajinanın tam yokluğu, septalı veya çift vajina.`,sik_aciklamalari:{B:`Doğru. Yetişkinlerde nadiren primer hastalık yeridir; daha sık komşu organ kanserlerinin (serviks, mesane, rektum) sekonder tutulumu görülür. Nadir konjenital anomaliler: vajinanın tam yokluğu, septalı veya çift vajina.`,A:`Yanlış. Her yaşta görülebilir (menopoz sonrası kadınlar, ergenlik öncesi kızlar); patogenezi belirsizdir, subepiteliyal aktif T hücre infiltrasyonu ve otoimmün bozukluklarla birliktelik vardır.`,E:`Yanlış. İki temel tablo liken skleroz ve skuamöz hücre hiperplazisidir; klinik olarak genellikle lökoplaki şeklinde görülürler.`,C:`Yanlış. Tüm kadın genital sistem kanserlerinin ~%3'ü; 60 yaş üstü kadınlarda görülür; histolojik tiplerin ~%90'ı skuamöz hücreli karsinom, diğerleri adenokarsinom ve bazal hücreli karsinomdur.`,D:`Yanlış. Vulva dış kadın genital organıdır; kıllı deri (labia majora) ve mukoza (labia minora) içerir.`},bilgi:[31],benzer_cikmis:[]}],ilgili_cikmis:[]},{no:2,metin:`Non-neoplastik ve neoplastik süreçleri ayırt edebilmek`,sorular:[{id:`k1-48-q04`,kazanim:2,zorluk:`kolay`,soru:`Aşağıdakilerden hangisi vulvanın non-neoplastik epitel bozukluklarından biridir?`,secenekler:{A:`Bazaloid karsinom`,B:`Vulvar intraepitelyal neoplazi`,C:`Ekstramammary Paget hastalığı`,D:`Liken skleroz`,E:`Keratinize skuamöz hücreli karsinom`},dogru:`D`,aciklama:`Vulvanın iki temel non-neoplastik epitel bozukluğu liken skleroz ve skuamöz hücre hiperplazisidir.`,sik_aciklamalari:{A:`Bazaloid karsinom HPV ilişkili malign tümördür.`,B:`VIN prekanseröz neoplastik bir lezyondur.`,C:`Paget hastalığı intraepidermal neoplastik süreçtir.`,D:`Doğru: liken skleroz non-neoplastik bir dermatozdur.`,E:`Keratinize SCC HPV negatif malign tümördür.`},bilgi:[9],benzer_cikmis:[]},{id:`k1-48-q05`,kazanim:2,zorluk:`orta`,soru:`Skuamöz hücre hiperplazisini neoplastik bir süreçten ayırmada en önemli histolojik özellik hangisidir?`,secenekler:{A:`Hiperkeratoz varlığı`,B:`Mitotik aktivite artışına rağmen sitolojik atipi bulunmaması`,C:`Akantoz varlığı`,D:`Dermiste lenfosit infiltrasyonu`,E:`Lökoplaki görünümü`},dogru:`B`,aciklama:`Skuamöz hücre hiperplazisinde akantoz, hiperkeratoz ve artmış mitoz vardır; sitolojik atipinin olmaması maligniteyi dışlar.`,sik_aciklamalari:{A:`Hiperkeratoz neoplastik lezyonlarda da görülebilir.`,B:`Doğru: atipi yokluğu benign/non-neoplastik doğayı gösterir.`,C:`Akantoz tek başına ayırt edici değildir.`,D:`Lenfosit infiltrasyonu spesifik değildir.`,E:`Lökoplaki hem benign hem malign lezyonlarda görülür.`},bilgi:[15,16],benzer_cikmis:[`f17c4ebee26c`,`75e2de21b0ba`]},{id:`k1-48-q06`,kazanim:2,zorluk:`zor`,soru:`Aşağıdaki vulvar lezyonlardan hangisi prekanseröz (neoplastik ön) lezyon olarak kabul edilir?`,secenekler:{A:`Kondiloma akuminatum`,B:`Liken skleroz`,C:`Skuamöz hücre hiperplazisi`,D:`Diferansiye vulvar intraepitelyal neoplazi (dVIN)`,E:`Bartholin kisti`},dogru:`D`,aciklama:`dVIN HPV negatif keratinize SCC'nin ön lezyonudur; liken skleroz karsinom riskini biraz artırsa da prekanseröz değildir.`,sik_aciklamalari:{A:`Vulvar kondilomlar kansere dönüşmez.`,B:`Liken skleroz risk artırır ancak prekanseröz lezyon değildir.`,C:`Skuamöz hücre hiperplazisi atipisizdir ve non-neoplastiktir.`,D:`Doğru: dVIN tedavi edilmezse keratinize SCC'ye ilerler.`,E:`Bartholin kisti tıkanmaya bağlı benign lezyondur.`},bilgi:[13,21,26],benzer_cikmis:[`08150f2de419`]},{id:`k1-48-vulva-vajen-ve-serviks-hastaliklari-k02-q04`,kazanim:2,zorluk:`orta`,soru:`Vulvar beyaz plaklı hastada biyopside atipi araştırılıyor. Aşağıdakilerden hangisi non-neoplastik epitel bozukluğudur?`,secenekler:{A:`Diferansiye VIN`,B:`Klasik VIN`,C:`Liken skleroz ve skuamöz hücre hiperplazisi (atipisiz)`,D:`Karsinoma in situ`,E:`İnvaziv skuamöz karsinom`},dogru:`C`,aciklama:`Liken skleroz ve skuamöz hiperplazi atipisiz non-neoplastik tablolardır.`,sik_aciklamalari:{A:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Liken skleroz ve skuamöz hücre hiperplazisi (atipisiz)' seçeneğidir.`,B:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Liken skleroz ve skuamöz hücre hiperplazisi (atipisiz)' seçeneğidir.`,C:`Doğru: Liken skleroz ve skuamöz hiperplazi atipisiz non-neoplastik tablolardır.`,D:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Liken skleroz ve skuamöz hücre hiperplazisi (atipisiz)' seçeneğidir.`,E:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Liken skleroz ve skuamöz hücre hiperplazisi (atipisiz)' seçeneğidir.`},bilgi:[9,15],benzer_cikmis:[]},{id:`k1-48-vulva-vajen-ve-serviks-hastaliklari-k02-q05`,kazanim:2,zorluk:`zor`,soru:`Skuamöz hiperplaziyi neoplaziden ayıran histoloji soruluyor. Aşağıdakilerden hangisi yanlıştır?`,secenekler:{A:`Skuamöz hiperplazide akantoz ve hiperkeratoz vardır ancak sitolojik atipi yoktur`,B:`Atipi yokluğu benign/non-neoplastik doğayı destekler`,C:`Liken skleroz prekanseröz değildir`,D:`Atipi yokluğu maligniteyi kanıtlar ve dVIN atipisizdir`,E:`Mitoz artışı atipi olmadan görülebilir`},dogru:`A`,aciklama:`Atipi yokluğu benign lehinedir; dVIN'de bazal atipi vardır.`,sik_aciklamalari:{A:`Doğru: Atipi yokluğu benign lehinedir; dVIN'de bazal atipi vardır.`,B:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Skuamöz hiperplazide akantoz ve hiperkeratoz vardır ancak sitolojik atipi yoktur' seçeneğidir.`,C:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Skuamöz hiperplazide akantoz ve hiperkeratoz vardır ancak sitolojik atipi yoktur' seçeneğidir.`,D:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Skuamöz hiperplazide akantoz ve hiperkeratoz vardır ancak sitolojik atipi yoktur' seçeneğidir.`,E:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Skuamöz hiperplazide akantoz ve hiperkeratoz vardır ancak sitolojik atipi yoktur' seçeneğidir.`},bilgi:[11,13,15,26],benzer_cikmis:[]},{id:`k1-48-vulva-vajen-ve-serviks-hastaliklari-k02-q06`,kazanim:2,zorluk:`orta`,soru:`Vulvada non-neoplastik epitel bozuklukları hangileridir?`,secenekler:{A:`Liken skleroz ve skuamöz hiperplazi non-neoplastiktir`,B:`Klasik VIN non-neoplastik inflamasyondur`,C:`Karsinoma in situ benign hiperplazidir`,D:`İnvaziv karsinom non-neoplastik lezyondur`,E:`Diferansiye VIN atipisiz benignitedir`},dogru:`A`,aciklama:`Liken skleroz ve skuamöz hücre hiperplazisi atipisiz non-neoplastik epitel bozukluklarıdır. VIN, karsinoma in situ ve invaziv karsinom ise neoplastik spektrumdadır. Ayrım sitolojik atipi varlığına dayanır.`,sik_aciklamalari:{A:`Doğru: Her ikisi de atipisiz benign epitel bozukluğudur.`,B:`Yanlış: Klasik VIN neoplastik intraepiteliyal lezyondur.`,C:`Yanlış: CIS tam kat atipili preinvaziv neoplazidir.`,D:`Yanlış: İnvaziv karsinom malign neoplazidir.`,E:`Yanlış: dVIN bazal atipi taşıyan prekürsördür.`},bilgi:[9],benzer_cikmis:[]},{id:`k1-48-vulva-vajen-ve-serviks-hastaliklari-k02-q07`,kazanim:2,zorluk:`orta`,soru:`Skuamöz hiperplaziyi neoplaziden ayıran histolojik ölçüt nedir?`,secenekler:{A:`Atipi yokluğu maligniteyi kanıtlar`,B:`dVIN atipisiz benign lezyondur`,C:`Atipi yokluğu benign lehinedir; dVIN bazal atipilidir`,D:`Akantoz varlığı invazyonu gösterir`,E:`Hiperkeratoz tek başına karsinomdur`},dogru:`C`,aciklama:`Skuamöz hiperplazide akantoz ve hiperkeratoz vardır ancak sitolojik atipi yoktur; atipi yokluğu benign doğayı destekler. Diferansiye VIN'de ise bazal tabakaya sınırlı atipi bulunur. Mitoz artışı atipi olmadan benign tabloda görülebilir.`,sik_aciklamalari:{A:`Yanlış: Atipi yokluğu benign lehine bulgudur.`,B:`Yanlış: dVIN bazal atipi içeren prekürsördür.`,C:`Doğru: Sitolojik atipi neoplastik ayrımın ölçütüdür.`,D:`Yanlış: Akantoz epidermal kalınlaşmadır, invazyon değildir.`,E:`Yanlış: Hiperkeratoz benign tablolarda da görülür.`},bilgi:[15,26],benzer_cikmis:[]},{id:`k1-48-vulva-vajen-ve-serviks-hastaliklari-k02-q08`,kazanim:2,zorluk:`kolay`,soru:`"Ekstramammary Paget: klinik, histoloji, seyir" kavramının tanımı aşağıdakilerden hangisidir?`,secenekler:{D:`Klinikte kırmızı, pullu, kabuklu plak kronik dermatiti taklit eder; histolojide büyük hücreler, bol soluk ince granüllü sitoplazma ve epidermiste tek tek/gruplar halinde hücreler vardır; invazyon veya metastaz olmaksızın yıllarca sürebilir.`,E:`Kronik, sklerozan dermatozdur; düz beyaz plaklar veya papüller (lökoplaki) görülür, zamanla genişler ve birleşir, vajinal açıklık daralabilir, labialar atrofik ve sert hale gelir.`,B:`İki temel tablo liken skleroz ve skuamöz hücre hiperplazisidir; klinik olarak genellikle lökoplaki şeklinde görülürler.`,A:`Yetişkinlerde nadiren primer hastalık yeridir; daha sık komşu organ kanserlerinin (serviks, mesane, rektum) sekonder tutulumu görülür. Nadir konjenital anomaliler: vajinanın tam yokluğu, septalı veya çift vajina.`,C:`HSV-1 ve HSV-2 genital herpes etkenidir; ağrılı vezikül ve ülserler ile tekrarlayıcı seyir yapar.`},dogru:`D`,aciklama:`Doğru: Klinikte kırmızı, pullu, kabuklu plak kronik dermatiti taklit eder; histolojide büyük hücreler, bol soluk ince granüllü sitoplazma ve epidermiste tek tek/gruplar halinde hücreler vardır; invazyon veya metastaz olmaksızın yıllarca sürebilir.`,sik_aciklamalari:{D:`Doğru. Klinikte kırmızı, pullu, kabuklu plak kronik dermatiti taklit eder; histolojide büyük hücreler, bol soluk ince granüllü sitoplazma ve epidermiste tek tek/gruplar halinde hücreler vardır; invazyon veya metastaz olmaksızın yıllarca sürebilir.`,E:`Yanlış. Kronik, sklerozan dermatozdur; düz beyaz plaklar veya papüller (lökoplaki) görülür, zamanla genişler ve birleşir, vajinal açıklık daralabilir, labialar atrofik ve sert hale gelir.`,B:`Yanlış. İki temel tablo liken skleroz ve skuamöz hücre hiperplazisidir; klinik olarak genellikle lökoplaki şeklinde görülürler.`,A:`Yanlış. Yetişkinlerde nadiren primer hastalık yeridir; daha sık komşu organ kanserlerinin (serviks, mesane, rektum) sekonder tutulumu görülür. Nadir konjenital anomaliler: vajinanın tam yokluğu, septalı veya çift vajina.`,C:`Yanlış. HSV-1 ve HSV-2 genital herpes etkenidir; ağrılı vezikül ve ülserler ile tekrarlayıcı seyir yapar.`},bilgi:[30],benzer_cikmis:[]},{id:`k1-48-vulva-vajen-ve-serviks-hastaliklari-k02-q09`,kazanim:2,zorluk:`orta`,soru:`"Gardnerella vaginalis ve bakteriyel vajinoz" ile ilgili eşleştirmelerden hangisi doğrudur?`,secenekler:{E:`Gram negatif kokobasildir ve bakteriyel vajinozun ana nedenidir; ince, gri beyaz, kötü kokulu akıntı ve 'balık kokusu' şikayeti görülür.`,A:`Genellikle yaşlı kadınlarda (ortalama yaş ~75), uzun süreli liken skleroz ve skuamöz hücre hiperplazisi zemininde görülür ve HPV ile ilişkili değildir; ön lezyonu dVIN'dir (bazal tabakaya sınırlı anormal keratinizasyon ve sitolojik atipi).`,B:`Uzun süre lokal kalma eğilimi vardır; ilk yayılım bölgesel lenf düğümlerine, ileri evrede akciğer ve diğer organlara hematogen metastaz olur.`,C:`Genital organların siğil benzeri lezyonlarıdır; cinsel yolla bulaşan iki temel formu kondiloma lata ve kondiloma akuminatumdur.`,D:`Reaktif inflamasyon alerjen veya irritan temasına yanıttır; losyon ve sabun katkı maddeleri, antiseptikler ve giysi kimyasalları rol oynar.`},dogru:`E`,aciklama:`Doğru: Gram negatif kokobasildir ve bakteriyel vajinozun ana nedenidir; ince, gri beyaz, kötü kokulu akıntı ve 'balık kokusu' şikayeti görülür.`,sik_aciklamalari:{E:`Doğru. Gram negatif kokobasildir ve bakteriyel vajinozun ana nedenidir; ince, gri beyaz, kötü kokulu akıntı ve 'balık kokusu' şikayeti görülür.`,A:`Yanlış. Genellikle yaşlı kadınlarda (ortalama yaş ~75), uzun süreli liken skleroz ve skuamöz hücre hiperplazisi zemininde görülür ve HPV ile ilişkili değildir; ön lezyonu dVIN'dir (bazal tabakaya sınırlı anormal keratinizasyon ve sitolojik atipi).`,B:`Yanlış. Uzun süre lokal kalma eğilimi vardır; ilk yayılım bölgesel lenf düğümlerine, ileri evrede akciğer ve diğer organlara hematogen metastaz olur.`,C:`Yanlış. Genital organların siğil benzeri lezyonlarıdır; cinsel yolla bulaşan iki temel formu kondiloma lata ve kondiloma akuminatumdur.`,D:`Yanlış. Reaktif inflamasyon alerjen veya irritan temasına yanıttır; losyon ve sabun katkı maddeleri, antiseptikler ve giysi kimyasalları rol oynar.`},bilgi:[36],benzer_cikmis:[]},{id:`k1-48-vulva-vajen-ve-serviks-hastaliklari-k02-q10`,kazanim:2,zorluk:`orta`,soru:`"Liken skleroz: onkolojik risk" ile ilgili eşleştirmelerden hangisi doğrudur?`,secenekler:{C:`Vulvar skuamöz hücreli karsinom riski biraz artmıştır ancak liken skleroz prekanseröz lezyon değildir.`,A:`Tüm kadın genital sistem kanserlerinin ~%3'ü; 60 yaş üstü kadınlarda görülür; histolojik tiplerin ~%90'ı skuamöz hücreli karsinom, diğerleri adenokarsinom ve bazal hücreli karsinomdur.`,E:`Dünya çapında en yaygın viral olmayan cinsel yolla bulaşan enfeksiyondur; çoğu enfeksiyon asemptomatiktir.`,B:`Genellikle yaşlı kadınlarda (ortalama yaş ~75), uzun süreli liken skleroz ve skuamöz hücre hiperplazisi zemininde görülür ve HPV ile ilişkili değildir; ön lezyonu dVIN'dir (bazal tabakaya sınırlı anormal keratinizasyon ve sitolojik atipi).`,D:`Vajinanın inflamatuar durumudur; genellikle enfeksiyona bağlı ve geçicidir, temel bulgu vajinal akıntıdır (lökore). Etkenler bakteri, mantar, parazit olup pek çoğu normal kommensal flora üyesidir.`},dogru:`C`,aciklama:`Doğru: Vulvar skuamöz hücreli karsinom riski biraz artmıştır ancak liken skleroz prekanseröz lezyon değildir.`,sik_aciklamalari:{C:`Doğru. Vulvar skuamöz hücreli karsinom riski biraz artmıştır ancak liken skleroz prekanseröz lezyon değildir.`,A:`Yanlış. Tüm kadın genital sistem kanserlerinin ~%3'ü; 60 yaş üstü kadınlarda görülür; histolojik tiplerin ~%90'ı skuamöz hücreli karsinom, diğerleri adenokarsinom ve bazal hücreli karsinomdur.`,E:`Yanlış. Dünya çapında en yaygın viral olmayan cinsel yolla bulaşan enfeksiyondur; çoğu enfeksiyon asemptomatiktir.`,B:`Yanlış. Genellikle yaşlı kadınlarda (ortalama yaş ~75), uzun süreli liken skleroz ve skuamöz hücre hiperplazisi zemininde görülür ve HPV ile ilişkili değildir; ön lezyonu dVIN'dir (bazal tabakaya sınırlı anormal keratinizasyon ve sitolojik atipi).`,D:`Yanlış. Vajinanın inflamatuar durumudur; genellikle enfeksiyona bağlı ve geçicidir, temel bulgu vajinal akıntıdır (lökore). Etkenler bakteri, mantar, parazit olup pek çoğu normal kommensal flora üyesidir.`},bilgi:[13],benzer_cikmis:[]},{id:`k1-48-vulva-vajen-ve-serviks-hastaliklari-k02-q11`,kazanim:2,zorluk:`zor`,soru:`"Gardnerella vaginalis ve bakteriyel vajinoz" ile ilgili bir hastada bulunacak aşağıdaki bulgulardan hangisi beklenmez?`,secenekler:{C:`Gram negatif kokobasildir ve bakteriyel vajinozun ana nedenidir; ince, gri beyaz, kötü kokulu akıntı ve 'balık kokusu' şikayeti görülür.`,D:`1) Bazaloid/siğil benzeri karsinom yüksek riskli HPV ile ilişkilidir. 2) Keratinize skuamöz hücreli karsinom HPV ile ilişkili değildir ve liken skleroz veya skuamöz hücre hiperplazisi zemininde gelişir.`,B:`Sekonder sifilizde görülür; etkeni Treponema pallidum'dur, düz hafif kabarık lezyonlar yapar.`,A:`Lökoplaki yapabilen benign hastalıklar psoriasis ve liken planus; neoplastik lezyonlar skuamöz hücreli karsinoma in situ ve invaziv skuamöz hücreli karsinomdur.`,E:`Skuamöz hücreli karsinomun öncü lezyonudur ve displazi derecesine göre sınıflanır.`},dogru:`C`,aciklama:`Doğru: Gram negatif kokobasildir ve bakteriyel vajinozun ana nedenidir; ince, gri beyaz, kötü kokulu akıntı ve 'balık kokusu' şikayeti görülür.`,sik_aciklamalari:{C:`Doğru. Gram negatif kokobasildir ve bakteriyel vajinozun ana nedenidir; ince, gri beyaz, kötü kokulu akıntı ve 'balık kokusu' şikayeti görülür.`,D:`Yanlış. 1) Bazaloid/siğil benzeri karsinom yüksek riskli HPV ile ilişkilidir. 2) Keratinize skuamöz hücreli karsinom HPV ile ilişkili değildir ve liken skleroz veya skuamöz hücre hiperplazisi zemininde gelişir.`,B:`Yanlış. Sekonder sifilizde görülür; etkeni Treponema pallidum'dur, düz hafif kabarık lezyonlar yapar.`,A:`Yanlış. Lökoplaki yapabilen benign hastalıklar psoriasis ve liken planus; neoplastik lezyonlar skuamöz hücreli karsinoma in situ ve invaziv skuamöz hücreli karsinomdur.`,E:`Yanlış. Skuamöz hücreli karsinomun öncü lezyonudur ve displazi derecesine göre sınıflanır.`},bilgi:[36],benzer_cikmis:[]}],ilgili_cikmis:[{id:`f17c4ebee26c`,soru:`Vulva, vagen ve servik patolojisi lökoplaki ön tanısıyla biopsi alınan vulvanın nonneoplastik hastalıklarından liken simpleks kronikustabeklenmez?`,secenekler:{A:`No`,B:`Bazal ve suprabazal tabakada artmış mitotik aktivite`,C:`Epidermiste incelme`,D:`Bazal dermiste lökositik infiltrasyon`,E:`Hiperkeratoz`},cevap:`A`},{id:`75e2de21b0ba`,soru:`Lökoplaki ön tanısıyla biopsi alınan vulvanın nonneoplastik hastalığından liken simpleks kronikustabeklenmez?`,secenekler:{A:`Bazal ve suprabazal tabakada artmış mitotik aktivite`,B:`Epidermiste incelme`,C:`Bazal dermiste lökositik infiltrasyon`,D:`Hiperkeratoz`,E:`Epitelyal atipi izlenmemesi`},cevap:`E`},{id:`08150f2de419`,soru:`Vulva, vagen ve servik patolojisi için aşağıdakilerden hangileri malign transformasyon açısından düşük risk grubundadır?`,secenekler:{A:`I-II`,B:`I-III`,C:`II-IV`,D:`II-III`,E:`III-IV`},cevap:`E`}]},{no:3,metin:`HPV ilişkili ve ilişkisiz tümörleri vurgulayabilmek`,sorular:[{id:`k1-48-q07`,kazanim:3,zorluk:`kolay`,soru:`Kondiloma akuminatumun etkeni hangisidir?`,secenekler:{A:`Treponema pallidum`,B:`Yüksek riskli HPV tip 16`,C:`Düşük riskli HPV tip 6 ve 11`,D:`HSV-2`,E:`Candida albicans`},dogru:`C`,aciklama:`Kondiloma akuminatum düşük riskli HPV 6 ve 11 ile oluşur; cinsel temasla bulaşır.`,sik_aciklamalari:{A:`T. pallidum kondiloma lataya yol açar.`,B:`HPV 16 HPV pozitif vulvar karsinom ve VIN ile ilişkilidir.`,C:`Doğru: düşük riskli tipler siğil yapar.`,D:`HSV-2 ağrılı vezikül ve ülser yapar.`,E:`Candida vulvovajinit yapar.`},bilgi:[19],benzer_cikmis:[]},{id:`k1-48-q08`,kazanim:3,zorluk:`orta`,soru:`HPV ile ilişkili ve ilişkisiz vulvar karsinom karşılaştırıldığında hangisi doğrudur?`,secenekler:{A:`HPV negatif tümör VIN zemininde gelişir`,B:`HPV pozitif tümör bazaloid/siğil benzeri, HPV negatif tümör keratinize skuamöz hücreli karsinomdur`,C:`HPV pozitif tümör liken skleroz zemininde gelişir`,D:`Her iki grup da aynı yaş ve prognoza sahiptir`,E:`HPV negatif tümör HPV tip 16 ile ilişkilidir`},dogru:`B`,aciklama:`Bazaloid/siğil benzeri karsinom yüksek riskli HPV ile, keratinize SCC ise liken skleroz/skuamöz hiperplazi zemininde HPV'den bağımsız gelişir.`,sik_aciklamalari:{A:`HPV negatif tümörün öncülü dVIN'dir.`,B:`Doğru: iki grubun morfolojisi doğru verilmiştir.`,C:`Liken skleroz zemini HPV negatif gruba aittir.`,D:`Yaş, zemin ve prognozları farklıdır.`,E:`HPV 16 HPV pozitif grupla ilişkilidir.`},bilgi:[23,24,26],benzer_cikmis:[]},{id:`k1-48-q09`,kazanim:3,zorluk:`zor`,soru:`Aşağıdaki genital sistem lezyonlarından hangisi HPV ile ilişkili değildir?`,secenekler:{A:`Vajinal skuamöz hücreli karsinom`,B:`Vulvar intraepitelyal neoplazi (klasik)`,C:`Servikal skuamöz hücreli karsinom`,D:`Uzun süreli liken skleroz zemininde gelişen keratinize vulvar SCC`,E:`Kondiloma akuminatum`},dogru:`D`,aciklama:`Liken skleroz zemininde gelişen keratinize vulvar SCC HPV'den bağımsızdır; diğerleri HPV ilişkilidir.`,sik_aciklamalari:{A:`Primer vajinal SCC'lerin neredeyse tamamı yüksek riskli HPV ile ilişkilidir.`,B:`Klasik VIN yüksek riskli HPV ile ilişkilidir.`,C:`Servikal SCC'nin HPV ilişkisi belirgindir.`,D:`Doğru: HPV negatif yol dVIN üzerinden ilerler.`,E:`Kondiloma HPV 6/11 ile oluşur.`},bilgi:[19,23,25,26,38,40],benzer_cikmis:[]},{id:`k1-48-vulva-vajen-ve-serviks-hastaliklari-k03-q04`,kazanim:3,zorluk:`orta`,soru:`Vulvar siğilli genç hasta ile liken sklerozlu yaşlı hastanın tümör riski karşılaştırılıyor. Aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`Tüm vulvar tümörler HPV ile ilişkilidir`,B:`Hiçbir vulvar tümör HPV ile ilişkili değildir`,C:`Kondilom yüksek riskli HPV yapar`,D:`Keratinize SCC HPV 16 ile oluşur`,E:`Kondiloma akuminatum düşük riskli HPV 6/11 ile oluşur; bazaloid/siğil benzeri karsinom yüksek riskli HPV ile, keratinize SCC HPV'den bağımsız gelişir`},dogru:`E`,aciklama:`HPV ilişkili (bazaloid) ve ilişkisiz (keratinize) iki yol vardır.`,sik_aciklamalari:{A:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Kondiloma akuminatum düşük riskli HPV 6/11 ile oluşur; bazaloid/siğil benzeri karsinom yüksek riskli HPV ile, keratinize SCC HPV'den bağımsız gelişir' seçeneğidir.`,B:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Kondiloma akuminatum düşük riskli HPV 6/11 ile oluşur; bazaloid/siğil benzeri karsinom yüksek riskli HPV ile, keratinize SCC HPV'den bağımsız gelişir' seçeneğidir.`,C:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Kondiloma akuminatum düşük riskli HPV 6/11 ile oluşur; bazaloid/siğil benzeri karsinom yüksek riskli HPV ile, keratinize SCC HPV'den bağımsız gelişir' seçeneğidir.`,D:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Kondiloma akuminatum düşük riskli HPV 6/11 ile oluşur; bazaloid/siğil benzeri karsinom yüksek riskli HPV ile, keratinize SCC HPV'den bağımsız gelişir' seçeneğidir.`,E:`Doğru: HPV ilişkili (bazaloid) ve ilişkisiz (keratinize) iki yol vardır.`},bilgi:[19,23,26],benzer_cikmis:[]},{id:`k1-48-vulva-vajen-ve-serviks-hastaliklari-k03-q05`,kazanim:3,zorluk:`zor`,soru:`Hangisinin HPV ile ilişkisiz olduğu soruluyor. Aşağıdakilerden hangisi yanlıştır?`,secenekler:{A:`Klasik VIN yüksek riskli HPV ile ilişkilidir`,B:`Servikal SCC HPV ile güçlü ilişkilidir`,C:`Liken skleroz zeminli keratinize vulvar SCC HPV 16 ile oluşur ve kondilom kansere dönüşür`,D:`Primer vajinal SCC'ler yüksek riskli HPV ile ilişkilidir`,E:`Kondiloma HPV 6/11 ile oluşur`},dogru:`D`,aciklama:`Keratinize yol HPV'den bağımsızdır; kondilom kansere dönüşmez.`,sik_aciklamalari:{A:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Primer vajinal SCC'ler yüksek riskli HPV ile ilişkilidir' seçeneğidir.`,B:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Primer vajinal SCC'ler yüksek riskli HPV ile ilişkilidir' seçeneğidir.`,C:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Primer vajinal SCC'ler yüksek riskli HPV ile ilişkilidir' seçeneğidir.`,D:`Doğru: Keratinize yol HPV'den bağımsızdır; kondilom kansere dönüşmez.`,E:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Primer vajinal SCC'ler yüksek riskli HPV ile ilişkilidir' seçeneğidir.`},bilgi:[19,23,24,26,38,40],benzer_cikmis:[]},{id:`k1-48-vulva-vajen-ve-serviks-hastaliklari-k03-q06`,kazanim:3,zorluk:`orta`,soru:`Vulvar lezyonlarda HPV ilişkisine göre ayrım nasıldır?`,secenekler:{A:`Tüm vulvar tümörler HPV ile ilişkilidir`,B:`Hiçbir vulvar tümör HPV ile ilişkili değildir`,C:`Kondilom yüksek riskli HPV ile oluşur`,D:`Keratinize karsinom HPV 16 ile oluşur`,E:`Kondilom tip 6-11; keratinize yol HPV bağımsızdır`},dogru:`E`,aciklama:`Kondiloma akuminatum düşük riskli HPV 6 ve 11'e bağlı papiller siğildir. Bazaloid ve siğil benzeri vulvar karsinomlar yüksek riskli HPV ile, keratinize skuamöz karsinom ise HPV'den bağımsız gelişir. İki ayrı onkojenik yol vardır.`,sik_aciklamalari:{A:`Yanlış: Keratinize yol HPV'den bağımsızdır.`,B:`Yanlış: Bazaloid yol yüksek riskli HPV'lidir.`,C:`Yanlış: Kondilom düşük riskli tiplerle oluşur.`,D:`Yanlış: Keratinize karsinom HPV ilişkisizdir.`,E:`Doğru: Düşük risk siğil, yüksek risk bazaloid, bağımsız keratinize yol vardır.`},bilgi:[5,19,23],benzer_cikmis:[]},{id:`k1-48-vulva-vajen-ve-serviks-hastaliklari-k03-q07`,kazanim:3,zorluk:`orta`,soru:`HPV'den bağımsız gelişen vulvar tümör yolu hangisidir?`,secenekler:{A:`Klasik VIN HPV'den bağımsızdır`,B:`Keratinize karsinom HPV bağımsız; kondilom dönüşmez`,C:`Servikal karsinom HPV ile ilişkisizdir`,D:`Kondilom doğrudan kansere dönüşür`,E:`Vajinal SCC düşük riskli HPV'lidir`},dogru:`B`,aciklama:`Klasik VIN yüksek riskli HPV ile ilişkilidir; primer vajinal skuamöz karsinomlar da yüksek riskli HPV'lidir. Liken skleroz zeminli keratinize karsinom HPV'den bağımsızdır. Kondiloma akuminatum kansere dönüşmez.`,sik_aciklamalari:{A:`Yanlış: Klasik VIN yüksek riskli HPV ile ilişkilidir.`,B:`Doğru: Keratinize yol bağımsızdır; kondilom benign siğildir.`,C:`Yanlış: Servikal SCC güçlü HPV ilişkilidir.`,D:`Yanlış: Kondilom prekanseröz değildir.`,E:`Yanlış: Vajinal SCC yüksek riskli HPV'lidir.`},bilgi:[19,23,38],benzer_cikmis:[]},{id:`k1-48-vulva-vajen-ve-serviks-hastaliklari-k03-q08`,kazanim:3,zorluk:`kolay`,soru:`"Liken skleroz: klinik" kavramının tanımı aşağıdakilerden hangisidir?`,secenekler:{B:`Kronik, sklerozan dermatozdur; düz beyaz plaklar veya papüller (lökoplaki) görülür, zamanla genişler ve birleşir, vajinal açıklık daralabilir, labialar atrofik ve sert hale gelir.`,C:`Atipik epitel hücrelerinin intraepidermal proliferasyonudur; vulva derisi (ekstramammary Paget) veya meme ucu derisinde görülür. Olası köken vulva derisi kanallarındaki multipotent hücrelerdir.`,D:`Papiller ekzofitik stromal çekirdekler, üzerinde kalınlaşmış skuamöz epitel ve viral sitopatik değişiklikler (koilositik atipi, büyümüş buruşuk çekirdek, hiperkromazi, sitoplazmik perinükleer halo) vardır.`,A:`Son derece nadirdir; neredeyse tüm primer karsinomlar yüksek riskli HPV ile ilişkili skuamöz hücreli karsinomdur; en büyük risk faktörü daha önce serviks veya vulva karsinomu öyküsüdür.`,E:`Vulvit vulvanın inflamasyonudur; sık görülen, çok nedenli bir durumdur ve sıklıkla yoğun kaşıntı ile seyreder.`},dogru:`B`,aciklama:`Doğru: Kronik, sklerozan dermatozdur; düz beyaz plaklar veya papüller (lökoplaki) görülür, zamanla genişler ve birleşir, vajinal açıklık daralabilir, labialar atrofik ve sert hale gelir.`,sik_aciklamalari:{B:`Doğru. Kronik, sklerozan dermatozdur; düz beyaz plaklar veya papüller (lökoplaki) görülür, zamanla genişler ve birleşir, vajinal açıklık daralabilir, labialar atrofik ve sert hale gelir.`,C:`Yanlış. Atipik epitel hücrelerinin intraepidermal proliferasyonudur; vulva derisi (ekstramammary Paget) veya meme ucu derisinde görülür. Olası köken vulva derisi kanallarındaki multipotent hücrelerdir.`,D:`Yanlış. Papiller ekzofitik stromal çekirdekler, üzerinde kalınlaşmış skuamöz epitel ve viral sitopatik değişiklikler (koilositik atipi, büyümüş buruşuk çekirdek, hiperkromazi, sitoplazmik perinükleer halo) vardır.`,A:`Yanlış. Son derece nadirdir; neredeyse tüm primer karsinomlar yüksek riskli HPV ile ilişkili skuamöz hücreli karsinomdur; en büyük risk faktörü daha önce serviks veya vulva karsinomu öyküsüdür.`,E:`Yanlış. Vulvit vulvanın inflamasyonudur; sık görülen, çok nedenli bir durumdur ve sıklıkla yoğun kaşıntı ile seyreder.`},bilgi:[10],benzer_cikmis:[]},{id:`k1-48-vulva-vajen-ve-serviks-hastaliklari-k03-q09`,kazanim:3,zorluk:`orta`,soru:`"Ekstramammary Paget: klinik, histoloji, seyir" ile ilgili eşleştirmelerden hangisi doğrudur?`,secenekler:{C:`Klinikte kırmızı, pullu, kabuklu plak kronik dermatiti taklit eder; histolojide büyük hücreler, bol soluk ince granüllü sitoplazma ve epidermiste tek tek/gruplar halinde hücreler vardır; invazyon veya metastaz olmaksızın yıllarca sürebilir.`,A:`Dünya çapında en yaygın viral olmayan cinsel yolla bulaşan enfeksiyondur; çoğu enfeksiyon asemptomatiktir.`,B:`Yetişkinlerde nadiren primer hastalık yeridir; daha sık komşu organ kanserlerinin (serviks, mesane, rektum) sekonder tutulumu görülür. Nadir konjenital anomaliler: vajinanın tam yokluğu, septalı veya çift vajina.`,D:`Reaktif inflamasyon alerjen veya irritan temasına yanıttır; losyon ve sabun katkı maddeleri, antiseptikler ve giysi kimyasalları rol oynar.`,E:`Son derece nadirdir; neredeyse tüm primer karsinomlar yüksek riskli HPV ile ilişkili skuamöz hücreli karsinomdur; en büyük risk faktörü daha önce serviks veya vulva karsinomu öyküsüdür.`},dogru:`C`,aciklama:`Doğru: Klinikte kırmızı, pullu, kabuklu plak kronik dermatiti taklit eder; histolojide büyük hücreler, bol soluk ince granüllü sitoplazma ve epidermiste tek tek/gruplar halinde hücreler vardır; invazyon veya metastaz olmaksızın yıllarca sürebilir.`,sik_aciklamalari:{C:`Doğru. Klinikte kırmızı, pullu, kabuklu plak kronik dermatiti taklit eder; histolojide büyük hücreler, bol soluk ince granüllü sitoplazma ve epidermiste tek tek/gruplar halinde hücreler vardır; invazyon veya metastaz olmaksızın yıllarca sürebilir.`,A:`Yanlış. Dünya çapında en yaygın viral olmayan cinsel yolla bulaşan enfeksiyondur; çoğu enfeksiyon asemptomatiktir.`,B:`Yanlış. Yetişkinlerde nadiren primer hastalık yeridir; daha sık komşu organ kanserlerinin (serviks, mesane, rektum) sekonder tutulumu görülür. Nadir konjenital anomaliler: vajinanın tam yokluğu, septalı veya çift vajina.`,D:`Yanlış. Reaktif inflamasyon alerjen veya irritan temasına yanıttır; losyon ve sabun katkı maddeleri, antiseptikler ve giysi kimyasalları rol oynar.`,E:`Yanlış. Son derece nadirdir; neredeyse tüm primer karsinomlar yüksek riskli HPV ile ilişkili skuamöz hücreli karsinomdur; en büyük risk faktörü daha önce serviks veya vulva karsinomu öyküsüdür.`},bilgi:[30],benzer_cikmis:[]},{id:`k1-48-vulva-vajen-ve-serviks-hastaliklari-k03-q10`,kazanim:3,zorluk:`orta`,soru:`"Non-neoplastik epitel bozuklukları" kavramı hakkında verilen aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`İki temel tablo liken skleroz ve skuamöz hücre hiperplazisidir; klinik olarak genellikle lökoplaki şeklinde görülürler.`,E:`Vulvar kondilomlar kansere dönüşmez ancak vajina ve servikste HPV ilişkili prekanseröz lezyon riski artar.`,C:`Sekonder sifilizde görülür; etkeni Treponema pallidum'dur, düz hafif kabarık lezyonlar yapar.`,B:`HPV pozitif tümörler sıklıkla multifokal, siğil benzeri ve genellikle kötü diferansiye; HPV negatif tümörler genellikle unifokal ve iyi diferansiye, keratinize skuamöz hücreli karsinomdur.`,D:`Servikal lezyonların çoğu inflamatuvar (servisit) niteliktedir; servikal skuamöz hücreli karsinom dünya çapında kadınlarda en sık görülen kanserlerden biridir ve HPV ilişkisi belirgindir.`},dogru:`A`,aciklama:`Doğru: İki temel tablo liken skleroz ve skuamöz hücre hiperplazisidir; klinik olarak genellikle lökoplaki şeklinde görülürler.`,sik_aciklamalari:{A:`Doğru. İki temel tablo liken skleroz ve skuamöz hücre hiperplazisidir; klinik olarak genellikle lökoplaki şeklinde görülürler.`,E:`Yanlış. Vulvar kondilomlar kansere dönüşmez ancak vajina ve servikste HPV ilişkili prekanseröz lezyon riski artar.`,C:`Yanlış. Sekonder sifilizde görülür; etkeni Treponema pallidum'dur, düz hafif kabarık lezyonlar yapar.`,B:`Yanlış. HPV pozitif tümörler sıklıkla multifokal, siğil benzeri ve genellikle kötü diferansiye; HPV negatif tümörler genellikle unifokal ve iyi diferansiye, keratinize skuamöz hücreli karsinomdur.`,D:`Yanlış. Servikal lezyonların çoğu inflamatuvar (servisit) niteliktedir; servikal skuamöz hücreli karsinom dünya çapında kadınlarda en sık görülen kanserlerden biridir ve HPV ilişkisi belirgindir.`},bilgi:[9],benzer_cikmis:[]},{id:`k1-48-vulva-vajen-ve-serviks-hastaliklari-k03-q11`,kazanim:3,zorluk:`zor`,soru:`"Liken skleroz: epidemiyoloji ve patogenez" ile ilgili bir hastada bulunacak aşağıdaki bulgulardan hangisi beklenmez?`,secenekler:{D:`Her yaşta görülebilir (menopoz sonrası kadınlar, ergenlik öncesi kızlar); patogenezi belirsizdir, subepiteliyal aktif T hücre infiltrasyonu ve otoimmün bozukluklarla birliktelik vardır.`,E:`HPV kondiloma akuminatum etkenidir, VIN ile ilişkilidir ve vulvar skuamöz karsinom alt kümesinde rol oynar.`,B:`Bartholin bezi salgı kanalı tıkanması ağrılı gland genişlemesi (Bartholin kisti) ve sıkça apse oluşumuna yol açar.`,C:`Daha az yaygın formdur, HPV tip 16 ile ilişkilidir, ortalama yaş ~60'tır, sıklıkla sigara içen kadınlarda ve çoğunlukla çok odaklı lezyonlar şeklinde görülür.`,A:`Atipik epitel hücrelerinin intraepidermal proliferasyonudur; vulva derisi (ekstramammary Paget) veya meme ucu derisinde görülür. Olası köken vulva derisi kanallarındaki multipotent hücrelerdir.`},dogru:`D`,aciklama:`Doğru: Her yaşta görülebilir (menopoz sonrası kadınlar, ergenlik öncesi kızlar); patogenezi belirsizdir, subepiteliyal aktif T hücre infiltrasyonu ve otoimmün bozukluklarla birliktelik vardır.`,sik_aciklamalari:{D:`Doğru. Her yaşta görülebilir (menopoz sonrası kadınlar, ergenlik öncesi kızlar); patogenezi belirsizdir, subepiteliyal aktif T hücre infiltrasyonu ve otoimmün bozukluklarla birliktelik vardır.`,E:`Yanlış. HPV kondiloma akuminatum etkenidir, VIN ile ilişkilidir ve vulvar skuamöz karsinom alt kümesinde rol oynar.`,B:`Yanlış. Bartholin bezi salgı kanalı tıkanması ağrılı gland genişlemesi (Bartholin kisti) ve sıkça apse oluşumuna yol açar.`,C:`Yanlış. Daha az yaygın formdur, HPV tip 16 ile ilişkilidir, ortalama yaş ~60'tır, sıklıkla sigara içen kadınlarda ve çoğunlukla çok odaklı lezyonlar şeklinde görülür.`,A:`Yanlış. Atipik epitel hücrelerinin intraepidermal proliferasyonudur; vulva derisi (ekstramammary Paget) veya meme ucu derisinde görülür. Olası köken vulva derisi kanallarındaki multipotent hücrelerdir.`},bilgi:[12],benzer_cikmis:[]}],ilgili_cikmis:[]},{no:4,metin:`Vulvanın yapısını ve hastalık spektrumunu tanımlayabilmek`,sorular:[{id:`k1-48-q10`,kazanim:4,zorluk:`kolay`,soru:`Vulvanın yapısı ile ilgili aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`Vulva iç genital organdır`,B:`Labia majora kıllı deri, labia minora mukoza içerir`,C:`Labia minora kıllı deriden oluşur`,D:`Vulva yalnızca mukozadan oluşur`,E:`Vulvada salgı bezi bulunmaz`},dogru:`B`,aciklama:`Vulva dış kadın genital organıdır; labia majora kıllı deri, labia minora mukoza içerir.`,sik_aciklamalari:{A:`Vulva dış genital organdır.`,B:`Doğru: vulvanın yapısal içeriğidir.`,C:`Labia minora mukozal yapıdadır.`,D:`Vulvada deri ve mukoza birlikte bulunur.`,E:`Bartholin bezleri gibi salgı bezleri vardır.`},bilgi:[1,8],benzer_cikmis:[]},{id:`k1-48-q11`,kazanim:4,zorluk:`orta`,soru:`Vulvar karsinomun epidemiyolojisi ile ilgili hangisi doğrudur?`,secenekler:{A:`En sık histolojik tipi adenokarsinomdur`,B:`Kadın genital kanserlerinin en sık görülenidir`,C:`Kadın genital sistem kanserlerinin ~%3'ünü oluşturur ve çoğunlukla 60 yaş üstünde görülür`,D:`Çoğunlukla çocukluk çağında görülür`,E:`Bazal hücreli karsinom en sık tiptir`},dogru:`C`,aciklama:`Vulvar karsinom nadirdir (~%3), çoğunlukla 60 yaş üstünde görülür ve ~%90'ı skuamöz hücreli karsinomdur.`,sik_aciklamalari:{A:`Adenokarsinom daha az görülür.`,B:`Nadir bir genital kanserdir.`,C:`Doğru: sıklık ve yaş dağılımı doğru verilmiştir.`,D:`Yaşlı kadın hastalığıdır.`,E:`En sık tip skuamöz hücreli karsinomdur.`},bilgi:[22],benzer_cikmis:[]},{id:`k1-48-q12`,kazanim:4,zorluk:`zor`,soru:`Vulva hastalık spektrumu ile ilgili aşağıdakilerden hangisi yanlıştır?`,secenekler:{A:`Vulvit sık görülür ve çoğu zaman yoğun kaşıntıyla seyreder`,B:`Kaşıma ek travma yaratarak tabloyu ağırlaştırır`,C:`Liken skleroz ve skuamöz hiperplazi klinikte lökoplaki olarak görülebilir`,D:`Vulvadaki her beyaz lezyon benign olduğundan biyopsi gerekmez`,E:`Ekstramammary Paget hastalığı vulva derisinde görülebilir`},dogru:`D`,aciklama:`Lökoplaki benign veya malign olabildiğinden her lökoplaki için biyopsi zorunludur.`,sik_aciklamalari:{A:`Doğru ifade: vulvit çok nedenli ve kaşıntılıdır.`,B:`Doğru ifade: kaşıma-kaşıntı döngüsü oluşur.`,C:`Doğru ifade: iki non-neoplastik tablo da lökoplaki yapar.`,D:`Yanlış ifade (aranan cevap): lökoplakide biyopsi zorunludur.`,E:`Doğru ifade: ekstramammary Paget vulvada görülür.`},bilgi:[2,9,16,29],benzer_cikmis:[]},{id:`k1-48-vulva-vajen-ve-serviks-hastaliklari-k04-q04`,kazanim:4,zorluk:`orta`,soru:`Dermatoloji konsültasyonunda vulvanın deri-mukoza bileşimi tartışılıyor. Aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`Vulva iç organdır`,B:`Vulva dış genital organdır; labia majora kıllı deri, labia minora mukoza içerir; spektrumda inflamasyon sık, malignite nadir-önemlidir`,C:`Labia minora kıllıdır`,D:`Vulvada bez yoktur`,E:`Malignite sıktır`},dogru:`B`,aciklama:`Vulva dış organ; deri + mukoza içerir; inflamasyon sık, kanser nadirdir.`,sik_aciklamalari:{A:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Vulva dış genital organdır; labia majora kıllı deri, labia minora mukoza içerir; spektrumda inflamasyon sık, malignite nadir-önemlidir' seçeneğidir.`,B:`Doğru: Vulva dış organ; deri + mukoza içerir; inflamasyon sık, kanser nadirdir.`,C:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Vulva dış genital organdır; labia majora kıllı deri, labia minora mukoza içerir; spektrumda inflamasyon sık, malignite nadir-önemlidir' seçeneğidir.`,D:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Vulva dış genital organdır; labia majora kıllı deri, labia minora mukoza içerir; spektrumda inflamasyon sık, malignite nadir-önemlidir' seçeneğidir.`,E:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Vulva dış genital organdır; labia majora kıllı deri, labia minora mukoza içerir; spektrumda inflamasyon sık, malignite nadir-önemlidir' seçeneğidir.`},bilgi:[1,8],benzer_cikmis:[]},{id:`k1-48-vulva-vajen-ve-serviks-hastaliklari-k04-q05`,kazanim:4,zorluk:`zor`,soru:`Vulvar karsinomun sıklığı ve yaşı soruluyor. Aşağıdakilerden hangisi yanlıştır?`,secenekler:{A:`Çoğunlukla 60 yaş üstünde görülür`,B:`Vulvar karsinom kadın genital kanserlerinin ~%3'üdür ve ~%90'ı SCC'dir`,C:`Vulvit sık ve kaşıntılıdır; kaşıma tabloyu ağırlaştırır`,D:`Vulvar karsinom en sık genital kanserdir ve çocuklukta pik yapar`,E:`Ekstramammary Paget vulvada görülebilir`},dogru:`B`,aciklama:`Vulvar karsinom nadirdir ve yaşlıda görülür.`,sik_aciklamalari:{A:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Vulvar karsinom kadın genital kanserlerinin ~%3'üdür ve ~%90'ı SCC'dir' seçeneğidir.`,B:`Doğru: Vulvar karsinom nadirdir ve yaşlıda görülür.`,C:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Vulvar karsinom kadın genital kanserlerinin ~%3'üdür ve ~%90'ı SCC'dir' seçeneğidir.`,D:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Vulvar karsinom kadın genital kanserlerinin ~%3'üdür ve ~%90'ı SCC'dir' seçeneğidir.`,E:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Vulvar karsinom kadın genital kanserlerinin ~%3'üdür ve ~%90'ı SCC'dir' seçeneğidir.`},bilgi:[2,22,29],benzer_cikmis:[]},{id:`k1-48-vulva-vajen-ve-serviks-hastaliklari-k04-q06`,kazanim:4,zorluk:`orta`,soru:`Vulvanın anatomik yapısı ve hastalık spektrumu nasıldır?`,secenekler:{A:`Vulva iç genital organdır`,B:`Labia minora kıllı deridir`,C:`Vulvada bez ve mukoza yoktur`,D:`Dış organ; deri-mukoza içerir, inflamasyon sıktır`,E:`Malignite vulvada en sık lezyondur`},dogru:`D`,aciklama:`Vulva dış kadın genital organıdır; labia majora kıllı deri, labia minora mukoza içerir. Spektrumda inflamatuvar lezyonlar sık, maligniteler nadir ama önemlidir. Deri-mukoza bileşimi hastalık çeşitliliğini açıklar.`,sik_aciklamalari:{A:`Yanlış: Vulva dış genital organdır.`,B:`Yanlış: Kıllı deri labia majoradadır.`,C:`Yanlış: Mukozal yüzey ve bezler bulunur.`,D:`Doğru: Yapısal bileşim hastalık spektrumunu belirler.`,E:`Yanlış: Malignite nadir ama önemlidir.`},bilgi:[1,2],benzer_cikmis:[]},{id:`k1-48-vulva-vajen-ve-serviks-hastaliklari-k04-q07`,kazanim:4,zorluk:`orta`,soru:`Vulvar karsinomun sıklığı, histolojisi ve yaş dağılımı nedir?`,secenekler:{A:`Genital kanserlerin ~%3'ü; ~%90'ı SCC, yaşlıda`,B:`En sık genital kanser; çocuklukta pik yapar`,C:`Vulvit nadir ve ağrısızdır`,D:`Adenokarsinom vulvada baskın tiptir`,E:`Kaşıma vulviti tamamen iyileştirir`},dogru:`A`,aciklama:`Vulvar karsinom kadın genital kanserlerinin yaklaşık %3'üdür ve %90'ı skuamöz hücreli karsinomdur. Çoğunlukla 60 yaş üstünde görülür. Vulvit ise sık, kaşıntılı bir tablodur ve kaşıma lezyonu ağırlaştırır.`,sik_aciklamalari:{A:`Doğru: Vulvar karsinom nadir, yaşlıda ve SCC baskındır.`,B:`Yanlış: En sık değildir; yaşlıda görülür.`,C:`Yanlış: Vulvit sık ve kaşıntılıdır.`,D:`Yanlış: SCC %90 ile baskın histolojidir.`,E:`Yanlış: Kaşıma tabloyu ağırlaştırır.`},bilgi:[2,22],benzer_cikmis:[]},{id:`k1-48-vulva-vajen-ve-serviks-hastaliklari-k04-q08`,kazanim:4,zorluk:`kolay`,soru:`"Vulvanın tanımı ve içeriği" ifadesi ile ilgili aşağıdakilerden hangisi doğrudur?`,secenekler:{E:`Vulva dış kadın genital organıdır; kıllı deri (labia majora) ve mukoza (labia minora) içerir.`,C:`HPV kondiloma akuminatum etkenidir, VIN ile ilişkilidir ve vulvar skuamöz karsinom alt kümesinde rol oynar.`,A:`Eski isimleri hiperplastik distrofi ve liken simpleks kronikustur; nedeni şiddetli kaşıntıyı gidermek için ovma/kaşımadır ve lökoplaki görünümü oluşturur.`,D:`Klinikte kırmızı, pullu, kabuklu plak kronik dermatiti taklit eder; histolojide büyük hücreler, bol soluk ince granüllü sitoplazma ve epidermiste tek tek/gruplar halinde hücreler vardır; invazyon veya metastaz olmaksızın yıllarca sürebilir.`,B:`Nadir bir vajinal tümördür (sarkoma botryoides); histogenezi malign embriyonel rabdomiyoblastlardır ve 5 yaşından küçük bebek ve çocuklarda görülür.`},dogru:`E`,aciklama:`Doğru: Vulva dış kadın genital organıdır; kıllı deri (labia majora) ve mukoza (labia minora) içerir.`,sik_aciklamalari:{E:`Doğru. Vulva dış kadın genital organıdır; kıllı deri (labia majora) ve mukoza (labia minora) içerir.`,C:`Yanlış. HPV kondiloma akuminatum etkenidir, VIN ile ilişkilidir ve vulvar skuamöz karsinom alt kümesinde rol oynar.`,A:`Yanlış. Eski isimleri hiperplastik distrofi ve liken simpleks kronikustur; nedeni şiddetli kaşıntıyı gidermek için ovma/kaşımadır ve lökoplaki görünümü oluşturur.`,D:`Yanlış. Klinikte kırmızı, pullu, kabuklu plak kronik dermatiti taklit eder; histolojide büyük hücreler, bol soluk ince granüllü sitoplazma ve epidermiste tek tek/gruplar halinde hücreler vardır; invazyon veya metastaz olmaksızın yıllarca sürebilir.`,B:`Yanlış. Nadir bir vajinal tümördür (sarkoma botryoides); histogenezi malign embriyonel rabdomiyoblastlardır ve 5 yaşından küçük bebek ve çocuklarda görülür.`},bilgi:[1],benzer_cikmis:[]},{id:`k1-48-vulva-vajen-ve-serviks-hastaliklari-k04-q09`,kazanim:4,zorluk:`orta`,soru:`"Vulvitin enfeksiyöz etkenleri" kavramı hakkında verilen aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`Çoğu cinsel yolla bulaşır: HPV, HSV-1/HSV-2, Neisseria gonorrhoeae, Treponema pallidum ve Candida türleri.`,E:`Vulvar skuamöz hücreli karsinom riski biraz artmıştır ancak liken skleroz prekanseröz lezyon değildir.`,D:`1) Bazaloid/siğil benzeri karsinom yüksek riskli HPV ile ilişkilidir. 2) Keratinize skuamöz hücreli karsinom HPV ile ilişkili değildir ve liken skleroz veya skuamöz hücre hiperplazisi zemininde gelişir.`,C:`Gram negatif kokobasildir ve bakteriyel vajinozun ana nedenidir; ince, gri beyaz, kötü kokulu akıntı ve 'balık kokusu' şikayeti görülür.`,B:`Reaktif inflamasyon alerjen veya irritan temasına yanıttır; losyon ve sabun katkı maddeleri, antiseptikler ve giysi kimyasalları rol oynar.`},dogru:`A`,aciklama:`Doğru: Çoğu cinsel yolla bulaşır: HPV, HSV-1/HSV-2, Neisseria gonorrhoeae, Treponema pallidum ve Candida türleri.`,sik_aciklamalari:{A:`Doğru. Çoğu cinsel yolla bulaşır: HPV, HSV-1/HSV-2, Neisseria gonorrhoeae, Treponema pallidum ve Candida türleri.`,E:`Yanlış. Vulvar skuamöz hücreli karsinom riski biraz artmıştır ancak liken skleroz prekanseröz lezyon değildir.`,D:`Yanlış. 1) Bazaloid/siğil benzeri karsinom yüksek riskli HPV ile ilişkilidir. 2) Keratinize skuamöz hücreli karsinom HPV ile ilişkili değildir ve liken skleroz veya skuamöz hücre hiperplazisi zemininde gelişir.`,C:`Yanlış. Gram negatif kokobasildir ve bakteriyel vajinozun ana nedenidir; ince, gri beyaz, kötü kokulu akıntı ve 'balık kokusu' şikayeti görülür.`,B:`Yanlış. Reaktif inflamasyon alerjen veya irritan temasına yanıttır; losyon ve sabun katkı maddeleri, antiseptikler ve giysi kimyasalları rol oynar.`},bilgi:[4],benzer_cikmis:[]},{id:`k1-48-vulva-vajen-ve-serviks-hastaliklari-k04-q10`,kazanim:4,zorluk:`orta`,soru:`"HPV ile ilişkili vulvar lezyonlar" ile ilgili eşleştirmelerden hangisi doğrudur?`,secenekler:{A:`HPV kondiloma akuminatum etkenidir, VIN ile ilişkilidir ve vulvar skuamöz karsinom alt kümesinde rol oynar.`,D:`VIN seyri yüksek dereceli atipi ve karsinoma in situ gelişimidir; invaziv karsinom riski 45 yaşından büyük kadınlarda ve immün sistemi baskılanmış hastalarda artar.`,B:`İki temel tablo liken skleroz ve skuamöz hücre hiperplazisidir; klinik olarak genellikle lökoplaki şeklinde görülürler.`,C:`Epidermis kalınlaşması (akantoz), hiperkeratoz, dermiste bazen lenfositik infiltrasyon ve sitolojik atipisi olmayan artmış mitotik aktivite gösteren hiperplastik epitel vardır.`,E:`Candida vulvit nedeni olmakla birlikte cinsel yolla bulaşmaz; diyabet, antibiyotik kullanımı, gebelik ve immün yetmezlikte yatkınlık artar.`},dogru:`A`,aciklama:`Doğru: HPV kondiloma akuminatum etkenidir, VIN ile ilişkilidir ve vulvar skuamöz karsinom alt kümesinde rol oynar.`,sik_aciklamalari:{A:`Doğru. HPV kondiloma akuminatum etkenidir, VIN ile ilişkilidir ve vulvar skuamöz karsinom alt kümesinde rol oynar.`,D:`Yanlış. VIN seyri yüksek dereceli atipi ve karsinoma in situ gelişimidir; invaziv karsinom riski 45 yaşından büyük kadınlarda ve immün sistemi baskılanmış hastalarda artar.`,B:`Yanlış. İki temel tablo liken skleroz ve skuamöz hücre hiperplazisidir; klinik olarak genellikle lökoplaki şeklinde görülürler.`,C:`Yanlış. Epidermis kalınlaşması (akantoz), hiperkeratoz, dermiste bazen lenfositik infiltrasyon ve sitolojik atipisi olmayan artmış mitotik aktivite gösteren hiperplastik epitel vardır.`,E:`Yanlış. Candida vulvit nedeni olmakla birlikte cinsel yolla bulaşmaz; diyabet, antibiyotik kullanımı, gebelik ve immün yetmezlikte yatkınlık artar.`},bilgi:[5],benzer_cikmis:[]},{id:`k1-48-vulva-vajen-ve-serviks-hastaliklari-k04-q11`,kazanim:4,zorluk:`zor`,soru:`"Candida enfeksiyonu (vulva)" klinik bağlamda aşağıdakilerden hangisi doğrudur?`,secenekler:{C:`Candida vulvit nedeni olmakla birlikte cinsel yolla bulaşmaz; diyabet, antibiyotik kullanımı, gebelik ve immün yetmezlikte yatkınlık artar.`,D:`Vajinanın inflamatuar durumudur; genellikle enfeksiyona bağlı ve geçicidir, temel bulgu vajinal akıntıdır (lökore). Etkenler bakteri, mantar, parazit olup pek çoğu normal kommensal flora üyesidir.`,E:`VIN seyri yüksek dereceli atipi ve karsinoma in situ gelişimidir; invaziv karsinom riski 45 yaşından büyük kadınlarda ve immün sistemi baskılanmış hastalarda artar.`,B:`Lökoplaki yapabilen benign hastalıklar psoriasis ve liken planus; neoplastik lezyonlar skuamöz hücreli karsinoma in situ ve invaziv skuamöz hücreli karsinomdur.`,A:`Genellikle yaşlı kadınlarda (ortalama yaş ~75), uzun süreli liken skleroz ve skuamöz hücre hiperplazisi zemininde görülür ve HPV ile ilişkili değildir; ön lezyonu dVIN'dir (bazal tabakaya sınırlı anormal keratinizasyon ve sitolojik atipi).`},dogru:`C`,aciklama:`Doğru: Candida vulvit nedeni olmakla birlikte cinsel yolla bulaşmaz; diyabet, antibiyotik kullanımı, gebelik ve immün yetmezlikte yatkınlık artar.`,sik_aciklamalari:{C:`Doğru. Candida vulvit nedeni olmakla birlikte cinsel yolla bulaşmaz; diyabet, antibiyotik kullanımı, gebelik ve immün yetmezlikte yatkınlık artar.`,D:`Yanlış. Vajinanın inflamatuar durumudur; genellikle enfeksiyona bağlı ve geçicidir, temel bulgu vajinal akıntıdır (lökore). Etkenler bakteri, mantar, parazit olup pek çoğu normal kommensal flora üyesidir.`,E:`Yanlış. VIN seyri yüksek dereceli atipi ve karsinoma in situ gelişimidir; invaziv karsinom riski 45 yaşından büyük kadınlarda ve immün sistemi baskılanmış hastalarda artar.`,B:`Yanlış. Lökoplaki yapabilen benign hastalıklar psoriasis ve liken planus; neoplastik lezyonlar skuamöz hücreli karsinoma in situ ve invaziv skuamöz hücreli karsinomdur.`,A:`Yanlış. Genellikle yaşlı kadınlarda (ortalama yaş ~75), uzun süreli liken skleroz ve skuamöz hücre hiperplazisi zemininde görülür ve HPV ile ilişkili değildir; ön lezyonu dVIN'dir (bazal tabakaya sınırlı anormal keratinizasyon ve sitolojik atipi).`},bilgi:[7],benzer_cikmis:[]}],ilgili_cikmis:[]},{no:5,metin:`Vulvitin alerjik/irritan ve enfeksiyöz nedenlerini açıklayabilmek`,sorular:[{id:`k1-48-q13`,kazanim:5,zorluk:`kolay`,soru:`Aşağıdaki vulvit etkenlerinden hangisi cinsel yolla bulaşmaz?`,secenekler:{A:`Neisseria gonorrhoeae`,B:`HPV`,C:`HSV-2`,D:`Candida türleri`,E:`Treponema pallidum`},dogru:`D`,aciklama:`Candida vulvit nedenidir ancak cinsel yolla bulaşmaz; diyabet, antibiyotik, gebelik ve immün yetmezlikte yatkınlık artar.`,sik_aciklamalari:{A:`Gonokok cinsel yolla bulaşır.`,B:`HPV cinsel yolla bulaşır.`,C:`HSV-2 cinsel yolla bulaşır.`,D:`Doğru: kandida endojen floradan kaynaklanır.`,E:`T. pallidum cinsel yolla bulaşır.`},bilgi:[4,7],benzer_cikmis:[]},{id:`k1-48-q14`,kazanim:5,zorluk:`orta`,soru:`Yeni bir parfümlü sabun kullanmaya başlayan yaşlı kadında vulvada iyi sınırlı eritemli papül ve plaklar, sulanma ve kabuklanma gelişiyor.

En olası tanı hangisidir?`,secenekler:{A:`Liken skleroz`,B:`Alerjik/irritan kontakt vulvit`,C:`Vulvar karsinom`,D:`Kondiloma akuminatum`,E:`Bartholin apsesi`},dogru:`B`,aciklama:`Losyon, sabun katkıları, antiseptikler veya idrar teması reaktif (alerjik/irritan) vulvit yapar.`,sik_aciklamalari:{A:`Liken skleroz sklerotik beyaz plaklar ve atrofi ile seyreder.`,B:`Doğru: tetikleyici madde ve klinik tablo uyumludur.`,C:`Karsinom kitle veya ülser yapar, akut ekzematöz tablo değildir.`,D:`Kondilom papiller siğildir.`,E:`Bartholin apsesi lokalize ağrılı şişlik yapar.`},bilgi:[3],benzer_cikmis:[]},{id:`k1-48-q15`,kazanim:5,zorluk:`zor`,soru:`Vulvitin enfeksiyöz etkenleri ve yol açtıkları tablolar eşleştirildiğinde hangisi yanlıştır?`,secenekler:{A:`N. gonorrhoeae – vulvovajinal bezlerin süpüratif enfeksiyonu`,B:`T. pallidum – primer şankr`,C:`HSV – ağrılı vezikül/ülser ve tekrarlayıcı seyir`,D:`Candida – beyaz plak benzeri lezyonlar, kaşıntı`,E:`HPV 6/11 – ağrılı derin ülser ve kalıcı latent enfeksiyon`},dogru:`E`,aciklama:`HPV 6/11 kondiloma akuminatum (siğil) yapar; ağrılı vezikül/ülser ve latent enfeksiyon HSV'ye özgüdür.`,sik_aciklamalari:{A:`Doğru eşleştirme: gonokok Bartholin gibi bezlerde süpürasyon yapar.`,B:`Doğru eşleştirme: T. pallidum primer şankra yol açar.`,C:`Doğru eşleştirme: HSV persistan latent enfeksiyon yapar.`,D:`Doğru eşleştirme: kandida eritem, ödem ve beyaz plak yapar.`,E:`Yanlış eşleştirme (aranan cevap): HPV 6/11 siğil oluşturur.`},bilgi:[4,6,7,19],benzer_cikmis:[]},{id:`k1-48-vulva-vajen-ve-serviks-hastaliklari-k05-q04`,kazanim:5,zorluk:`orta`,soru:`Parfümlü sabun sonrası vulvar ekzematöz plakları çıkan yaşlı hasta ile akıntılı genç hasta karşılaştırılıyor. Aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`Tüm vulvitler enfeksiyözdür`,B:`Candida cinsel yolla bulaşır`,C:`HSV latent yapmaz`,D:`Sabun/antiseptik/idrar teması reaktif (alerjik/irritan) vulvit yapar; enfeksiyöz nedenlerin çoğu cinsel yolla bulaşır, Candida önemli istisnadır`,E:`Gonokok bez enfeksiyonu yapmaz`},dogru:`D`,aciklama:`Alerjik/irritan temas dermatit yapar; Candida CYBE değildir.`,sik_aciklamalari:{A:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Sabun/antiseptik/idrar teması reaktif (alerjik/irritan) vulvit yapar; enfeksiyöz nedenlerin çoğu cinsel yolla bulaşır, Candida önemli istisnadır' seçeneğidir.`,B:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Sabun/antiseptik/idrar teması reaktif (alerjik/irritan) vulvit yapar; enfeksiyöz nedenlerin çoğu cinsel yolla bulaşır, Candida önemli istisnadır' seçeneğidir.`,C:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Sabun/antiseptik/idrar teması reaktif (alerjik/irritan) vulvit yapar; enfeksiyöz nedenlerin çoğu cinsel yolla bulaşır, Candida önemli istisnadır' seçeneğidir.`,D:`Doğru: Alerjik/irritan temas dermatit yapar; Candida CYBE değildir.`,E:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Sabun/antiseptik/idrar teması reaktif (alerjik/irritan) vulvit yapar; enfeksiyöz nedenlerin çoğu cinsel yolla bulaşır, Candida önemli istisnadır' seçeneğidir.`},bilgi:[3,4,7],benzer_cikmis:[]},{id:`k1-48-vulva-vajen-ve-serviks-hastaliklari-k05-q05`,kazanim:5,zorluk:`zor`,soru:`Etken-tabla eşleştirmesi soruluyor. Aşağıdakilerden hangisi yanlıştır?`,secenekler:{A:`T. pallidum primer şankr yapar`,B:`HSV ağrılı vezikül/ülser ve latent enfeksiyon yapar`,C:`HPV 6/11 ağrılı derin ülser ve kalıcı latent yapar; Candida cinsel yolla bulaşır`,D:`Candida diyabet/antibiyotik/gebelikte artar`,E:`N. gonorrhoeae vulvovajinal bezlerin süpüratif enfeksiyonu yapar`},dogru:`E`,aciklama:`HPV 6/11 siğil yapar; ülser-latent HSV'nindir; Candida CYBE değildir.`,sik_aciklamalari:{A:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'N. gonorrhoeae vulvovajinal bezlerin süpüratif enfeksiyonu yapar' seçeneğidir.`,B:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'N. gonorrhoeae vulvovajinal bezlerin süpüratif enfeksiyonu yapar' seçeneğidir.`,C:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'N. gonorrhoeae vulvovajinal bezlerin süpüratif enfeksiyonu yapar' seçeneğidir.`,D:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'N. gonorrhoeae vulvovajinal bezlerin süpüratif enfeksiyonu yapar' seçeneğidir.`,E:`Doğru: HPV 6/11 siğil yapar; ülser-latent HSV'nindir; Candida CYBE değildir.`},bilgi:[4,6,7,19],benzer_cikmis:[]},{id:`k1-48-vulva-vajen-ve-serviks-hastaliklari-k05-q06`,kazanim:5,zorluk:`orta`,soru:`Vulvitin alerjik-irritan ve enfeksiyöz neden ayrımı nasıldır?`,secenekler:{A:`Tüm vulvitler enfeksiyözdür`,B:`Candida cinsel yolla bulaşır`,C:`Temas reaktif yapar; Candida CYBE değildir`,D:`HSV latent enfeksiyon yapmaz`,E:`Gonokok bez enfeksiyonu yapmaz`},dogru:`C`,aciklama:`Sabun, antiseptik ve idrar teması reaktif alerjik-irritan vulvit yapar. Enfeksiyöz nedenlerin çoğu cinsel yolla bulaşır; Candida önemli istisnadır ve cinsel yolla bulaşmaz. Diyabet, antibiyotik ve gebelik yatkınlığı artırır.`,sik_aciklamalari:{A:`Yanlış: Alerjik-irritan nedenler de sıktır.`,B:`Yanlış: Candida endojen flora üyesidir.`,C:`Doğru: Kimyasal temas dermatit, çoğu mikrop CYBE yapar.`,D:`Yanlış: HSV latent kalıp tekrarlar.`,E:`Yanlış: Gonokok bezlerin süpüratif enfeksiyonunu yapar.`},bilgi:[3,4,7],benzer_cikmis:[]},{id:`k1-48-vulva-vajen-ve-serviks-hastaliklari-k05-q07`,kazanim:5,zorluk:`orta`,soru:`Vulvit etkenlerinin tipik lezyon paternleri nasıl eşleşir?`,secenekler:{A:`HPV 6-11 ağrılı derin ülser yapar`,B:`Candida hep cinsel yolla bulaşır`,C:`HSV latent kalmadan tek atak yapar`,D:`Gonokok yalnızca üretriti etkiler`,E:`Şankr, vezikül, siğil ve bez enfeksiyonu ayrılır`},dogru:`E`,aciklama:`T. pallidum primer şankr, HSV ağrılı vezikül-ülser ve latent enfeksiyon, HPV 6-11 papiller siğil yapar. Candida diyabet, antibiyotik ve gebelikte artar. N. gonorrhoeae vulvovajinal bezlerin süpüratif enfeksiyonuna yol açar.`,sik_aciklamalari:{A:`Yanlış: HPV 6-11 papiller siğil yapar.`,B:`Yanlış: Candida endojen kaynaklıdır.`,C:`Yanlış: HSV latent kalıp nükseder.`,D:`Yanlış: Gonokok bezleri de enfekte eder.`,E:`Doğru: Her etkenin lezyon paterni farklıdır.`},bilgi:[4,6,7],benzer_cikmis:[]},{id:`k1-48-vulva-vajen-ve-serviks-hastaliklari-k05-q08`,kazanim:5,zorluk:`kolay`,soru:`Aşağıdakilerden "HPV ile ilişkili vulvar lezyonlar" ile ilgili doğru olan seçeneği işaretleyiniz.`,secenekler:{E:`HPV kondiloma akuminatum etkenidir, VIN ile ilişkilidir ve vulvar skuamöz karsinom alt kümesinde rol oynar.`,D:`Vulvar kondilomlar kansere dönüşmez ancak vajina ve servikste HPV ilişkili prekanseröz lezyon riski artar.`,C:`Servikal lezyonların çoğu inflamatuvar (servisit) niteliktedir; servikal skuamöz hücreli karsinom dünya çapında kadınlarda en sık görülen kanserlerden biridir ve HPV ilişkisi belirgindir.`,A:`Atipik epitel hücrelerinin intraepidermal proliferasyonudur; vulva derisi (ekstramammary Paget) veya meme ucu derisinde görülür. Olası köken vulva derisi kanallarındaki multipotent hücrelerdir.`,B:`Vulvar skuamöz hücreli karsinom riski biraz artmıştır ancak liken skleroz prekanseröz lezyon değildir.`},dogru:`E`,aciklama:`Doğru: HPV kondiloma akuminatum etkenidir, VIN ile ilişkilidir ve vulvar skuamöz karsinom alt kümesinde rol oynar.`,sik_aciklamalari:{E:`Doğru. HPV kondiloma akuminatum etkenidir, VIN ile ilişkilidir ve vulvar skuamöz karsinom alt kümesinde rol oynar.`,D:`Yanlış. Vulvar kondilomlar kansere dönüşmez ancak vajina ve servikste HPV ilişkili prekanseröz lezyon riski artar.`,C:`Yanlış. Servikal lezyonların çoğu inflamatuvar (servisit) niteliktedir; servikal skuamöz hücreli karsinom dünya çapında kadınlarda en sık görülen kanserlerden biridir ve HPV ilişkisi belirgindir.`,A:`Yanlış. Atipik epitel hücrelerinin intraepidermal proliferasyonudur; vulva derisi (ekstramammary Paget) veya meme ucu derisinde görülür. Olası köken vulva derisi kanallarındaki multipotent hücrelerdir.`,B:`Yanlış. Vulvar skuamöz hücreli karsinom riski biraz artmıştır ancak liken skleroz prekanseröz lezyon değildir.`},bilgi:[5],benzer_cikmis:[]},{id:`k1-48-vulva-vajen-ve-serviks-hastaliklari-k05-q09`,kazanim:5,zorluk:`orta`,soru:`"Candida albicans vajiniti" kavramı hakkında verilen aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`Kadınların ~%20'sinde normal vajinal flora üyesidir; semptomatik enfeksiyon yatkınlaştırıcı faktörlere veya virülan bir suşla süperenfeksiyona bağlıdır.`,D:`Daha az yaygın formdur, HPV tip 16 ile ilişkilidir, ortalama yaş ~60'tır, sıklıkla sigara içen kadınlarda ve çoğunlukla çok odaklı lezyonlar şeklinde görülür.`,B:`Dünya çapında en yaygın viral olmayan cinsel yolla bulaşan enfeksiyondur; çoğu enfeksiyon asemptomatiktir.`,C:`Reaktif inflamasyon alerjen veya irritan temasına yanıttır; losyon ve sabun katkı maddeleri, antiseptikler ve giysi kimyasalları rol oynar.`,E:`Candida vulvit nedeni olmakla birlikte cinsel yolla bulaşmaz; diyabet, antibiyotik kullanımı, gebelik ve immün yetmezlikte yatkınlık artar.`},dogru:`A`,aciklama:`Doğru: Kadınların ~%20'sinde normal vajinal flora üyesidir; semptomatik enfeksiyon yatkınlaştırıcı faktörlere veya virülan bir suşla süperenfeksiyona bağlıdır.`,sik_aciklamalari:{A:`Doğru. Kadınların ~%20'sinde normal vajinal flora üyesidir; semptomatik enfeksiyon yatkınlaştırıcı faktörlere veya virülan bir suşla süperenfeksiyona bağlıdır.`,D:`Yanlış. Daha az yaygın formdur, HPV tip 16 ile ilişkilidir, ortalama yaş ~60'tır, sıklıkla sigara içen kadınlarda ve çoğunlukla çok odaklı lezyonlar şeklinde görülür.`,B:`Yanlış. Dünya çapında en yaygın viral olmayan cinsel yolla bulaşan enfeksiyondur; çoğu enfeksiyon asemptomatiktir.`,C:`Yanlış. Reaktif inflamasyon alerjen veya irritan temasına yanıttır; losyon ve sabun katkı maddeleri, antiseptikler ve giysi kimyasalları rol oynar.`,E:`Yanlış. Candida vulvit nedeni olmakla birlikte cinsel yolla bulaşmaz; diyabet, antibiyotik kullanımı, gebelik ve immün yetmezlikte yatkınlık artar.`},bilgi:[34],benzer_cikmis:[]},{id:`k1-48-vulva-vajen-ve-serviks-hastaliklari-k05-q10`,kazanim:5,zorluk:`orta`,soru:`"Vajina genel özellikler ve anomaliler" ile ilgili eşleştirmelerden hangisi doğrudur?`,secenekler:{E:`Yetişkinlerde nadiren primer hastalık yeridir; daha sık komşu organ kanserlerinin (serviks, mesane, rektum) sekonder tutulumu görülür. Nadir konjenital anomaliler: vajinanın tam yokluğu, septalı veya çift vajina.`,B:`HPV kondiloma akuminatum etkenidir, VIN ile ilişkilidir ve vulvar skuamöz karsinom alt kümesinde rol oynar.`,C:`Servikal lezyonların çoğu inflamatuvar (servisit) niteliktedir; servikal skuamöz hücreli karsinom dünya çapında kadınlarda en sık görülen kanserlerden biridir ve HPV ilişkisi belirgindir.`,D:`Uzun süre lokal kalma eğilimi vardır; ilk yayılım bölgesel lenf düğümlerine, ileri evrede akciğer ve diğer organlara hematogen metastaz olur.`,A:`HSV-1 ve HSV-2 genital herpes etkenidir; ağrılı vezikül ve ülserler ile tekrarlayıcı seyir yapar.`},dogru:`E`,aciklama:`Doğru: Yetişkinlerde nadiren primer hastalık yeridir; daha sık komşu organ kanserlerinin (serviks, mesane, rektum) sekonder tutulumu görülür. Nadir konjenital anomaliler: vajinanın tam yokluğu, septalı veya çift vajina.`,sik_aciklamalari:{E:`Doğru. Yetişkinlerde nadiren primer hastalık yeridir; daha sık komşu organ kanserlerinin (serviks, mesane, rektum) sekonder tutulumu görülür. Nadir konjenital anomaliler: vajinanın tam yokluğu, septalı veya çift vajina.`,B:`Yanlış. HPV kondiloma akuminatum etkenidir, VIN ile ilişkilidir ve vulvar skuamöz karsinom alt kümesinde rol oynar.`,C:`Yanlış. Servikal lezyonların çoğu inflamatuvar (servisit) niteliktedir; servikal skuamöz hücreli karsinom dünya çapında kadınlarda en sık görülen kanserlerden biridir ve HPV ilişkisi belirgindir.`,D:`Yanlış. Uzun süre lokal kalma eğilimi vardır; ilk yayılım bölgesel lenf düğümlerine, ileri evrede akciğer ve diğer organlara hematogen metastaz olur.`,A:`Yanlış. HSV-1 ve HSV-2 genital herpes etkenidir; ağrılı vezikül ve ülserler ile tekrarlayıcı seyir yapar.`},bilgi:[31],benzer_cikmis:[]},{id:`k1-48-vulva-vajen-ve-serviks-hastaliklari-k05-q11`,kazanim:5,zorluk:`zor`,soru:`"Bartholin bezi komplikasyonları" ile ilgili bir hastada bulunacak aşağıdaki bulgulardan hangisi beklenmez?`,secenekler:{E:`Bartholin bezi salgı kanalı tıkanması ağrılı gland genişlemesi (Bartholin kisti) ve sıkça apse oluşumuna yol açar.`,C:`Tüm kadın genital sistem kanserlerinin ~%3'ü; 60 yaş üstü kadınlarda görülür; histolojik tiplerin ~%90'ı skuamöz hücreli karsinom, diğerleri adenokarsinom ve bazal hücreli karsinomdur.`,D:`HPV pozitif tümörler sıklıkla multifokal, siğil benzeri ve genellikle kötü diferansiye; HPV negatif tümörler genellikle unifokal ve iyi diferansiye, keratinize skuamöz hücreli karsinomdur.`,B:`Vulva dış kadın genital organıdır; kıllı deri (labia majora) ve mukoza (labia minora) içerir.`,A:`HPV kondiloma akuminatum etkenidir, VIN ile ilişkilidir ve vulvar skuamöz karsinom alt kümesinde rol oynar.`},dogru:`E`,aciklama:`Doğru: Bartholin bezi salgı kanalı tıkanması ağrılı gland genişlemesi (Bartholin kisti) ve sıkça apse oluşumuna yol açar.`,sik_aciklamalari:{E:`Doğru. Bartholin bezi salgı kanalı tıkanması ağrılı gland genişlemesi (Bartholin kisti) ve sıkça apse oluşumuna yol açar.`,C:`Yanlış. Tüm kadın genital sistem kanserlerinin ~%3'ü; 60 yaş üstü kadınlarda görülür; histolojik tiplerin ~%90'ı skuamöz hücreli karsinom, diğerleri adenokarsinom ve bazal hücreli karsinomdur.`,D:`Yanlış. HPV pozitif tümörler sıklıkla multifokal, siğil benzeri ve genellikle kötü diferansiye; HPV negatif tümörler genellikle unifokal ve iyi diferansiye, keratinize skuamöz hücreli karsinomdur.`,B:`Yanlış. Vulva dış kadın genital organıdır; kıllı deri (labia majora) ve mukoza (labia minora) içerir.`,A:`Yanlış. HPV kondiloma akuminatum etkenidir, VIN ile ilişkilidir ve vulvar skuamöz karsinom alt kümesinde rol oynar.`},bilgi:[8],benzer_cikmis:[]}],ilgili_cikmis:[]},{no:6,metin:`Bartholin bezi komplikasyonlarını (kist/apse) bilmek`,sorular:[{id:`k1-48-q16`,kazanim:6,zorluk:`kolay`,soru:`Bartholin kistinin temel oluşum mekanizması hangisidir?`,secenekler:{A:`HPV enfeksiyonu`,B:`Wolffian kanal kalıntısı`,C:`Bartholin bezi salgı kanalının tıkanması`,D:`Epidermal neoplazi`,E:`Konjenital vajinal septum`},dogru:`C`,aciklama:`Salgı kanalının tıkanması bezin ağrılı genişlemesine (kist) ve sıklıkla apseye yol açar.`,sik_aciklamalari:{A:`HPV siğil ve neoplazilerle ilişkilidir.`,B:`Wolffian kalıntı Gartner kanal kistini oluşturur.`,C:`Doğru: kanal tıkanması kist oluşumunun nedenidir.`,D:`Bartholin kisti neoplastik değildir.`,E:`Vajinal septum Bartholin kisti yapmaz.`},bilgi:[8],benzer_cikmis:[]},{id:`k1-48-q17`,kazanim:6,zorluk:`orta`,soru:`Bartholin bezi apsesi gelişen hastada uygun yaklaşım hangisidir?`,secenekler:{A:`Kemoterapi`,B:`Yalnızca HPV aşısı`,C:`Radyoterapi`,D:`Cerrahi drenaj ve gerekirse antibiyotik`,E:`Tedavi gerekmez, kalıcı olarak geriler`},dogru:`D`,aciklama:`Bartholin kisti/apsesi vulvitin önemli komplikasyonudur; cerrahi drenaj ve antibiyotik gerekebilir.`,sik_aciklamalari:{A:`Kemoterapi benign apsede endike değildir.`,B:`HPV aşısı bu tablonun tedavisi değildir.`,C:`Radyoterapi malign tümörlerde kullanılır.`,D:`Doğru: apse drene edilmelidir.`,E:`Apse genellikle drenaj gerektirir.`},bilgi:[8],benzer_cikmis:[]},{id:`k1-48-q18`,kazanim:6,zorluk:`zor`,soru:`Vulvanın posterolateral bölgesinde ağrılı, kızarık, fluktuasyon veren şişlik saptanan genç kadında aşağıdaki etkenlerden hangisi bu bezlerin süpüratif enfeksiyonu ile özellikle ilişkilidir?`,secenekler:{A:`HPV 6`,B:`Neisseria gonorrhoeae`,C:`Treponema pallidum`,D:`Trichomonas vaginalis`,E:`Gardnerella vaginalis`},dogru:`B`,aciklama:`N. gonorrhoeae vulvovajinal bezlerde süpüratif enfeksiyon (Bartholin apsesi) yapabilir.`,sik_aciklamalari:{A:`HPV 6 siğil yapar: HPV 6.`,B:`Doğru: gonokok bez enfeksiyonu ve apse ile ilişkilidir.`,C:`T. pallidum ağrısız şankr yapar.`,D:`Trichomonas vajinit yapar, apse değil.`,E:`Gardnerella bakteriyel vajinoz yapar.`},bilgi:[4,8],benzer_cikmis:[]},{id:`k1-48-vulva-vajen-ve-serviks-hastaliklari-k06-q04`,kazanim:6,zorluk:`orta`,soru:`Vulvada posterolateral ağrılı fluktuasyon veren şişliği olan genç kadın değerlendiriliyor. Aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`Bartholin bezi salgı kanalı tıkanması ağrılı kist ve sıkça apse yapar; tedavi drenaj + antibiyotiktir; gonokok bezlerin süpüratif enfeksiyonu yapabilir`,B:`Bartholin kisti HPV ile oluşur`,C:`Apse kendiliğinden hep geriler`,D:`Tedavi kemoterapidir`,E:`Kist neoplastiktir`},dogru:`A`,aciklama:`Kanal tıkanması kist/apse yapar; gonokok süpüratif bez enfeksiyonu nedenidir.`,sik_aciklamalari:{A:`Doğru: Kanal tıkanması kist/apse yapar; gonokok süpüratif bez enfeksiyonu nedenidir.`,B:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Bartholin bezi salgı kanalı tıkanması ağrılı kist ve sıkça apse yapar; tedavi drenaj + antibiyotiktir; gonokok bezlerin süpüratif enfeksiyonu yapabilir' seçeneğidir.`,C:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Bartholin bezi salgı kanalı tıkanması ağrılı kist ve sıkça apse yapar; tedavi drenaj + antibiyotiktir; gonokok bezlerin süpüratif enfeksiyonu yapabilir' seçeneğidir.`,D:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Bartholin bezi salgı kanalı tıkanması ağrılı kist ve sıkça apse yapar; tedavi drenaj + antibiyotiktir; gonokok bezlerin süpüratif enfeksiyonu yapabilir' seçeneğidir.`,E:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Bartholin bezi salgı kanalı tıkanması ağrılı kist ve sıkça apse yapar; tedavi drenaj + antibiyotiktir; gonokok bezlerin süpüratif enfeksiyonu yapabilir' seçeneğidir.`},bilgi:[4,8],benzer_cikmis:[]},{id:`k1-48-vulva-vajen-ve-serviks-hastaliklari-k06-q05`,kazanim:6,zorluk:`zor`,soru:`Bartholin kisti ile Gartner kisti ayrımı soruluyor. Aşağıdakilerden hangisi yanlıştır?`,secenekler:{A:`Apse drenaj gerektirebilir`,B:`Gonokok süpüratif bez enfeksiyonu yapar`,C:`Bartholin kisti kanal tıkanmasıyla oluşur`,D:`Bartholin kisti Wolffian kalıntısıdır ve HPV aşısı apseleri tedavi eder`,E:`Gartner kisti lateral vajinal Wolffian kalıntısıdır`},dogru:`C`,aciklama:`Bartholin kisti kanal tıkanmasıdır; Wolffian kalıntı Gartner kistidir.`,sik_aciklamalari:{A:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Bartholin kisti kanal tıkanmasıyla oluşur' seçeneğidir.`,B:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Bartholin kisti kanal tıkanmasıyla oluşur' seçeneğidir.`,C:`Doğru: Bartholin kisti kanal tıkanmasıdır; Wolffian kalıntı Gartner kistidir.`,D:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Bartholin kisti kanal tıkanmasıyla oluşur' seçeneğidir.`,E:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Bartholin kisti kanal tıkanmasıyla oluşur' seçeneğidir.`},bilgi:[4,8,32],benzer_cikmis:[]},{id:`k1-48-vulva-vajen-ve-serviks-hastaliklari-k06-q06`,kazanim:6,zorluk:`orta`,soru:`Bartholin bezi kist ve apsesinin oluşumu ve tedavisi nasıldır?`,secenekler:{A:`Bartholin kisti HPV ile oluşur`,B:`Kanal tıkanması kist-apse; tedavi drenaj-antibiyotik`,C:`Apse kendiliğinden hep geriler`,D:`Tedavi kemoterapi ile yapılır`,E:`Kist neoplastik proliferasyondur`},dogru:`B`,aciklama:`Bartholin bezi salgı kanalı tıkanması ağrılı kist ve sıkça apse oluşturur. Tedavi drenaj ve antibiyotiktir. Gonokok vulvovajinal bezlerin süpüratif enfeksiyonuna yol açabilir.`,sik_aciklamalari:{A:`Yanlış: Neden kanal tıkanmasıdır, HPV değildir.`,B:`Doğru: Tıkanma sekresyon birikimi ve enfeksiyon yapar.`,C:`Yanlış: Apse drenaj gerektirir.`,D:`Yanlış: Kemoterapi endikasyonu yoktur.`,E:`Yanlış: Kist benign retansiyon lezyonudur.`},bilgi:[4,8],benzer_cikmis:[]},{id:`k1-48-vulva-vajen-ve-serviks-hastaliklari-k06-q07`,kazanim:6,zorluk:`orta`,soru:`Bartholin kisti ile Gartner kistinin köken farkı nedir?`,secenekler:{A:`Bartholin kisti Wolffian kalıntısıdır`,B:`Gartner kisti Bartholin kanalı tıkanmasıdır`,C:`HPV aşısı apseleri tedavi eder`,D:`Bartholin tıkanma; Gartner Wolffian kalıntısıdır`,E:`Apse drenajı kontrendikedir`},dogru:`D`,aciklama:`Bartholin kisti salgı kanalı tıkanmasıyla oluşur; Gartner kisti ise lateral vajinal duvardaki Wolffian kalıntısıdır. Apse drenaj gerektirebilir. Gonokok süpüratif bez enfeksiyonu yapar.`,sik_aciklamalari:{A:`Yanlış: Bartholin kisti kanal tıkanmasındandır.`,B:`Yanlış: Gartner kisti Wolffian artığıdır.`,C:`Yanlış: Aşı profilaktiktir, tedavi etmez.`,D:`Doğru: İki kistin kökeni farklıdır.`,E:`Yanlış: Apse drenaj gerektirir.`},bilgi:[8,32],benzer_cikmis:[]},{id:`k1-48-vulva-vajen-ve-serviks-hastaliklari-k06-q08`,kazanim:6,zorluk:`kolay`,soru:`Aşağıdakilerden "Candida albicans vajiniti" ile ilgili doğru olan seçeneği işaretleyiniz.`,secenekler:{E:`Kadınların ~%20'sinde normal vajinal flora üyesidir; semptomatik enfeksiyon yatkınlaştırıcı faktörlere veya virülan bir suşla süperenfeksiyona bağlıdır.`,A:`Vajinanın inflamatuar durumudur; genellikle enfeksiyona bağlı ve geçicidir, temel bulgu vajinal akıntıdır (lökore). Etkenler bakteri, mantar, parazit olup pek çoğu normal kommensal flora üyesidir.`,C:`Nadir bir vajinal tümördür (sarkoma botryoides); histogenezi malign embriyonel rabdomiyoblastlardır ve 5 yaşından küçük bebek ve çocuklarda görülür.`,B:`Sekonder sifilizde görülür; etkeni Treponema pallidum'dur, düz hafif kabarık lezyonlar yapar.`,D:`Epidermis kalınlaşması (akantoz), hiperkeratoz, dermiste bazen lenfositik infiltrasyon ve sitolojik atipisi olmayan artmış mitotik aktivite gösteren hiperplastik epitel vardır.`},dogru:`E`,aciklama:`Doğru: Kadınların ~%20'sinde normal vajinal flora üyesidir; semptomatik enfeksiyon yatkınlaştırıcı faktörlere veya virülan bir suşla süperenfeksiyona bağlıdır.`,sik_aciklamalari:{E:`Doğru. Kadınların ~%20'sinde normal vajinal flora üyesidir; semptomatik enfeksiyon yatkınlaştırıcı faktörlere veya virülan bir suşla süperenfeksiyona bağlıdır.`,A:`Yanlış. Vajinanın inflamatuar durumudur; genellikle enfeksiyona bağlı ve geçicidir, temel bulgu vajinal akıntıdır (lökore). Etkenler bakteri, mantar, parazit olup pek çoğu normal kommensal flora üyesidir.`,C:`Yanlış. Nadir bir vajinal tümördür (sarkoma botryoides); histogenezi malign embriyonel rabdomiyoblastlardır ve 5 yaşından küçük bebek ve çocuklarda görülür.`,B:`Yanlış. Sekonder sifilizde görülür; etkeni Treponema pallidum'dur, düz hafif kabarık lezyonlar yapar.`,D:`Yanlış. Epidermis kalınlaşması (akantoz), hiperkeratoz, dermiste bazen lenfositik infiltrasyon ve sitolojik atipisi olmayan artmış mitotik aktivite gösteren hiperplastik epitel vardır.`},bilgi:[34],benzer_cikmis:[]},{id:`k1-48-vulva-vajen-ve-serviks-hastaliklari-k06-q09`,kazanim:6,zorluk:`orta`,soru:`"Trichomonas vaginalis vajiniti" kavramı hakkında verilen aşağıdakilerden hangisi doğrudur?`,secenekler:{D:`Dünya çapında en yaygın viral olmayan cinsel yolla bulaşan enfeksiyondur; çoğu enfeksiyon asemptomatiktir.`,A:`Vulva dış kadın genital organıdır; kıllı deri (labia majora) ve mukoza (labia minora) içerir.`,C:`En yaygın kondilom tipidir; etkeni düşük riskli HPV tip 6 ve 11'dir, cinsel temasla bulaşır ve sıklıkla genç erişkinlerde görülür.`,B:`Epidermis kalınlaşması (akantoz), hiperkeratoz, dermiste bazen lenfositik infiltrasyon ve sitolojik atipisi olmayan artmış mitotik aktivite gösteren hiperplastik epitel vardır.`,E:`HSV-1 ve HSV-2 genital herpes etkenidir; ağrılı vezikül ve ülserler ile tekrarlayıcı seyir yapar.`},dogru:`D`,aciklama:`Doğru: Dünya çapında en yaygın viral olmayan cinsel yolla bulaşan enfeksiyondur; çoğu enfeksiyon asemptomatiktir.`,sik_aciklamalari:{D:`Doğru. Dünya çapında en yaygın viral olmayan cinsel yolla bulaşan enfeksiyondur; çoğu enfeksiyon asemptomatiktir.`,A:`Yanlış. Vulva dış kadın genital organıdır; kıllı deri (labia majora) ve mukoza (labia minora) içerir.`,C:`Yanlış. En yaygın kondilom tipidir; etkeni düşük riskli HPV tip 6 ve 11'dir, cinsel temasla bulaşır ve sıklıkla genç erişkinlerde görülür.`,B:`Yanlış. Epidermis kalınlaşması (akantoz), hiperkeratoz, dermiste bazen lenfositik infiltrasyon ve sitolojik atipisi olmayan artmış mitotik aktivite gösteren hiperplastik epitel vardır.`,E:`Yanlış. HSV-1 ve HSV-2 genital herpes etkenidir; ağrılı vezikül ve ülserler ile tekrarlayıcı seyir yapar.`},bilgi:[35],benzer_cikmis:[]},{id:`k1-48-vulva-vajen-ve-serviks-hastaliklari-k06-q10`,kazanim:6,zorluk:`orta`,soru:`"Trichomonas vaginalis vajiniti" ile ilgili aşağıdakilerden hangisi yanlıştır?`,secenekler:{B:`Dünya çapında en yaygın viral olmayan cinsel yolla bulaşan enfeksiyondur; çoğu enfeksiyon asemptomatiktir.`,A:`Vulvar kondilomlar kansere dönüşmez ancak vajina ve servikste HPV ilişkili prekanseröz lezyon riski artar.`,D:`Vulva dış kadın genital organıdır; kıllı deri (labia majora) ve mukoza (labia minora) içerir.`,E:`Gram negatif kokobasildir ve bakteriyel vajinozun ana nedenidir; ince, gri beyaz, kötü kokulu akıntı ve 'balık kokusu' şikayeti görülür.`,C:`Her yaşta görülebilir (menopoz sonrası kadınlar, ergenlik öncesi kızlar); patogenezi belirsizdir, subepiteliyal aktif T hücre infiltrasyonu ve otoimmün bozukluklarla birliktelik vardır.`},dogru:`B`,aciklama:`Doğru: Dünya çapında en yaygın viral olmayan cinsel yolla bulaşan enfeksiyondur; çoğu enfeksiyon asemptomatiktir.`,sik_aciklamalari:{B:`Doğru. Dünya çapında en yaygın viral olmayan cinsel yolla bulaşan enfeksiyondur; çoğu enfeksiyon asemptomatiktir.`,A:`Yanlış. Vulvar kondilomlar kansere dönüşmez ancak vajina ve servikste HPV ilişkili prekanseröz lezyon riski artar.`,D:`Yanlış. Vulva dış kadın genital organıdır; kıllı deri (labia majora) ve mukoza (labia minora) içerir.`,E:`Yanlış. Gram negatif kokobasildir ve bakteriyel vajinozun ana nedenidir; ince, gri beyaz, kötü kokulu akıntı ve 'balık kokusu' şikayeti görülür.`,C:`Yanlış. Her yaşta görülebilir (menopoz sonrası kadınlar, ergenlik öncesi kızlar); patogenezi belirsizdir, subepiteliyal aktif T hücre infiltrasyonu ve otoimmün bozukluklarla birliktelik vardır.`},bilgi:[35],benzer_cikmis:[]},{id:`k1-48-vulva-vajen-ve-serviks-hastaliklari-k06-q11`,kazanim:6,zorluk:`zor`,soru:`"Liken skleroz: histoloji" bilgisini içeren doğru kurulum aşağıdakilerden hangisidir?`,secenekler:{C:`Epidermis incelmesi, rete çıkıntılarının kaybı, hücresiz homojen dermal fibrozis alanı ve bant tarzında mononükleer inflamatuar infiltrat vardır.`,A:`Kadınların ~%20'sinde normal vajinal flora üyesidir; semptomatik enfeksiyon yatkınlaştırıcı faktörlere veya virülan bir suşla süperenfeksiyona bağlıdır.`,E:`Her yaşta görülebilir (menopoz sonrası kadınlar, ergenlik öncesi kızlar); patogenezi belirsizdir, subepiteliyal aktif T hücre infiltrasyonu ve otoimmün bozukluklarla birliktelik vardır.`,B:`Çoğu cinsel yolla bulaşır: HPV, HSV-1/HSV-2, Neisseria gonorrhoeae, Treponema pallidum ve Candida türleri.`,D:`Papiller ekzofitik stromal çekirdekler, üzerinde kalınlaşmış skuamöz epitel ve viral sitopatik değişiklikler (koilositik atipi, büyümüş buruşuk çekirdek, hiperkromazi, sitoplazmik perinükleer halo) vardır.`},dogru:`C`,aciklama:`Doğru: Epidermis incelmesi, rete çıkıntılarının kaybı, hücresiz homojen dermal fibrozis alanı ve bant tarzında mononükleer inflamatuar infiltrat vardır.`,sik_aciklamalari:{C:`Doğru. Epidermis incelmesi, rete çıkıntılarının kaybı, hücresiz homojen dermal fibrozis alanı ve bant tarzında mononükleer inflamatuar infiltrat vardır.`,A:`Yanlış. Kadınların ~%20'sinde normal vajinal flora üyesidir; semptomatik enfeksiyon yatkınlaştırıcı faktörlere veya virülan bir suşla süperenfeksiyona bağlıdır.`,E:`Yanlış. Her yaşta görülebilir (menopoz sonrası kadınlar, ergenlik öncesi kızlar); patogenezi belirsizdir, subepiteliyal aktif T hücre infiltrasyonu ve otoimmün bozukluklarla birliktelik vardır.`,B:`Yanlış. Çoğu cinsel yolla bulaşır: HPV, HSV-1/HSV-2, Neisseria gonorrhoeae, Treponema pallidum ve Candida türleri.`,D:`Yanlış. Papiller ekzofitik stromal çekirdekler, üzerinde kalınlaşmış skuamöz epitel ve viral sitopatik değişiklikler (koilositik atipi, büyümüş buruşuk çekirdek, hiperkromazi, sitoplazmik perinükleer halo) vardır.`},bilgi:[11],benzer_cikmis:[]}],ilgili_cikmis:[]},{no:7,metin:`Liken skleroz ve skuamöz hücre hiperplazisinin klinik ve histolojik özelliklerini açıklayabilmek`,sorular:[{id:`k1-48-q19`,kazanim:7,zorluk:`kolay`,soru:`Liken sklerozun karakteristik histolojik bulgusu hangisidir?`,secenekler:{A:`Koilositoz`,B:`Belirgin akantoz ve hiperkeratoz`,C:`Epidermis incelmesi ve hücresiz homojen dermal fibrozis`,D:`Cowdry A inklüzyonları`,E:`Bazal tabakada atipik keratinizasyon`},dogru:`C`,aciklama:`Liken sklerozda epidermis incelir, rete çıkıntıları kaybolur, homojen hücresiz dermal fibrozis ve bant tarzı infiltrat görülür.`,sik_aciklamalari:{A:`Koilositoz HPV enfeksiyonunu gösterir.`,B:`Akantoz ve hiperkeratoz skuamöz hücre hiperplazisine aittir.`,C:`Doğru: tipik histolojik bulgulardır.`,D:`Cowdry A inklüzyonları herpese aittir.`,E:`Bazal tabakada atipik keratinizasyon dVIN bulgusudur.`},bilgi:[11],benzer_cikmis:[`59aa2cf4d0fa`]},{id:`k1-48-q20`,kazanim:7,zorluk:`orta`,soru:`Liken skleroz ile ilgili aşağıdakilerden hangisi yanlıştır?`,secenekler:{A:`Menopoz sonrası kadınlarda ve ergenlik öncesi kızlarda görülebilir`,B:`Otoimmün bozukluklarla birliktelik gösterir`,C:`Labialar atrofik ve sert hale gelir, vajinal açıklık daralabilir`,D:`Vulvar skuamöz hücreli karsinom riski biraz artmıştır`,E:`Prekanseröz lezyon olarak kabul edilir ve mutlaka karsinoma dönüşür`},dogru:`E`,aciklama:`Liken skleroz karsinom riskini biraz artırır ancak prekanseröz lezyon değildir; uzun dönem takip önerilir.`,sik_aciklamalari:{A:`Doğru ifade: her yaşta, özellikle bu iki grupta görülür.`,B:`Doğru ifade: otoimmün zemin ve T hücre infiltrasyonu vardır.`,C:`Doğru ifade: sklerotik-atrofik değişiklikler gelişir.`,D:`Doğru ifade: SCC riski hafif artmıştır.`,E:`Yanlış ifade (aranan cevap): prekanseröz değildir.`},bilgi:[10,12,13],benzer_cikmis:[]},{id:`k1-48-q21`,kazanim:7,zorluk:`zor`,soru:`Şiddetli kaşıntı nedeniyle sürekli kaşıma öyküsü olan kadında vulvada beyaz plak (lökoplaki) biyopsisinde epidermis kalınlaşması, hiperkeratoz ve atipisiz artmış mitoz izleniyor.

Bu lezyonun tanısı ve eski adı hangisidir?`,secenekler:{A:`Kondiloma lata – sekonder sifilis`,B:`Liken skleroz – hiperplastik distrofi`,C:`dVIN – karsinoma in situ`,D:`Skuamöz hücre hiperplazisi – liken simpleks kronikus`,E:`Ekstramammary Paget – intraepitelyal adenokarsinom`},dogru:`D`,aciklama:`Kaşımaya bağlı skuamöz hücre hiperplazisinin eski isimleri hiperplastik distrofi ve liken simpleks kronikustur; atipi yoktur.`,sik_aciklamalari:{A:`Kondiloma lata düz kabarık sifilitik lezyondur.`,B:`Liken sklerozda epidermis incelir; hiperplastik distrofi skuamöz hiperplazinin eski adıdır.`,C:`dVIN'de bazal atipi vardır.`,D:`Doğru: klinik ve histoloji uyumludur.`,E:`Paget'te epidermiste büyük soluk hücreler görülür.`},bilgi:[14,15],benzer_cikmis:[`f17c4ebee26c`]},{id:`k1-48-vulva-vajen-ve-serviks-hastaliklari-k07-q04`,kazanim:7,zorluk:`orta`,soru:`Menopoz sonrası kadında beyaz sklerotik plaklar ve daralmış introitus var; biyopsi isteniyor. Liken skleroz için aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`Epidermis kalınlaşır`,B:`Atipi tam kattadır`,C:`Epidermis incelmesi, rete kaybı, homojen dermal fibrozis ve bant infiltrat tipiktir; prekanseröz değildir ancak SCC riski biraz artar`,D:`Prekanserözdür ve hep kansere dönüşür`,E:`Yalnızca gençte görülür`},dogru:`C`,aciklama:`Histoloji incelme + fibrozistir; risk hafif artar ama prekanseröz değildir.`,sik_aciklamalari:{A:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Epidermis incelmesi, rete kaybı, homojen dermal fibrozis ve bant infiltrat tipiktir; prekanseröz değildir ancak SCC riski biraz artar' seçeneğidir.`,B:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Epidermis incelmesi, rete kaybı, homojen dermal fibrozis ve bant infiltrat tipiktir; prekanseröz değildir ancak SCC riski biraz artar' seçeneğidir.`,C:`Doğru: Histoloji incelme + fibrozistir; risk hafif artar ama prekanseröz değildir.`,D:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Epidermis incelmesi, rete kaybı, homojen dermal fibrozis ve bant infiltrat tipiktir; prekanseröz değildir ancak SCC riski biraz artar' seçeneğidir.`,E:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Epidermis incelmesi, rete kaybı, homojen dermal fibrozis ve bant infiltrat tipiktir; prekanseröz değildir ancak SCC riski biraz artar' seçeneğidir.`},bilgi:[10,11,13],benzer_cikmis:[]},{id:`k1-48-vulva-vajen-ve-serviks-hastaliklari-k07-q05`,kazanim:7,zorluk:`zor`,soru:`Kaşımaya bağlı kalınlaşmış lökoplakik lezyonun eski adı soruluyor. Aşağıdakilerden hangisi yanlıştır?`,secenekler:{A:`Skuamöz hiperplazinin eski adları hiperplastik distrofi ve liken simpleks kronikustur`,B:`Histolojide akantoz, hiperkeratoz ve atipisiz mitoz artışı vardır`,C:`Liken skleroz otoimmün zeminlidir`,D:`Liken sklerozda epidermis kalınlaşır ve skuamöz hiperplazi prekanserözdür`,E:`Her iki tablo da lökoplaki yapabilir`},dogru:`A`,aciklama:`Liken sklerozda epidermis incelir; skuamöz hiperplazi atipisizdir.`,sik_aciklamalari:{A:`Doğru: Liken sklerozda epidermis incelir; skuamöz hiperplazi atipisizdir.`,B:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Skuamöz hiperplazinin eski adları hiperplastik distrofi ve liken simpleks kronikustur' seçeneğidir.`,C:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Skuamöz hiperplazinin eski adları hiperplastik distrofi ve liken simpleks kronikustur' seçeneğidir.`,D:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Skuamöz hiperplazinin eski adları hiperplastik distrofi ve liken simpleks kronikustur' seçeneğidir.`,E:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Skuamöz hiperplazinin eski adları hiperplastik distrofi ve liken simpleks kronikustur' seçeneğidir.`},bilgi:[11,12,14,15],benzer_cikmis:[]},{id:`k1-48-vulva-vajen-ve-serviks-hastaliklari-k07-q06`,kazanim:7,zorluk:`orta`,soru:`Liken sklerozun histolojisi ve onkolojik riski nasıldır?`,secenekler:{A:`İncelme, rete kaybı, fibrozis; prekanseröz değil`,B:`Epidermis kalınlaşır ve tam kat atipi vardır`,C:`Prekanserözdür ve hep kansere dönüşür`,D:`Yalnızca genç kadınlarda görülür`,E:`Bant infiltrat hiç görülmez`},dogru:`A`,aciklama:`Liken sklerozda epidermis incelmesi, rete kaybı, homojen dermal fibrozis ve bant infiltrat tipiktir. Prekanseröz değildir ancak skuamöz karsinom riski biraz artar. Vajinal açıklık daralabilir, labialar atrofikleşir.`,sik_aciklamalari:{A:`Doğru: Histoloji incelme-fibrozistir; risk hafif artar.`,B:`Yanlış: Kalınlaşma hiperplaziye, atipi neoplaziye aittir.`,C:`Yanlış: Prekanseröz değildir, risk artışı sınırlıdır.`,D:`Yanlış: Menopoz sonrası ve prepubertal de görülür.`,E:`Yanlış: Bant mononükleer infiltrat tipiktir.`},bilgi:[10,11,13],benzer_cikmis:[]},{id:`k1-48-vulva-vajen-ve-serviks-hastaliklari-k07-q07`,kazanim:7,zorluk:`orta`,soru:`Skuamöz hücre hiperplazisinin nedeni ve histolojisi nedir?`,secenekler:{A:`Liken sklerozda epidermis kalınlaşır`,B:`Skuamöz hiperplazi prekanserözdür`,C:`Kaşımaya bağlı akantoz; atipi yoktur`,D:`Lökoplaki bu tablolarda görülmez`,E:`Otoimmün birliktelik hiperplaziye özgüdür`},dogru:`C`,aciklama:`Skuamöz hiperplazinin eski adları hiperplastik distrofi ve liken simpleks kronikustur; kaşıma-ovmaya bağlı gelişir. Histolojide akantoz, hiperkeratoz ve atipisiz mitoz artışı vardır. Her iki tablo da lökoplaki yapabilir.`,sik_aciklamalari:{A:`Yanlış: Liken sklerozda epidermis incelir.`,B:`Yanlış: Atipi yokluğu benign olduğunu gösterir.`,C:`Doğru: Kronik travma hiperplaziyi, atipi yokluğu benignliği gösterir.`,D:`Yanlış: İkisi de beyaz plak yapar.`,E:`Yanlış: Otoimmün birliktelik liken sklerozdadır.`},bilgi:[14,15],benzer_cikmis:[]},{id:`k1-48-vulva-vajen-ve-serviks-hastaliklari-k07-q08`,kazanim:7,zorluk:`kolay`,soru:`"Vulvar skuamöz hücreli karsinomun iki grubu" kavramının tanımı aşağıdakilerden hangisidir?`,secenekler:{A:`1) Bazaloid/siğil benzeri karsinom yüksek riskli HPV ile ilişkilidir. 2) Keratinize skuamöz hücreli karsinom HPV ile ilişkili değildir ve liken skleroz veya skuamöz hücre hiperplazisi zemininde gelişir.`,B:`HPV pozitif tümörler sıklıkla multifokal, siğil benzeri ve genellikle kötü diferansiye; HPV negatif tümörler genellikle unifokal ve iyi diferansiye, keratinize skuamöz hücreli karsinomdur.`,E:`Dünya çapında en yaygın viral olmayan cinsel yolla bulaşan enfeksiyondur; çoğu enfeksiyon asemptomatiktir.`,D:`Vajinanın inflamatuar durumudur; genellikle enfeksiyona bağlı ve geçicidir, temel bulgu vajinal akıntıdır (lökore). Etkenler bakteri, mantar, parazit olup pek çoğu normal kommensal flora üyesidir.`,C:`Son derece nadirdir; neredeyse tüm primer karsinomlar yüksek riskli HPV ile ilişkili skuamöz hücreli karsinomdur; en büyük risk faktörü daha önce serviks veya vulva karsinomu öyküsüdür.`},dogru:`A`,aciklama:`Doğru: 1) Bazaloid/siğil benzeri karsinom yüksek riskli HPV ile ilişkilidir. 2) Keratinize skuamöz hücreli karsinom HPV ile ilişkili değildir ve liken skleroz veya skuamöz hücre hiperplazisi zemininde gelişir.`,sik_aciklamalari:{A:`Doğru. 1) Bazaloid/siğil benzeri karsinom yüksek riskli HPV ile ilişkilidir. 2) Keratinize skuamöz hücreli karsinom HPV ile ilişkili değildir ve liken skleroz veya skuamöz hücre hiperplazisi zemininde gelişir.`,B:`Yanlış. HPV pozitif tümörler sıklıkla multifokal, siğil benzeri ve genellikle kötü diferansiye; HPV negatif tümörler genellikle unifokal ve iyi diferansiye, keratinize skuamöz hücreli karsinomdur.`,E:`Yanlış. Dünya çapında en yaygın viral olmayan cinsel yolla bulaşan enfeksiyondur; çoğu enfeksiyon asemptomatiktir.`,D:`Yanlış. Vajinanın inflamatuar durumudur; genellikle enfeksiyona bağlı ve geçicidir, temel bulgu vajinal akıntıdır (lökore). Etkenler bakteri, mantar, parazit olup pek çoğu normal kommensal flora üyesidir.`,C:`Yanlış. Son derece nadirdir; neredeyse tüm primer karsinomlar yüksek riskli HPV ile ilişkili skuamöz hücreli karsinomdur; en büyük risk faktörü daha önce serviks veya vulva karsinomu öyküsüdür.`},bilgi:[23],benzer_cikmis:[]},{id:`k1-48-vulva-vajen-ve-serviks-hastaliklari-k07-q09`,kazanim:7,zorluk:`orta`,soru:`"Vajinit tanımı ve yatkınlık" kavramı hakkında verilen aşağıdakilerden hangisi doğrudur?`,secenekler:{D:`Vajinanın inflamatuar durumudur; genellikle enfeksiyona bağlı ve geçicidir, temel bulgu vajinal akıntıdır (lökore). Etkenler bakteri, mantar, parazit olup pek çoğu normal kommensal flora üyesidir.`,E:`Her yaşta görülebilir (menopoz sonrası kadınlar, ergenlik öncesi kızlar); patogenezi belirsizdir, subepiteliyal aktif T hücre infiltrasyonu ve otoimmün bozukluklarla birliktelik vardır.`,C:`Vulvit vulvanın inflamasyonudur; sık görülen, çok nedenli bir durumdur ve sıklıkla yoğun kaşıntı ile seyreder.`,B:`Son derece nadirdir; neredeyse tüm primer karsinomlar yüksek riskli HPV ile ilişkili skuamöz hücreli karsinomdur; en büyük risk faktörü daha önce serviks veya vulva karsinomu öyküsüdür.`,A:`Tüm kadın genital sistem kanserlerinin ~%3'ü; 60 yaş üstü kadınlarda görülür; histolojik tiplerin ~%90'ı skuamöz hücreli karsinom, diğerleri adenokarsinom ve bazal hücreli karsinomdur.`},dogru:`D`,aciklama:`Doğru: Vajinanın inflamatuar durumudur; genellikle enfeksiyona bağlı ve geçicidir, temel bulgu vajinal akıntıdır (lökore). Etkenler bakteri, mantar, parazit olup pek çoğu normal kommensal flora üyesidir.`,sik_aciklamalari:{D:`Doğru. Vajinanın inflamatuar durumudur; genellikle enfeksiyona bağlı ve geçicidir, temel bulgu vajinal akıntıdır (lökore). Etkenler bakteri, mantar, parazit olup pek çoğu normal kommensal flora üyesidir.`,E:`Yanlış. Her yaşta görülebilir (menopoz sonrası kadınlar, ergenlik öncesi kızlar); patogenezi belirsizdir, subepiteliyal aktif T hücre infiltrasyonu ve otoimmün bozukluklarla birliktelik vardır.`,C:`Yanlış. Vulvit vulvanın inflamasyonudur; sık görülen, çok nedenli bir durumdur ve sıklıkla yoğun kaşıntı ile seyreder.`,B:`Yanlış. Son derece nadirdir; neredeyse tüm primer karsinomlar yüksek riskli HPV ile ilişkili skuamöz hücreli karsinomdur; en büyük risk faktörü daha önce serviks veya vulva karsinomu öyküsüdür.`,A:`Yanlış. Tüm kadın genital sistem kanserlerinin ~%3'ü; 60 yaş üstü kadınlarda görülür; histolojik tiplerin ~%90'ı skuamöz hücreli karsinom, diğerleri adenokarsinom ve bazal hücreli karsinomdur.`},bilgi:[33],benzer_cikmis:[]},{id:`k1-48-vulva-vajen-ve-serviks-hastaliklari-k07-q10`,kazanim:7,zorluk:`orta`,soru:`"HPV ile ilişkili vulvar lezyonlar" ile ilgili aşağıdakilerden hangisi yanlıştır?`,secenekler:{E:`HPV kondiloma akuminatum etkenidir, VIN ile ilişkilidir ve vulvar skuamöz karsinom alt kümesinde rol oynar.`,C:`Klinikte kırmızı, pullu, kabuklu plak kronik dermatiti taklit eder; histolojide büyük hücreler, bol soluk ince granüllü sitoplazma ve epidermiste tek tek/gruplar halinde hücreler vardır; invazyon veya metastaz olmaksızın yıllarca sürebilir.`,B:`Skuamöz hücreli karsinomun öncü lezyonudur ve displazi derecesine göre sınıflanır.`,D:`Reaktif inflamasyon alerjen veya irritan temasına yanıttır; losyon ve sabun katkı maddeleri, antiseptikler ve giysi kimyasalları rol oynar.`,A:`Vajinanın inflamatuar durumudur; genellikle enfeksiyona bağlı ve geçicidir, temel bulgu vajinal akıntıdır (lökore). Etkenler bakteri, mantar, parazit olup pek çoğu normal kommensal flora üyesidir.`},dogru:`E`,aciklama:`Doğru: HPV kondiloma akuminatum etkenidir, VIN ile ilişkilidir ve vulvar skuamöz karsinom alt kümesinde rol oynar.`,sik_aciklamalari:{E:`Doğru. HPV kondiloma akuminatum etkenidir, VIN ile ilişkilidir ve vulvar skuamöz karsinom alt kümesinde rol oynar.`,C:`Yanlış. Klinikte kırmızı, pullu, kabuklu plak kronik dermatiti taklit eder; histolojide büyük hücreler, bol soluk ince granüllü sitoplazma ve epidermiste tek tek/gruplar halinde hücreler vardır; invazyon veya metastaz olmaksızın yıllarca sürebilir.`,B:`Yanlış. Skuamöz hücreli karsinomun öncü lezyonudur ve displazi derecesine göre sınıflanır.`,D:`Yanlış. Reaktif inflamasyon alerjen veya irritan temasına yanıttır; losyon ve sabun katkı maddeleri, antiseptikler ve giysi kimyasalları rol oynar.`,A:`Yanlış. Vajinanın inflamatuar durumudur; genellikle enfeksiyona bağlı ve geçicidir, temel bulgu vajinal akıntıdır (lökore). Etkenler bakteri, mantar, parazit olup pek çoğu normal kommensal flora üyesidir.`},bilgi:[5],benzer_cikmis:[]},{id:`k1-48-vulva-vajen-ve-serviks-hastaliklari-k07-q11`,kazanim:7,zorluk:`zor`,soru:`"Kondiloma akuminatum: etken ve epidemi" ile ilgili bir hastada bulunacak aşağıdaki bulgulardan hangisi beklenmez?`,secenekler:{A:`En yaygın kondilom tipidir; etkeni düşük riskli HPV tip 6 ve 11'dir, cinsel temasla bulaşır ve sıklıkla genç erişkinlerde görülür.`,E:`İki temel tablo liken skleroz ve skuamöz hücre hiperplazisidir; klinik olarak genellikle lökoplaki şeklinde görülürler.`,B:`HPV pozitif tümörler sıklıkla multifokal, siğil benzeri ve genellikle kötü diferansiye; HPV negatif tümörler genellikle unifokal ve iyi diferansiye, keratinize skuamöz hücreli karsinomdur.`,D:`Epidermis incelmesi, rete çıkıntılarının kaybı, hücresiz homojen dermal fibrozis alanı ve bant tarzında mononükleer inflamatuar infiltrat vardır.`,C:`Candida vulvit nedeni olmakla birlikte cinsel yolla bulaşmaz; diyabet, antibiyotik kullanımı, gebelik ve immün yetmezlikte yatkınlık artar.`},dogru:`A`,aciklama:`Doğru: En yaygın kondilom tipidir; etkeni düşük riskli HPV tip 6 ve 11'dir, cinsel temasla bulaşır ve sıklıkla genç erişkinlerde görülür.`,sik_aciklamalari:{A:`Doğru. En yaygın kondilom tipidir; etkeni düşük riskli HPV tip 6 ve 11'dir, cinsel temasla bulaşır ve sıklıkla genç erişkinlerde görülür.`,E:`Yanlış. İki temel tablo liken skleroz ve skuamöz hücre hiperplazisidir; klinik olarak genellikle lökoplaki şeklinde görülürler.`,B:`Yanlış. HPV pozitif tümörler sıklıkla multifokal, siğil benzeri ve genellikle kötü diferansiye; HPV negatif tümörler genellikle unifokal ve iyi diferansiye, keratinize skuamöz hücreli karsinomdur.`,D:`Yanlış. Epidermis incelmesi, rete çıkıntılarının kaybı, hücresiz homojen dermal fibrozis alanı ve bant tarzında mononükleer inflamatuar infiltrat vardır.`,C:`Yanlış. Candida vulvit nedeni olmakla birlikte cinsel yolla bulaşmaz; diyabet, antibiyotik kullanımı, gebelik ve immün yetmezlikte yatkınlık artar.`},bilgi:[19],benzer_cikmis:[]}],ilgili_cikmis:[{id:`59aa2cf4d0fa`,soru:`Vulva, vagen ve servik patolojisi lökoplaki ön tanısıyla biopsi alınan vulvanın nonneoplastik hastalıklarından liken sklerozda beklenmez?`,secenekler:{A:`No`,B:`Bant benzeri mononükleer iltihabi hücre infiltrasyonu`,C:`Epitel kalınlaşması`,D:`Reterde kaybolma`,E:`Dermal fibrozis`},cevap:`A`},{id:`f17c4ebee26c`,soru:`Vulva, vagen ve servik patolojisi lökoplaki ön tanısıyla biopsi alınan vulvanın nonneoplastik hastalıklarından liken simpleks kronikustabeklenmez?`,secenekler:{A:`No`,B:`Bazal ve suprabazal tabakada artmış mitotik aktivite`,C:`Epidermiste incelme`,D:`Bazal dermiste lökositik infiltrasyon`,E:`Hiperkeratoz`},cevap:`A`}]},{no:8,metin:`Lökoplaki ayırıcı tanısını ve biyopsi gerekliliğini kavramak`,sorular:[{id:`k1-48-q22`,kazanim:8,zorluk:`kolay`,soru:`Vulvada lökoplaki saptanan hastada kesin tanı için gereken yaklaşım hangisidir?`,secenekler:{A:`Yalnızca klinik gözlem`,B:`Biyopsi ve mikroskobik inceleme`,C:`Yalnızca topikal steroid denemesi`,D:`Yalnızca serolojik test`,E:`Yalnızca ultrasonografi`},dogru:`B`,aciklama:`Lökoplaki benign ve malign hastalıklarda görülebildiğinden her lökoplakiye biyopsi yapılmalıdır.`,sik_aciklamalari:{A:`Gözlem maligniteyi dışlayamaz.`,B:`Doğru: biyopsi zorunludur.`,C:`Ampirik tedavi tanıyı geciktirebilir.`,D:`Seroloji lökoplaki tanısı koydurmaz.`,E:`Ultrasonografi epitel lezyonunu değerlendiremez.`},bilgi:[16],benzer_cikmis:[]},{id:`k1-48-q23`,kazanim:8,zorluk:`orta`,soru:`Aşağıdakilerden hangisi lökoplaki yapabilen benign hastalıklardan biridir?`,secenekler:{A:`İnvaziv skuamöz hücreli karsinom`,B:`Skuamöz hücreli karsinoma in situ`,C:`Liken planus`,D:`Bazaloid karsinom`,E:`Melanom`},dogru:`C`,aciklama:`Psoriasis ve liken planus benign; karsinoma in situ ve invaziv SCC neoplastik lökoplaki nedenleridir.`,sik_aciklamalari:{A:`İnvaziv SCC maligndir.`,B:`Karsinoma in situ neoplastiktir.`,C:`Doğru: liken planus benign lökoplaki nedenidir.`,D:`Bazaloid karsinom malign tümördür.`,E:`Melanom pigmente malign tümördür.`},bilgi:[16],benzer_cikmis:[]},{id:`k1-48-q24`,kazanim:8,zorluk:`zor`,soru:`Lökoplaki ön tanısıyla vulvar biyopsi yapılan hastalarda aşağıdaki bulgu–tanı eşleştirmelerinden hangisi yanlıştır?`,secenekler:{A:`İnce epidermis, homojen dermal fibrozis – liken skleroz`,B:`Akantoz, hiperkeratoz, atipi yok – skuamöz hücre hiperplazisi`,C:`Bazal tabakaya sınırlı anormal keratinizasyon ve atipi – dVIN`,D:`Tam kat atipi ve stromal invazyon yok – karsinoma in situ`,E:`Koilositoz ve papiller ekzofitik yapı – liken skleroz`},dogru:`E`,aciklama:`Koilositoz ve papiller ekzofitik yapı kondiloma akuminatumun bulgusudur.`,sik_aciklamalari:{A:`Doğru eşleştirme: liken sklerozun tipik histolojisidir.`,B:`Doğru eşleştirme: skuamöz hiperplazi atipisizdir.`,C:`Doğru eşleştirme: dVIN'in tanımıdır.`,D:`Doğru eşleştirme: tam kat atipi invazyonsuz karsinoma in situdur.`,E:`Yanlış eşleştirme (aranan cevap): bu bulgular kondilomaya aittir.`},bilgi:[11,15,16,20,26],benzer_cikmis:[`59aa2cf4d0fa`]},{id:`k1-48-vulva-vajen-ve-serviks-hastaliklari-k08-q04`,kazanim:8,zorluk:`orta`,soru:`Vulvada beyaz plak saptanan hastada yönetim tartışılıyor. Aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`Gözlem yeterlidir`,B:`Ampirik steroid tanıyı koydurur`,C:`Seroloji tanı koydurur`,D:`Ultrason epitel tanısı koydurur`,E:`Her lökoplakide biyopsi zorunludur; benign (psoriasis, liken planus) ve neoplastik (CIS, invaziv SCC) nedenler ayırt edilmelidir`},dogru:`E`,aciklama:`Lökoplaki benign-malign ayrımı ancak biyopsiyle yapılır.`,sik_aciklamalari:{A:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Her lökoplakide biyopsi zorunludur; benign (psoriasis, liken planus) ve neoplastik (CIS, invaziv SCC) nedenler ayırt edilmelidir' seçeneğidir.`,B:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Her lökoplakide biyopsi zorunludur; benign (psoriasis, liken planus) ve neoplastik (CIS, invaziv SCC) nedenler ayırt edilmelidir' seçeneğidir.`,C:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Her lökoplakide biyopsi zorunludur; benign (psoriasis, liken planus) ve neoplastik (CIS, invaziv SCC) nedenler ayırt edilmelidir' seçeneğidir.`,D:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Her lökoplakide biyopsi zorunludur; benign (psoriasis, liken planus) ve neoplastik (CIS, invaziv SCC) nedenler ayırt edilmelidir' seçeneğidir.`,E:`Doğru: Lökoplaki benign-malign ayrımı ancak biyopsiyle yapılır.`},bilgi:[16],benzer_cikmis:[]},{id:`k1-48-vulva-vajen-ve-serviks-hastaliklari-k08-q05`,kazanim:8,zorluk:`zor`,soru:`Bulgu-tanı eşleştirmesi soruluyor. Aşağıdakilerden hangisi yanlıştır?`,secenekler:{A:`Akantoz + atipi yokluğu skuamöz hiperplazidir`,B:`Bazala sınırlı atipi dVIN'dir`,C:`Koilositoz + papiller yapı liken sklerozdur`,D:`İnce epidermis + homojen fibrozis liken sklerozdur`,E:`Tam kat atipi invazyonsuz CIS'tir`},dogru:`D`,aciklama:`Koilositoz + papiller yapı kondiloma akuminatumundur.`,sik_aciklamalari:{A:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'İnce epidermis + homojen fibrozis liken sklerozdur' seçeneğidir.`,B:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'İnce epidermis + homojen fibrozis liken sklerozdur' seçeneğidir.`,C:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'İnce epidermis + homojen fibrozis liken sklerozdur' seçeneğidir.`,D:`Doğru: Koilositoz + papiller yapı kondiloma akuminatumundur.`,E:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'İnce epidermis + homojen fibrozis liken sklerozdur' seçeneğidir.`},bilgi:[11,15,16,20,26],benzer_cikmis:[]},{id:`k1-48-vulva-vajen-ve-serviks-hastaliklari-k08-q06`,kazanim:8,zorluk:`orta`,soru:`Vulvar lökoplakide neden biyopsi zorunludur?`,secenekler:{A:`Gözlem tek başına yeterlidir`,B:`Ampirik steroid tanı koydurur`,C:`Seroloji epitel tanısı koydurur`,D:`Ultrason maligniteyi dışlar`,E:`Her lökoplakide biyopsi; benign-malign ayrımı gerekir`},dogru:`E`,aciklama:`Her lökoplakide biyopsi zorunludur; benign (psoriasis, liken planus) ve neoplastik (CIS, invaziv SCC) nedenler ancak histolojiyle ayırt edilir. Beyaz plak nonspesifik bir görünümdür. Ampirik tedavi tanıyı geciktirir.`,sik_aciklamalari:{A:`Yanlış: Gözlem invaziv kanseri atlayabilir.`,B:`Yanlış: Steroid histolojiyi değiştirip tanıyı geciktirir.`,C:`Yanlış: Seroloji epitel lezyonunu tanımlamaz.`,D:`Yanlış: Ultrason epitel atipisini göstermez.`,E:`Doğru: Beyaz plak benign-malign ayrımı biyopsiyle yapılır.`},bilgi:[16],benzer_cikmis:[]},{id:`k1-48-vulva-vajen-ve-serviks-hastaliklari-k08-q07`,kazanim:8,zorluk:`orta`,soru:`Lökoplaki ayırıcı tanısında histolojik bulgu eşleşmesi nasıldır?`,secenekler:{A:`Koilositoz ve papiller yapı liken sklerozdur`,B:`Koilositoz kondilomu; tam kat atipi CIS'i gösterir`,C:`İnce epidermis hiperplaziyi tanımlar`,D:`Akantoz ve atipi yokluğu CIS'tir`,E:`Fibrozis papiller siğili gösterir`},dogru:`B`,aciklama:`İnce epidermis ve homojen fibrozis liken sklerozu, akantoz ve atipi yokluğu hiperplaziyi, tam kat atipi CIS'i gösterir. Koilositoz ve papiller yapı ise kondiloma akuminatumu tanımlar. Her patern farklı biyolojik davranışa işaret eder.`,sik_aciklamalari:{A:`Yanlış: Bu bulgular HPV sitopatisine aittir.`,B:`Doğru: Viral sitopati ve tam kat atipi ayrı antitedir.`,C:`Yanlış: İncelme liken sklerozun bulgusudur.`,D:`Yanlış: Atipi yokluğu benign hiperplazidir.`,E:`Yanlış: Fibrozis liken sklerozda görülür.`},bilgi:[11,15,20],benzer_cikmis:[]},{id:`k1-48-vulva-vajen-ve-serviks-hastaliklari-k08-q08`,kazanim:8,zorluk:`kolay`,soru:`Aşağıdakilerden "Vulvar karsinom epidemiyolojisi" ile ilgili doğru olan seçeneği işaretleyiniz.`,secenekler:{A:`Tüm kadın genital sistem kanserlerinin ~%3'ü; 60 yaş üstü kadınlarda görülür; histolojik tiplerin ~%90'ı skuamöz hücreli karsinom, diğerleri adenokarsinom ve bazal hücreli karsinomdur.`,D:`VIN seyri yüksek dereceli atipi ve karsinoma in situ gelişimidir; invaziv karsinom riski 45 yaşından büyük kadınlarda ve immün sistemi baskılanmış hastalarda artar.`,E:`Daha az yaygın formdur, HPV tip 16 ile ilişkilidir, ortalama yaş ~60'tır, sıklıkla sigara içen kadınlarda ve çoğunlukla çok odaklı lezyonlar şeklinde görülür.`,B:`Uzun süre lokal kalma eğilimi vardır; ilk yayılım bölgesel lenf düğümlerine, ileri evrede akciğer ve diğer organlara hematogen metastaz olur.`,C:`Bartholin bezi salgı kanalı tıkanması ağrılı gland genişlemesi (Bartholin kisti) ve sıkça apse oluşumuna yol açar.`},dogru:`A`,aciklama:`Doğru: Tüm kadın genital sistem kanserlerinin ~%3'ü; 60 yaş üstü kadınlarda görülür; histolojik tiplerin ~%90'ı skuamöz hücreli karsinom, diğerleri adenokarsinom ve bazal hücreli karsinomdur.`,sik_aciklamalari:{A:`Doğru. Tüm kadın genital sistem kanserlerinin ~%3'ü; 60 yaş üstü kadınlarda görülür; histolojik tiplerin ~%90'ı skuamöz hücreli karsinom, diğerleri adenokarsinom ve bazal hücreli karsinomdur.`,D:`Yanlış. VIN seyri yüksek dereceli atipi ve karsinoma in situ gelişimidir; invaziv karsinom riski 45 yaşından büyük kadınlarda ve immün sistemi baskılanmış hastalarda artar.`,E:`Yanlış. Daha az yaygın formdur, HPV tip 16 ile ilişkilidir, ortalama yaş ~60'tır, sıklıkla sigara içen kadınlarda ve çoğunlukla çok odaklı lezyonlar şeklinde görülür.`,B:`Yanlış. Uzun süre lokal kalma eğilimi vardır; ilk yayılım bölgesel lenf düğümlerine, ileri evrede akciğer ve diğer organlara hematogen metastaz olur.`,C:`Yanlış. Bartholin bezi salgı kanalı tıkanması ağrılı gland genişlemesi (Bartholin kisti) ve sıkça apse oluşumuna yol açar.`},bilgi:[22],benzer_cikmis:[]},{id:`k1-48-vulva-vajen-ve-serviks-hastaliklari-k08-q09`,kazanim:8,zorluk:`orta`,soru:`"Candida enfeksiyonu (vulva)" kavramı hakkında verilen aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`Candida vulvit nedeni olmakla birlikte cinsel yolla bulaşmaz; diyabet, antibiyotik kullanımı, gebelik ve immün yetmezlikte yatkınlık artar.`,B:`Kadınların ~%20'sinde normal vajinal flora üyesidir; semptomatik enfeksiyon yatkınlaştırıcı faktörlere veya virülan bir suşla süperenfeksiyona bağlıdır.`,C:`Skuamöz hücreli karsinomun öncü lezyonudur ve displazi derecesine göre sınıflanır.`,E:`Epidermis kalınlaşması (akantoz), hiperkeratoz, dermiste bazen lenfositik infiltrasyon ve sitolojik atipisi olmayan artmış mitotik aktivite gösteren hiperplastik epitel vardır.`,D:`HSV-1 ve HSV-2 genital herpes etkenidir; ağrılı vezikül ve ülserler ile tekrarlayıcı seyir yapar.`},dogru:`A`,aciklama:`Doğru: Candida vulvit nedeni olmakla birlikte cinsel yolla bulaşmaz; diyabet, antibiyotik kullanımı, gebelik ve immün yetmezlikte yatkınlık artar.`,sik_aciklamalari:{A:`Doğru. Candida vulvit nedeni olmakla birlikte cinsel yolla bulaşmaz; diyabet, antibiyotik kullanımı, gebelik ve immün yetmezlikte yatkınlık artar.`,B:`Yanlış. Kadınların ~%20'sinde normal vajinal flora üyesidir; semptomatik enfeksiyon yatkınlaştırıcı faktörlere veya virülan bir suşla süperenfeksiyona bağlıdır.`,C:`Yanlış. Skuamöz hücreli karsinomun öncü lezyonudur ve displazi derecesine göre sınıflanır.`,E:`Yanlış. Epidermis kalınlaşması (akantoz), hiperkeratoz, dermiste bazen lenfositik infiltrasyon ve sitolojik atipisi olmayan artmış mitotik aktivite gösteren hiperplastik epitel vardır.`,D:`Yanlış. HSV-1 ve HSV-2 genital herpes etkenidir; ağrılı vezikül ve ülserler ile tekrarlayıcı seyir yapar.`},bilgi:[7],benzer_cikmis:[]},{id:`k1-48-vulva-vajen-ve-serviks-hastaliklari-k08-q10`,kazanim:8,zorluk:`orta`,soru:`"Liken skleroz: histoloji" kavramı hakkında verilen aşağıdakilerden hangisi doğrudur?`,secenekler:{C:`Epidermis incelmesi, rete çıkıntılarının kaybı, hücresiz homojen dermal fibrozis alanı ve bant tarzında mononükleer inflamatuar infiltrat vardır.`,B:`İki temel tablo liken skleroz ve skuamöz hücre hiperplazisidir; klinik olarak genellikle lökoplaki şeklinde görülürler.`,A:`Eski isimleri hiperplastik distrofi ve liken simpleks kronikustur; nedeni şiddetli kaşıntıyı gidermek için ovma/kaşımadır ve lökoplaki görünümü oluşturur.`,D:`HSV-1 ve HSV-2 genital herpes etkenidir; ağrılı vezikül ve ülserler ile tekrarlayıcı seyir yapar.`,E:`VIN seyri yüksek dereceli atipi ve karsinoma in situ gelişimidir; invaziv karsinom riski 45 yaşından büyük kadınlarda ve immün sistemi baskılanmış hastalarda artar.`},dogru:`C`,aciklama:`Doğru: Epidermis incelmesi, rete çıkıntılarının kaybı, hücresiz homojen dermal fibrozis alanı ve bant tarzında mononükleer inflamatuar infiltrat vardır.`,sik_aciklamalari:{C:`Doğru. Epidermis incelmesi, rete çıkıntılarının kaybı, hücresiz homojen dermal fibrozis alanı ve bant tarzında mononükleer inflamatuar infiltrat vardır.`,B:`Yanlış. İki temel tablo liken skleroz ve skuamöz hücre hiperplazisidir; klinik olarak genellikle lökoplaki şeklinde görülürler.`,A:`Yanlış. Eski isimleri hiperplastik distrofi ve liken simpleks kronikustur; nedeni şiddetli kaşıntıyı gidermek için ovma/kaşımadır ve lökoplaki görünümü oluşturur.`,D:`Yanlış. HSV-1 ve HSV-2 genital herpes etkenidir; ağrılı vezikül ve ülserler ile tekrarlayıcı seyir yapar.`,E:`Yanlış. VIN seyri yüksek dereceli atipi ve karsinoma in situ gelişimidir; invaziv karsinom riski 45 yaşından büyük kadınlarda ve immün sistemi baskılanmış hastalarda artar.`},bilgi:[11],benzer_cikmis:[]},{id:`k1-48-vulva-vajen-ve-serviks-hastaliklari-k08-q11`,kazanim:8,zorluk:`zor`,soru:`"Non-neoplastik epitel bozuklukları" bilgisini içeren doğru kurulum aşağıdakilerden hangisidir?`,secenekler:{D:`İki temel tablo liken skleroz ve skuamöz hücre hiperplazisidir; klinik olarak genellikle lökoplaki şeklinde görülürler.`,C:`Vulvar skuamöz hücreli karsinom riski biraz artmıştır ancak liken skleroz prekanseröz lezyon değildir.`,B:`Skuamöz hücreli karsinomun öncü lezyonudur ve displazi derecesine göre sınıflanır.`,E:`Candida vulvit nedeni olmakla birlikte cinsel yolla bulaşmaz; diyabet, antibiyotik kullanımı, gebelik ve immün yetmezlikte yatkınlık artar.`,A:`Dünya çapında en yaygın viral olmayan cinsel yolla bulaşan enfeksiyondur; çoğu enfeksiyon asemptomatiktir.`},dogru:`D`,aciklama:`Doğru: İki temel tablo liken skleroz ve skuamöz hücre hiperplazisidir; klinik olarak genellikle lökoplaki şeklinde görülürler.`,sik_aciklamalari:{D:`Doğru. İki temel tablo liken skleroz ve skuamöz hücre hiperplazisidir; klinik olarak genellikle lökoplaki şeklinde görülürler.`,C:`Yanlış. Vulvar skuamöz hücreli karsinom riski biraz artmıştır ancak liken skleroz prekanseröz lezyon değildir.`,B:`Yanlış. Skuamöz hücreli karsinomun öncü lezyonudur ve displazi derecesine göre sınıflanır.`,E:`Yanlış. Candida vulvit nedeni olmakla birlikte cinsel yolla bulaşmaz; diyabet, antibiyotik kullanımı, gebelik ve immün yetmezlikte yatkınlık artar.`,A:`Yanlış. Dünya çapında en yaygın viral olmayan cinsel yolla bulaşan enfeksiyondur; çoğu enfeksiyon asemptomatiktir.`},bilgi:[9],benzer_cikmis:[]}],ilgili_cikmis:[{id:`59aa2cf4d0fa`,soru:`Vulva, vagen ve servik patolojisi lökoplaki ön tanısıyla biopsi alınan vulvanın nonneoplastik hastalıklarından liken sklerozda beklenmez?`,secenekler:{A:`No`,B:`Bant benzeri mononükleer iltihabi hücre infiltrasyonu`,C:`Epitel kalınlaşması`,D:`Reterde kaybolma`,E:`Dermal fibrozis`},cevap:`A`}]},{no:9,metin:`Kondiloma lata ve kondiloma akuminatumu ayırt edebilmek`,sorular:[{id:`k1-48-q25`,kazanim:9,zorluk:`kolay`,soru:`Kondiloma latanın etkeni hangisidir?`,secenekler:{A:`HSV-2`,B:`HPV tip 6`,C:`HPV tip 11`,D:`Treponema pallidum`,E:`Candida albicans`},dogru:`D`,aciklama:`Kondiloma lata sekonder sifiliste T. pallidum ile oluşan düz, hafif kabarık lezyondur.`,sik_aciklamalari:{A:`HSV-2 vezikül ve ülser yapar.`,B:`HPV 6 kondiloma akuminatum etkenidir.`,C:`HPV 11 kondiloma akuminatum etkenidir.`,D:`Doğru: kondiloma lata sifilitiktir.`,E:`Candida vulvovajinit yapar.`},bilgi:[18],benzer_cikmis:[]},{id:`k1-48-q26`,kazanim:9,zorluk:`orta`,soru:`Kondiloma akuminatumun histolojik özellikleri arasında aşağıdakilerden hangisi yer almaz?`,secenekler:{A:`Papiller ekzofitik stromal çekirdekler`,B:`Kalınlaşmış skuamöz epitel`,C:`Perinükleer halo ve buruşuk hiperkromatik çekirdekler (koilositoz)`,D:`Büyümüş çekirdekler`,E:`Plazma hücreden zengin infiltrat ve proliferatif endarterit`},dogru:`E`,aciklama:`Kondiloma akuminatumda papiller skuamöz proliferasyon ve koilositik atipi vardır; proliferatif endarterit sifilisin özelliğidir.`,sik_aciklamalari:{A:`Kondilomun yapısal özelliğidir.`,B:`Kondilomda skuamöz epitel kalınlaşır.`,C:`Koilositoz HPV sitopatik etkisidir.`,D:`Viral sitopatik etkiyle çekirdek büyür.`,E:`Doğru: bu bulgu kondiloma lata/sifilise aittir.`},bilgi:[18,20],benzer_cikmis:[]},{id:`k1-48-q27`,kazanim:9,zorluk:`zor`,soru:`Kondiloma lata ve kondiloma akuminatum karşılaştırıldığında hangisi yanlıştır?`,secenekler:{A:`Her ikisi de cinsel yolla bulaşan siğil benzeri lezyonlardır`,B:`Kondiloma akuminatum en yaygın kondilom tipidir`,C:`Kondiloma lata sifilis tedavisi ile geriler`,D:`Vulvar kondiloma akuminatum kansere dönüşmez ancak vajina/serviks HPV lezyon riski artar`,E:`Kondiloma lata HPV aşısı ile önlenebilir`},dogru:`E`,aciklama:`HPV aşısı kondiloma akuminatumu önler; kondiloma lata T. pallidum'a bağlıdır ve aşı ile önlenmez.`,sik_aciklamalari:{A:`Doğru ifade: iki temel cinsel yolla bulaşan kondilom formudur.`,B:`Doğru ifade: akuminatum en sık tiptir.`,C:`Doğru ifade: kondiloma lata sifilis tedavisiyle kaybolur.`,D:`Doğru ifade: vulvar kondilom kansere dönüşmez.`,E:`Yanlış ifade (aranan cevap): HPV aşısı sifilisten korumaz.`},bilgi:[17,18,19,21],benzer_cikmis:[]},{id:`k1-48-vulva-vajen-ve-serviks-hastaliklari-k09-q04`,kazanim:9,zorluk:`orta`,soru:`Siğil benzeri genital lezyonlu iki hasta: biri sekonder sifilizli, diğeri HPV'li. Aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`İkisi de HPV yapar`,B:`Kondiloma lata T. pallidum'a bağlı sekonder sifiliz lezyonudur (düz, hafif kabarık); akuminatum HPV 6/11'e bağlı papiller siğildir`,C:`Lata HPV aşısıyla önlenir`,D:`Akuminatum sifilis yapar`,E:`Lata primer şankrdır`},dogru:`B`,aciklama:`Lata sifilitik, akuminatum HPV siğilidir; HPV aşısı akuminatumu önler.`,sik_aciklamalari:{A:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Kondiloma lata T. pallidum'a bağlı sekonder sifiliz lezyonudur (düz, hafif kabarık); akuminatum HPV 6/11'e bağlı papiller siğildir' seçeneğidir.`,B:`Doğru: Lata sifilitik, akuminatum HPV siğilidir; HPV aşısı akuminatumu önler.`,C:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Kondiloma lata T. pallidum'a bağlı sekonder sifiliz lezyonudur (düz, hafif kabarık); akuminatum HPV 6/11'e bağlı papiller siğildir' seçeneğidir.`,D:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Kondiloma lata T. pallidum'a bağlı sekonder sifiliz lezyonudur (düz, hafif kabarık); akuminatum HPV 6/11'e bağlı papiller siğildir' seçeneğidir.`,E:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Kondiloma lata T. pallidum'a bağlı sekonder sifiliz lezyonudur (düz, hafif kabarık); akuminatum HPV 6/11'e bağlı papiller siğildir' seçeneğidir.`},bilgi:[17,18,19,21],benzer_cikmis:[]},{id:`k1-48-vulva-vajen-ve-serviks-hastaliklari-k09-q05`,kazanim:9,zorluk:`zor`,soru:`Histoloji ve seyir karşılaştırılıyor. Aşağıdakilerden hangisi yanlıştır?`,secenekler:{A:`Latada proliferatif endarterit ve plazmositik infiltrat vardır`,B:`Akuminatumda papiller ekzofitik yapı ve koilositik atipi vardır`,C:`Akuminatum en yaygın kondilomdur`,D:`Latada koilositik atipi ve papiller yapı vardır; akuminatum sifilis tedavisiyle geriler`,E:`Vulvar kondilom kansere dönüşmez`},dogru:`B`,aciklama:`Koilositoz akuminatumundur; lata sifilis tedavisiyle geriler.`,sik_aciklamalari:{A:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Akuminatumda papiller ekzofitik yapı ve koilositik atipi vardır' seçeneğidir.`,B:`Doğru: Koilositoz akuminatumundur; lata sifilis tedavisiyle geriler.`,C:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Akuminatumda papiller ekzofitik yapı ve koilositik atipi vardır' seçeneğidir.`,D:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Akuminatumda papiller ekzofitik yapı ve koilositik atipi vardır' seçeneğidir.`,E:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Akuminatumda papiller ekzofitik yapı ve koilositik atipi vardır' seçeneğidir.`},bilgi:[17,18,20,21],benzer_cikmis:[]},{id:`k1-48-vulva-vajen-ve-serviks-hastaliklari-k09-q06`,kazanim:9,zorluk:`orta`,soru:`Kondiloma lata ile kondiloma akuminatumun etken farkı nedir?`,secenekler:{A:`İkisi de HPV ile oluşur`,B:`Lata HPV aşısıyla önlenir`,C:`Akuminatum sifilizle oluşur`,D:`Lata sifilitik; akuminatum HPV 6-11 siğilidir`,E:`Lata primer şankr lezyonudur`},dogru:`D`,aciklama:`Kondiloma lata T. pallidum'a bağlı sekonder sifiliz lezyonudur; düz, hafif kabarık plaklar yapar. Kondiloma akuminatum HPV 6 ve 11'e bağlı papiller siğildir. Biri sifilitik, diğeri viral etyolojilidir.`,sik_aciklamalari:{A:`Yanlış: Lata treponemal, akuminatum viraldir.`,B:`Yanlış: Aşı HPV siğillerini önler, sifilizi değil.`,C:`Yanlış: Akuminatum HPV 6-11'e bağlıdır.`,D:`Doğru: Düz sifilitik plak ile papiller siğil ayrılır.`,E:`Yanlış: Lata sekonder evre lezyonudur.`},bilgi:[17,18,19],benzer_cikmis:[]},{id:`k1-48-vulva-vajen-ve-serviks-hastaliklari-k09-q07`,kazanim:9,zorluk:`orta`,soru:`Kondiloma lata ve akuminatumun histoloji ve seyir farkı nedir?`,secenekler:{A:`Latada endarterit; akuminatumda koilositoz vardır`,B:`Latada koilositik atipi ve papiller yapı vardır`,C:`Akuminatum sifiliz tedavisiyle geriler`,D:`Lata HPV 6-11 ile oluşur`,E:`Vulvar kondilom hep kansere dönüşür`},dogru:`A`,aciklama:`Latada proliferatif endarterit ve plazmositik infiltrat vardır; sifiliz tedavisiyle geriler. Akuminatumda papiller ekzofitik yapı ve koilositik atipi görülür; en yaygın kondilomdur ve kansere dönüşmez. Histoloji etkeni yansıtır.`,sik_aciklamalari:{A:`Doğru: Vasküler-plazmositik patern sifilize, koilositoz HPV'ye aittir.`,B:`Yanlış: Koilositoz akuminatumun bulgusudur.`,C:`Yanlış: Sifiliz tedavisi latayı geriletir.`,D:`Yanlış: Lata treponemal lezyondur.`,E:`Yanlış: Vulvar kondilom prekanseröz değildir.`},bilgi:[18,20,21],benzer_cikmis:[]},{id:`k1-48-vulva-vajen-ve-serviks-hastaliklari-k09-q08`,kazanim:9,zorluk:`kolay`,soru:`Aşağıdakilerden "Liken skleroz: epidemiyoloji ve patogenez" ile ilgili doğru olan seçeneği işaretleyiniz.`,secenekler:{B:`Her yaşta görülebilir (menopoz sonrası kadınlar, ergenlik öncesi kızlar); patogenezi belirsizdir, subepiteliyal aktif T hücre infiltrasyonu ve otoimmün bozukluklarla birliktelik vardır.`,A:`Gram negatif kokobasildir ve bakteriyel vajinozun ana nedenidir; ince, gri beyaz, kötü kokulu akıntı ve 'balık kokusu' şikayeti görülür.`,D:`Vulvar skuamöz hücreli karsinom riski biraz artmıştır ancak liken skleroz prekanseröz lezyon değildir.`,E:`Papiller ekzofitik stromal çekirdekler, üzerinde kalınlaşmış skuamöz epitel ve viral sitopatik değişiklikler (koilositik atipi, büyümüş buruşuk çekirdek, hiperkromazi, sitoplazmik perinükleer halo) vardır.`,C:`Vulvar kondilomlar kansere dönüşmez ancak vajina ve servikste HPV ilişkili prekanseröz lezyon riski artar.`},dogru:`B`,aciklama:`Doğru: Her yaşta görülebilir (menopoz sonrası kadınlar, ergenlik öncesi kızlar); patogenezi belirsizdir, subepiteliyal aktif T hücre infiltrasyonu ve otoimmün bozukluklarla birliktelik vardır.`,sik_aciklamalari:{B:`Doğru. Her yaşta görülebilir (menopoz sonrası kadınlar, ergenlik öncesi kızlar); patogenezi belirsizdir, subepiteliyal aktif T hücre infiltrasyonu ve otoimmün bozukluklarla birliktelik vardır.`,A:`Yanlış. Gram negatif kokobasildir ve bakteriyel vajinozun ana nedenidir; ince, gri beyaz, kötü kokulu akıntı ve 'balık kokusu' şikayeti görülür.`,D:`Yanlış. Vulvar skuamöz hücreli karsinom riski biraz artmıştır ancak liken skleroz prekanseröz lezyon değildir.`,E:`Yanlış. Papiller ekzofitik stromal çekirdekler, üzerinde kalınlaşmış skuamöz epitel ve viral sitopatik değişiklikler (koilositik atipi, büyümüş buruşuk çekirdek, hiperkromazi, sitoplazmik perinükleer halo) vardır.`,C:`Yanlış. Vulvar kondilomlar kansere dönüşmez ancak vajina ve servikste HPV ilişkili prekanseröz lezyon riski artar.`},bilgi:[12],benzer_cikmis:[]},{id:`k1-48-vulva-vajen-ve-serviks-hastaliklari-k09-q09`,kazanim:9,zorluk:`orta`,soru:`"Liken skleroz: histoloji" kavramı hakkında verilen aşağıdakilerden hangisi doğrudur?`,secenekler:{E:`Epidermis incelmesi, rete çıkıntılarının kaybı, hücresiz homojen dermal fibrozis alanı ve bant tarzında mononükleer inflamatuar infiltrat vardır.`,D:`Bartholin bezi salgı kanalı tıkanması ağrılı gland genişlemesi (Bartholin kisti) ve sıkça apse oluşumuna yol açar.`,A:`Epidermis kalınlaşması (akantoz), hiperkeratoz, dermiste bazen lenfositik infiltrasyon ve sitolojik atipisi olmayan artmış mitotik aktivite gösteren hiperplastik epitel vardır.`,B:`Eski isimleri hiperplastik distrofi ve liken simpleks kronikustur; nedeni şiddetli kaşıntıyı gidermek için ovma/kaşımadır ve lökoplaki görünümü oluşturur.`,C:`Lökoplaki yapabilen benign hastalıklar psoriasis ve liken planus; neoplastik lezyonlar skuamöz hücreli karsinoma in situ ve invaziv skuamöz hücreli karsinomdur.`},dogru:`E`,aciklama:`Doğru: Epidermis incelmesi, rete çıkıntılarının kaybı, hücresiz homojen dermal fibrozis alanı ve bant tarzında mononükleer inflamatuar infiltrat vardır.`,sik_aciklamalari:{E:`Doğru. Epidermis incelmesi, rete çıkıntılarının kaybı, hücresiz homojen dermal fibrozis alanı ve bant tarzında mononükleer inflamatuar infiltrat vardır.`,D:`Yanlış. Bartholin bezi salgı kanalı tıkanması ağrılı gland genişlemesi (Bartholin kisti) ve sıkça apse oluşumuna yol açar.`,A:`Yanlış. Epidermis kalınlaşması (akantoz), hiperkeratoz, dermiste bazen lenfositik infiltrasyon ve sitolojik atipisi olmayan artmış mitotik aktivite gösteren hiperplastik epitel vardır.`,B:`Yanlış. Eski isimleri hiperplastik distrofi ve liken simpleks kronikustur; nedeni şiddetli kaşıntıyı gidermek için ovma/kaşımadır ve lökoplaki görünümü oluşturur.`,C:`Yanlış. Lökoplaki yapabilen benign hastalıklar psoriasis ve liken planus; neoplastik lezyonlar skuamöz hücreli karsinoma in situ ve invaziv skuamöz hücreli karsinomdur.`},bilgi:[11],benzer_cikmis:[]},{id:`k1-48-vulva-vajen-ve-serviks-hastaliklari-k09-q10`,kazanim:9,zorluk:`orta`,soru:`"HPV pozitif/negatif vulvar karsinom farkları" kavramı hakkında verilen aşağıdakilerden hangisi doğrudur?`,secenekler:{D:`HPV pozitif tümörler sıklıkla multifokal, siğil benzeri ve genellikle kötü diferansiye; HPV negatif tümörler genellikle unifokal ve iyi diferansiye, keratinize skuamöz hücreli karsinomdur.`,B:`Vajinanın inflamatuar durumudur; genellikle enfeksiyona bağlı ve geçicidir, temel bulgu vajinal akıntıdır (lökore). Etkenler bakteri, mantar, parazit olup pek çoğu normal kommensal flora üyesidir.`,E:`Her yaşta görülebilir (menopoz sonrası kadınlar, ergenlik öncesi kızlar); patogenezi belirsizdir, subepiteliyal aktif T hücre infiltrasyonu ve otoimmün bozukluklarla birliktelik vardır.`,A:`Son derece nadirdir; neredeyse tüm primer karsinomlar yüksek riskli HPV ile ilişkili skuamöz hücreli karsinomdur; en büyük risk faktörü daha önce serviks veya vulva karsinomu öyküsüdür.`,C:`Epidermis incelmesi, rete çıkıntılarının kaybı, hücresiz homojen dermal fibrozis alanı ve bant tarzında mononükleer inflamatuar infiltrat vardır.`},dogru:`D`,aciklama:`Doğru: HPV pozitif tümörler sıklıkla multifokal, siğil benzeri ve genellikle kötü diferansiye; HPV negatif tümörler genellikle unifokal ve iyi diferansiye, keratinize skuamöz hücreli karsinomdur.`,sik_aciklamalari:{D:`Doğru. HPV pozitif tümörler sıklıkla multifokal, siğil benzeri ve genellikle kötü diferansiye; HPV negatif tümörler genellikle unifokal ve iyi diferansiye, keratinize skuamöz hücreli karsinomdur.`,B:`Yanlış. Vajinanın inflamatuar durumudur; genellikle enfeksiyona bağlı ve geçicidir, temel bulgu vajinal akıntıdır (lökore). Etkenler bakteri, mantar, parazit olup pek çoğu normal kommensal flora üyesidir.`,E:`Yanlış. Her yaşta görülebilir (menopoz sonrası kadınlar, ergenlik öncesi kızlar); patogenezi belirsizdir, subepiteliyal aktif T hücre infiltrasyonu ve otoimmün bozukluklarla birliktelik vardır.`,A:`Yanlış. Son derece nadirdir; neredeyse tüm primer karsinomlar yüksek riskli HPV ile ilişkili skuamöz hücreli karsinomdur; en büyük risk faktörü daha önce serviks veya vulva karsinomu öyküsüdür.`,C:`Yanlış. Epidermis incelmesi, rete çıkıntılarının kaybı, hücresiz homojen dermal fibrozis alanı ve bant tarzında mononükleer inflamatuar infiltrat vardır.`},bilgi:[27],benzer_cikmis:[]},{id:`k1-48-vulva-vajen-ve-serviks-hastaliklari-k09-q11`,kazanim:9,zorluk:`zor`,soru:`"Skuamöz hücre hiperplazisinin histolojisi" bilgisini içeren doğru kurulum aşağıdakilerden hangisidir?`,secenekler:{B:`Epidermis kalınlaşması (akantoz), hiperkeratoz, dermiste bazen lenfositik infiltrasyon ve sitolojik atipisi olmayan artmış mitotik aktivite gösteren hiperplastik epitel vardır.`,A:`Kadınların ~%20'sinde normal vajinal flora üyesidir; semptomatik enfeksiyon yatkınlaştırıcı faktörlere veya virülan bir suşla süperenfeksiyona bağlıdır.`,D:`Skuamöz hücreli karsinomun öncü lezyonudur ve displazi derecesine göre sınıflanır.`,E:`Vajinanın inflamatuar durumudur; genellikle enfeksiyona bağlı ve geçicidir, temel bulgu vajinal akıntıdır (lökore). Etkenler bakteri, mantar, parazit olup pek çoğu normal kommensal flora üyesidir.`,C:`Epidermis incelmesi, rete çıkıntılarının kaybı, hücresiz homojen dermal fibrozis alanı ve bant tarzında mononükleer inflamatuar infiltrat vardır.`},dogru:`B`,aciklama:`Doğru: Epidermis kalınlaşması (akantoz), hiperkeratoz, dermiste bazen lenfositik infiltrasyon ve sitolojik atipisi olmayan artmış mitotik aktivite gösteren hiperplastik epitel vardır.`,sik_aciklamalari:{B:`Doğru. Epidermis kalınlaşması (akantoz), hiperkeratoz, dermiste bazen lenfositik infiltrasyon ve sitolojik atipisi olmayan artmış mitotik aktivite gösteren hiperplastik epitel vardır.`,A:`Yanlış. Kadınların ~%20'sinde normal vajinal flora üyesidir; semptomatik enfeksiyon yatkınlaştırıcı faktörlere veya virülan bir suşla süperenfeksiyona bağlıdır.`,D:`Yanlış. Skuamöz hücreli karsinomun öncü lezyonudur ve displazi derecesine göre sınıflanır.`,E:`Yanlış. Vajinanın inflamatuar durumudur; genellikle enfeksiyona bağlı ve geçicidir, temel bulgu vajinal akıntıdır (lökore). Etkenler bakteri, mantar, parazit olup pek çoğu normal kommensal flora üyesidir.`,C:`Yanlış. Epidermis incelmesi, rete çıkıntılarının kaybı, hücresiz homojen dermal fibrozis alanı ve bant tarzında mononükleer inflamatuar infiltrat vardır.`},bilgi:[15],benzer_cikmis:[]}],ilgili_cikmis:[]},{no:10,metin:`Vulvar karsinomun iki grubunu (HPV pozitif/negatif) ve ön lezyonlarını (VIN, dVIN) açıklayabilmek`,sorular:[{id:`k1-48-q28`,kazanim:10,zorluk:`kolay`,soru:`HPV negatif vulvar skuamöz hücreli karsinomun ön lezyonu hangisidir?`,secenekler:{A:`Kondiloma akuminatum`,B:`Klasik (HPV ilişkili) VIN`,C:`Diferansiye VIN (dVIN)`,D:`Bartholin kisti`,E:`Gartner kanal kisti`},dogru:`C`,aciklama:`HPV negatif keratinize SCC'nin ön lezyonu, bazal tabakaya sınırlı atipi gösteren dVIN'dir.`,sik_aciklamalari:{A:`Kondiloma akuminatum kansere dönüşmez.`,B:`Klasik VIN HPV pozitif bazaloid/siğil benzeri karsinomun öncülüdür.`,C:`Doğru: dVIN HPV'den bağımsız yolun öncülüdür.`,D:`Bartholin kisti benign kistik lezyondur.`,E:`Gartner kisti vajinal Wolffian kalıntısıdır.`},bilgi:[26],benzer_cikmis:[]},{id:`k1-48-q29`,kazanim:10,zorluk:`orta`,soru:`HPV pozitif vulvar karsinom ile ilgili aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`Ortalama yaşı ~75'tir`,B:`HPV tip 16 ile ilişkilidir, sıklıkla sigara içen kadınlarda ve çok odaklı görülür`,C:`Liken skleroz zemininde gelişir`,D:`İyi diferansiye keratinize SCC şeklindedir`,E:`Ön lezyonu dVIN'dir`},dogru:`B`,aciklama:`HPV pozitif tümör HPV 16 ile ilişkili, ortalama ~60 yaşta, sigara içenlerde, çok odaklı ve VIN zemininde gelişir.`,sik_aciklamalari:{A:`~75 yaş HPV negatif gruba aittir.`,B:`Doğru: HPV pozitif grubun özellikleridir.`,C:`Liken skleroz zemini HPV negatif gruptadır.`,D:`HPV pozitif tümörler bazaloid/siğil benzeri ve sıklıkla kötü diferansiyedir.`,E:`dVIN HPV negatif grubun ön lezyonudur.`},bilgi:[24,26,27],benzer_cikmis:[]},{id:`k1-48-q30`,kazanim:10,zorluk:`zor`,soru:`78 yaşında, yıllardır liken skleroz tanısıyla izlenen kadında vulvada tek odaklı ülsere kitle saptanıyor. Biyopside keratin incileri içeren iyi diferansiye skuamöz hücreli karsinom görülüyor; HPV testi negatif.

Bu tümörün öncül lezyonunun histolojik özelliği hangisidir?`,secenekler:{A:`Tam kat bazaloid atipi ve koilositoz`,B:`Bazal tabakaya sınırlı anormal keratinizasyon ve sitolojik atipi`,C:`Papiller ekzofitik yapı ve koilositik atipi`,D:`Epidermiste büyük soluk sitoplazmalı tek tek hücreler`,E:`Proliferatif endarterit ve plazma hücreleri`},dogru:`B`,aciklama:`HPV negatif keratinize SCC'nin öncülü dVIN'dir; atipi ve anormal keratinizasyon bazal tabakaya sınırlıdır.`,sik_aciklamalari:{A:`Tam kat bazaloid atipi ve koilositoz klasik (HPV ilişkili) VIN'e aittir.`,B:`Doğru: dVIN'in tanımlayıcı histolojisidir.`,C:`Bu bulgular kondiloma akuminatuma aittir.`,D:`Bu bulgu ekstramammary Paget hastalığına aittir.`,E:`Bu bulgu sifilise aittir.`},bilgi:[23,26,27],benzer_cikmis:[]},{id:`k1-48-vulva-vajen-ve-serviks-hastaliklari-k10-q04`,kazanim:10,zorluk:`orta`,soru:`Sigara içen 60 yaşında çok odaklı bazaloid tümör ile 78 yaşında liken sklerozlu tek odaklı keratinize tümör karşılaştırılıyor. Aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`HPV pozitif liken skleroz zeminlidir`,B:`HPV negatif çok odaklıdır`,C:`dVIN HPV pozitif yolundur`,D:`HPV pozitif tümör HPV 16 ilişkili, çok odaklı, kötü diferansiye bazaloid/siğil benzeridir (öncül klasik VIN); HPV negatif keratinize SCC yaşlıda, unifokal, iyi diferansiyedir (öncül dVIN)`,E:`Klasik VIN HPV negatiftir`},dogru:`D`,aciklama:`İki yol yaş, zemin, morfoloji ve öncül açısından ayrılır.`,sik_aciklamalari:{A:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'HPV pozitif tümör HPV 16 ilişkili, çok odaklı, kötü diferansiye bazaloid/siğil benzeridir (öncül klasik VIN); HPV negatif keratinize SCC yaşlıda, unifokal, iyi diferansiyedir (öncül dVIN)' seçeneğidir.`,B:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'HPV pozitif tümör HPV 16 ilişkili, çok odaklı, kötü diferansiye bazaloid/siğil benzeridir (öncül klasik VIN); HPV negatif keratinize SCC yaşlıda, unifokal, iyi diferansiyedir (öncül dVIN)' seçeneğidir.`,C:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'HPV pozitif tümör HPV 16 ilişkili, çok odaklı, kötü diferansiye bazaloid/siğil benzeridir (öncül klasik VIN); HPV negatif keratinize SCC yaşlıda, unifokal, iyi diferansiyedir (öncül dVIN)' seçeneğidir.`,D:`Doğru: İki yol yaş, zemin, morfoloji ve öncül açısından ayrılır.`,E:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'HPV pozitif tümör HPV 16 ilişkili, çok odaklı, kötü diferansiye bazaloid/siğil benzeridir (öncül klasik VIN); HPV negatif keratinize SCC yaşlıda, unifokal, iyi diferansiyedir (öncül dVIN)' seçeneğidir.`},bilgi:[23,24,26,27],benzer_cikmis:[]},{id:`k1-48-vulva-vajen-ve-serviks-hastaliklari-k10-q05`,kazanim:10,zorluk:`zor`,soru:`dVIN histolojisi soruluyor. Aşağıdakilerden hangisi yanlıştır?`,secenekler:{A:`Tedavisiz keratinize SCC gelişir`,B:`Klasik VIN'de tam kat bazaloid atipi ve koilositoz vardır`,C:`dVIN tam kat koilositik atipi gösterir ve HPV 16 ile oluşur`,D:`HPV negatif yol liken skleroz/hiperplazi zeminlidir`,E:`dVIN'de atipi ve anormal keratinizasyon bazal tabakaya sınırlıdır`},dogru:`E`,aciklama:`dVIN bazala sınırlıdır ve HPV'den bağımsızdır.`,sik_aciklamalari:{A:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'dVIN'de atipi ve anormal keratinizasyon bazal tabakaya sınırlıdır' seçeneğidir.`,B:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'dVIN'de atipi ve anormal keratinizasyon bazal tabakaya sınırlıdır' seçeneğidir.`,C:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'dVIN'de atipi ve anormal keratinizasyon bazal tabakaya sınırlıdır' seçeneğidir.`,D:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'dVIN'de atipi ve anormal keratinizasyon bazal tabakaya sınırlıdır' seçeneğidir.`,E:`Doğru: dVIN bazala sınırlıdır ve HPV'den bağımsızdır.`},bilgi:[23,25,26],benzer_cikmis:[]},{id:`k1-48-vulva-vajen-ve-serviks-hastaliklari-k10-q06`,kazanim:10,zorluk:`orta`,soru:`Vulvar karsinomun HPV pozitif ve negatif grupları nasıl ayrılır?`,secenekler:{A:`HPV pozitif liken skleroz zeminlidir`,B:`HPV negatif çok odaklıdır`,C:`HPV pozitif multifokal bazaloid; negatif unifokal keratinizedir`,D:`dVIN HPV pozitif yolun öncüsüdür`,E:`Klasik VIN HPV negatiftir`},dogru:`C`,aciklama:`HPV pozitif tümör HPV 16 ilişkili, çok odaklı, kötü diferansiye bazaloid veya siğil benzeridir; öncülü klasik VIN'dir. HPV negatif keratinize SCC yaşlıda, unifokal ve iyi diferansiyedir; öncülü dVIN'dir. Yaş, zemin ve morfoloji iki yolu ayırır.`,sik_aciklamalari:{A:`Yanlış: Liken skleroz HPV negatif yolun zeminidir.`,B:`Yanlış: Çok odaklılık HPV pozitif yolun özelliğidir.`,C:`Doğru: Öncül, morfoloji ve odak sayısı iki yolu ayırır.`,D:`Yanlış: dVIN HPV negatif yolun öncülüdür.`,E:`Yanlış: Klasik VIN yüksek riskli HPV'lidir.`},bilgi:[23,24,26,27],benzer_cikmis:[`28a4535abbe9`]},{id:`k1-48-vulva-vajen-ve-serviks-hastaliklari-k10-q07`,kazanim:10,zorluk:`orta`,soru:`Diferansiye VIN'in histolojisi ve HPV ilişkisi nedir?`,secenekler:{A:`dVIN tam kat koilositik atipi gösterir`,B:`dVIN HPV 16 ile oluşur`,C:`Klasik VIN liken skleroz zeminlidir`,D:`HPV negatif yol multifokal ve bazaloiddir`,E:`dVIN bazala sınırlı ve HPV bağımsızdır`},dogru:`E`,aciklama:`dVIN'de atipi ve anormal keratinizasyon bazal tabakaya sınırlıdır ve HPV'den bağımsızdır. Klasik VIN'de tam kat bazaloid atipi ve koilositoz vardır. HPV negatif yol liken skleroz ve hiperplazi zemininde gelişir.`,sik_aciklamalari:{A:`Yanlış: Tam kat atipi klasik VIN'in özelliğidir.`,B:`Yanlış: dVIN HPV'den bağımsız gelişir.`,C:`Yanlış: Klasik VIN HPV ilişkili intraepiteliyal lezyondur.`,D:`Yanlış: HPV negatif yol unifokal keratinizedir.`,E:`Doğru: Bazal sınırlı atipi dVIN'i tanımlar.`},bilgi:[25,26],benzer_cikmis:[]},{id:`k1-48-vulva-vajen-ve-serviks-hastaliklari-k10-q08`,kazanim:10,zorluk:`kolay`,soru:`"HPV negatif vulvar karsinom ve dVIN" ifadesi ile ilgili aşağıdakilerden hangisi doğrudur?`,secenekler:{E:`Genellikle yaşlı kadınlarda (ortalama yaş ~75), uzun süreli liken skleroz ve skuamöz hücre hiperplazisi zemininde görülür ve HPV ile ilişkili değildir; ön lezyonu dVIN'dir (bazal tabakaya sınırlı anormal keratinizasyon ve sitolojik atipi).`,D:`Kronik, sklerozan dermatozdur; düz beyaz plaklar veya papüller (lökoplaki) görülür, zamanla genişler ve birleşir, vajinal açıklık daralabilir, labialar atrofik ve sert hale gelir.`,A:`Atipik epitel hücrelerinin intraepidermal proliferasyonudur; vulva derisi (ekstramammary Paget) veya meme ucu derisinde görülür. Olası köken vulva derisi kanallarındaki multipotent hücrelerdir.`,B:`İki temel tablo liken skleroz ve skuamöz hücre hiperplazisidir; klinik olarak genellikle lökoplaki şeklinde görülürler.`,C:`HSV-1 ve HSV-2 genital herpes etkenidir; ağrılı vezikül ve ülserler ile tekrarlayıcı seyir yapar.`},dogru:`E`,aciklama:`Doğru: Genellikle yaşlı kadınlarda (ortalama yaş ~75), uzun süreli liken skleroz ve skuamöz hücre hiperplazisi zemininde görülür ve HPV ile ilişkili değildir; ön lezyonu dVIN'dir (bazal tabakaya sınırlı anormal keratinizasyon ve sitolojik atipi).`,sik_aciklamalari:{E:`Doğru. Genellikle yaşlı kadınlarda (ortalama yaş ~75), uzun süreli liken skleroz ve skuamöz hücre hiperplazisi zemininde görülür ve HPV ile ilişkili değildir; ön lezyonu dVIN'dir (bazal tabakaya sınırlı anormal keratinizasyon ve sitolojik atipi).`,D:`Yanlış. Kronik, sklerozan dermatozdur; düz beyaz plaklar veya papüller (lökoplaki) görülür, zamanla genişler ve birleşir, vajinal açıklık daralabilir, labialar atrofik ve sert hale gelir.`,A:`Yanlış. Atipik epitel hücrelerinin intraepidermal proliferasyonudur; vulva derisi (ekstramammary Paget) veya meme ucu derisinde görülür. Olası köken vulva derisi kanallarındaki multipotent hücrelerdir.`,B:`Yanlış. İki temel tablo liken skleroz ve skuamöz hücre hiperplazisidir; klinik olarak genellikle lökoplaki şeklinde görülürler.`,C:`Yanlış. HSV-1 ve HSV-2 genital herpes etkenidir; ağrılı vezikül ve ülserler ile tekrarlayıcı seyir yapar.`},bilgi:[26],benzer_cikmis:[]},{id:`k1-48-vulva-vajen-ve-serviks-hastaliklari-k10-q09`,kazanim:10,zorluk:`orta`,soru:`"Liken skleroz: histoloji" kavramı hakkında verilen aşağıdakilerden hangisi doğrudur?`,secenekler:{B:`Epidermis incelmesi, rete çıkıntılarının kaybı, hücresiz homojen dermal fibrozis alanı ve bant tarzında mononükleer inflamatuar infiltrat vardır.`,E:`Vulvar kondilomlar kansere dönüşmez ancak vajina ve servikste HPV ilişkili prekanseröz lezyon riski artar.`,D:`HPV pozitif tümörler sıklıkla multifokal, siğil benzeri ve genellikle kötü diferansiye; HPV negatif tümörler genellikle unifokal ve iyi diferansiye, keratinize skuamöz hücreli karsinomdur.`,A:`Vajinanın inflamatuar durumudur; genellikle enfeksiyona bağlı ve geçicidir, temel bulgu vajinal akıntıdır (lökore). Etkenler bakteri, mantar, parazit olup pek çoğu normal kommensal flora üyesidir.`,C:`1) Bazaloid/siğil benzeri karsinom yüksek riskli HPV ile ilişkilidir. 2) Keratinize skuamöz hücreli karsinom HPV ile ilişkili değildir ve liken skleroz veya skuamöz hücre hiperplazisi zemininde gelişir.`},dogru:`B`,aciklama:`Doğru: Epidermis incelmesi, rete çıkıntılarının kaybı, hücresiz homojen dermal fibrozis alanı ve bant tarzında mononükleer inflamatuar infiltrat vardır.`,sik_aciklamalari:{B:`Doğru. Epidermis incelmesi, rete çıkıntılarının kaybı, hücresiz homojen dermal fibrozis alanı ve bant tarzında mononükleer inflamatuar infiltrat vardır.`,E:`Yanlış. Vulvar kondilomlar kansere dönüşmez ancak vajina ve servikste HPV ilişkili prekanseröz lezyon riski artar.`,D:`Yanlış. HPV pozitif tümörler sıklıkla multifokal, siğil benzeri ve genellikle kötü diferansiye; HPV negatif tümörler genellikle unifokal ve iyi diferansiye, keratinize skuamöz hücreli karsinomdur.`,A:`Yanlış. Vajinanın inflamatuar durumudur; genellikle enfeksiyona bağlı ve geçicidir, temel bulgu vajinal akıntıdır (lökore). Etkenler bakteri, mantar, parazit olup pek çoğu normal kommensal flora üyesidir.`,C:`Yanlış. 1) Bazaloid/siğil benzeri karsinom yüksek riskli HPV ile ilişkilidir. 2) Keratinize skuamöz hücreli karsinom HPV ile ilişkili değildir ve liken skleroz veya skuamöz hücre hiperplazisi zemininde gelişir.`},bilgi:[11],benzer_cikmis:[]},{id:`k1-48-vulva-vajen-ve-serviks-hastaliklari-k10-q10`,kazanim:10,zorluk:`orta`,soru:`"Vulvar karsinom epidemiyolojisi" kavramı hakkında verilen aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`Tüm kadın genital sistem kanserlerinin ~%3'ü; 60 yaş üstü kadınlarda görülür; histolojik tiplerin ~%90'ı skuamöz hücreli karsinom, diğerleri adenokarsinom ve bazal hücreli karsinomdur.`,C:`Kronik, sklerozan dermatozdur; düz beyaz plaklar veya papüller (lökoplaki) görülür, zamanla genişler ve birleşir, vajinal açıklık daralabilir, labialar atrofik ve sert hale gelir.`,B:`Vulva dış kadın genital organıdır; kıllı deri (labia majora) ve mukoza (labia minora) içerir.`,D:`HPV pozitif tümörler sıklıkla multifokal, siğil benzeri ve genellikle kötü diferansiye; HPV negatif tümörler genellikle unifokal ve iyi diferansiye, keratinize skuamöz hücreli karsinomdur.`,E:`VIN seyri yüksek dereceli atipi ve karsinoma in situ gelişimidir; invaziv karsinom riski 45 yaşından büyük kadınlarda ve immün sistemi baskılanmış hastalarda artar.`},dogru:`A`,aciklama:`Doğru: Tüm kadın genital sistem kanserlerinin ~%3'ü; 60 yaş üstü kadınlarda görülür; histolojik tiplerin ~%90'ı skuamöz hücreli karsinom, diğerleri adenokarsinom ve bazal hücreli karsinomdur.`,sik_aciklamalari:{A:`Doğru. Tüm kadın genital sistem kanserlerinin ~%3'ü; 60 yaş üstü kadınlarda görülür; histolojik tiplerin ~%90'ı skuamöz hücreli karsinom, diğerleri adenokarsinom ve bazal hücreli karsinomdur.`,C:`Yanlış. Kronik, sklerozan dermatozdur; düz beyaz plaklar veya papüller (lökoplaki) görülür, zamanla genişler ve birleşir, vajinal açıklık daralabilir, labialar atrofik ve sert hale gelir.`,B:`Yanlış. Vulva dış kadın genital organıdır; kıllı deri (labia majora) ve mukoza (labia minora) içerir.`,D:`Yanlış. HPV pozitif tümörler sıklıkla multifokal, siğil benzeri ve genellikle kötü diferansiye; HPV negatif tümörler genellikle unifokal ve iyi diferansiye, keratinize skuamöz hücreli karsinomdur.`,E:`Yanlış. VIN seyri yüksek dereceli atipi ve karsinoma in situ gelişimidir; invaziv karsinom riski 45 yaşından büyük kadınlarda ve immün sistemi baskılanmış hastalarda artar.`},bilgi:[22],benzer_cikmis:[]},{id:`k1-48-vulva-vajen-ve-serviks-hastaliklari-k10-q11`,kazanim:10,zorluk:`zor`,soru:`"Bartholin bezi komplikasyonları" bilgisini içeren doğru kurulum aşağıdakilerden hangisidir?`,secenekler:{A:`Bartholin bezi salgı kanalı tıkanması ağrılı gland genişlemesi (Bartholin kisti) ve sıkça apse oluşumuna yol açar.`,B:`Kronik, sklerozan dermatozdur; düz beyaz plaklar veya papüller (lökoplaki) görülür, zamanla genişler ve birleşir, vajinal açıklık daralabilir, labialar atrofik ve sert hale gelir.`,C:`Daha az yaygın formdur, HPV tip 16 ile ilişkilidir, ortalama yaş ~60'tır, sıklıkla sigara içen kadınlarda ve çoğunlukla çok odaklı lezyonlar şeklinde görülür.`,E:`En yaygın kondilom tipidir; etkeni düşük riskli HPV tip 6 ve 11'dir, cinsel temasla bulaşır ve sıklıkla genç erişkinlerde görülür.`,D:`Genellikle yaşlı kadınlarda (ortalama yaş ~75), uzun süreli liken skleroz ve skuamöz hücre hiperplazisi zemininde görülür ve HPV ile ilişkili değildir; ön lezyonu dVIN'dir (bazal tabakaya sınırlı anormal keratinizasyon ve sitolojik atipi).`},dogru:`A`,aciklama:`Doğru: Bartholin bezi salgı kanalı tıkanması ağrılı gland genişlemesi (Bartholin kisti) ve sıkça apse oluşumuna yol açar.`,sik_aciklamalari:{A:`Doğru. Bartholin bezi salgı kanalı tıkanması ağrılı gland genişlemesi (Bartholin kisti) ve sıkça apse oluşumuna yol açar.`,B:`Yanlış. Kronik, sklerozan dermatozdur; düz beyaz plaklar veya papüller (lökoplaki) görülür, zamanla genişler ve birleşir, vajinal açıklık daralabilir, labialar atrofik ve sert hale gelir.`,C:`Yanlış. Daha az yaygın formdur, HPV tip 16 ile ilişkilidir, ortalama yaş ~60'tır, sıklıkla sigara içen kadınlarda ve çoğunlukla çok odaklı lezyonlar şeklinde görülür.`,E:`Yanlış. En yaygın kondilom tipidir; etkeni düşük riskli HPV tip 6 ve 11'dir, cinsel temasla bulaşır ve sıklıkla genç erişkinlerde görülür.`,D:`Yanlış. Genellikle yaşlı kadınlarda (ortalama yaş ~75), uzun süreli liken skleroz ve skuamöz hücre hiperplazisi zemininde görülür ve HPV ile ilişkili değildir; ön lezyonu dVIN'dir (bazal tabakaya sınırlı anormal keratinizasyon ve sitolojik atipi).`},bilgi:[8],benzer_cikmis:[]}],ilgili_cikmis:[]},{no:11,metin:`Vulvar karsinomun yayılımını ve prognozunu tanımlayabilmek`,sorular:[{id:`k1-48-q31`,kazanim:11,zorluk:`kolay`,soru:`Vulvar karsinomun ilk yayılım bölgesi genellikle hangisidir?`,secenekler:{A:`Kemik`,B:`Akciğer`,C:`Karaciğer`,D:`Bölgesel lenf düğümleri`,E:`Beyin`},dogru:`D`,aciklama:`Vulvar karsinom uzun süre lokal kalır; ilk yayılım bölgesel lenf düğümlerinedir, ileri evrede hematogen metastaz olur.`,sik_aciklamalari:{A:`Kemik metastazı ilk yayılım bölgesi değildir.`,B:`Akciğer metastazı ileri evrede hematogen yolla olur.`,C:`Karaciğer metastazı ileri evrede görülür.`,D:`Doğru: lenfatik yayılım ilk basamaktır.`,E:`Beyin metastazı nadirdir.`},bilgi:[28],benzer_cikmis:[]},{id:`k1-48-q32`,kazanim:11,zorluk:`orta`,soru:`Vulvar karsinomda prognozla ilişkili faktörler arasında aşağıdakilerden hangisi yer almaz?`,secenekler:{A:`Evre`,B:`İnvazyon derinliği`,C:`Tümör boyutu`,D:`Lenf düğümü tutulumu`,E:`Hastanın kan grubu`},dogru:`E`,aciklama:`Vulvar karsinomda prognoz evre, invazyon derinliği ve tümör boyutu ile ilişkilidir.`,sik_aciklamalari:{A:`Evre en önemli prognostik faktörlerdendir.`,B:`İnvazyon derinliği prognozu etkiler.`,C:`Tümör boyutu prognozla ilişkilidir.`,D:`Lenf düğümü tutulumu evreyi belirler.`,E:`Doğru: kan grubu prognostik faktör değildir.`},bilgi:[28],benzer_cikmis:[]},{id:`k1-48-q33`,kazanim:11,zorluk:`zor`,soru:`Vulvar karsinomun yayılım özellikleri ile ilgili aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`Lenf düğümlerine hiç yayılmaz`,B:`Tanı anında çoğunlukla yaygın hematogen metastaz vardır`,C:`Uzun süre lokal kalma eğilimindedir; ileri evrede akciğer gibi organlara hematogen metastaz yapar`,D:`Yalnızca doğrudan kemiğe yayılır`,E:`Prognoz tümör boyutundan bağımsızdır`},dogru:`C`,aciklama:`Vulvar karsinom uzun süre lokal kalır, önce bölgesel lenf düğümlerine, ileri evrede hematogen olarak akciğer ve diğer organlara yayılır.`,sik_aciklamalari:{A:`İlk yayılım bölgesel lenf düğümlerinedir.`,B:`Hematogen metastaz ileri evrede görülür.`,C:`Doğru: yayılım sıralaması doğru tanımlanmıştır.`,D:`Kemik doğrudan yayılımın tipik hedefi değildir.`,E:`Tümör boyutu prognozla ilişkilidir.`},bilgi:[28],benzer_cikmis:[]},{id:`k1-48-vulva-vajen-ve-serviks-hastaliklari-k11-q04`,kazanim:11,zorluk:`orta`,soru:`Vulvar kitleli hastada lenf düğümü evrelemesi tartışılıyor. Aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`Tümör uzun süre lokal kalır; ilk yayılım bölgesel lenf düğümlerine, ileri evrede akciğere hematogen metastaz olur; prognoz evre, invazyon derinliği ve boyutla ilişkilidir`,B:`İlk yayılım beyne olur`,C:`Hematogen metastaz erken olur`,D:`Prognoz kan grubuyla belirlenir`,E:`Lenfatik yayılım olmaz`},dogru:`A`,aciklama:`Yayılım lenfatik → hematogen sıradadır; evre-derinlik-boyut prognostiktir.`,sik_aciklamalari:{A:`Doğru: Yayılım lenfatik → hematogen sıradadır; evre-derinlik-boyut prognostiktir.`,B:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Tümör uzun süre lokal kalır; ilk yayılım bölgesel lenf düğümlerine, ileri evrede akciğere hematogen metastaz olur; prognoz evre, invazyon derinliği ve boyutla ilişkilidir' seçeneğidir.`,C:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Tümör uzun süre lokal kalır; ilk yayılım bölgesel lenf düğümlerine, ileri evrede akciğere hematogen metastaz olur; prognoz evre, invazyon derinliği ve boyutla ilişkilidir' seçeneğidir.`,D:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Tümör uzun süre lokal kalır; ilk yayılım bölgesel lenf düğümlerine, ileri evrede akciğere hematogen metastaz olur; prognoz evre, invazyon derinliği ve boyutla ilişkilidir' seçeneğidir.`,E:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Tümör uzun süre lokal kalır; ilk yayılım bölgesel lenf düğümlerine, ileri evrede akciğere hematogen metastaz olur; prognoz evre, invazyon derinliği ve boyutla ilişkilidir' seçeneğidir.`},bilgi:[28],benzer_cikmis:[]},{id:`k1-48-vulva-vajen-ve-serviks-hastaliklari-k11-q05`,kazanim:11,zorluk:`zor`,soru:`Prognoz faktörleri sayılıyor. Aşağıdakilerden hangisi yanlıştır?`,secenekler:{A:`İnvazyon derinliği prognostiktir`,B:`Tümör boyutu prognostiktir`,C:`Evre prognostiktir`,D:`Lenf düğümü tutulumu evreyi belirler`,E:`Prognozu yalnızca hastanın yaşı belirler; lenf düğümü tutulumu önemsizdir`},dogru:`C`,aciklama:`Evre, derinlik, boyut ve nodal tutulum prognostiktir.`,sik_aciklamalari:{A:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Evre prognostiktir' seçeneğidir.`,B:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Evre prognostiktir' seçeneğidir.`,C:`Doğru: Evre, derinlik, boyut ve nodal tutulum prognostiktir.`,D:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Evre prognostiktir' seçeneğidir.`,E:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Evre prognostiktir' seçeneğidir.`},bilgi:[28],benzer_cikmis:[]},{id:`k1-48-vulva-vajen-ve-serviks-hastaliklari-k11-q06`,kazanim:11,zorluk:`orta`,soru:`Vulvar karsinomun yayılım sırası ve prognostik faktörleri nelerdir?`,secenekler:{A:`İlk yayılım beyne hematogendir`,B:`Önce lenfatik, sonra hematogen yayılır`,C:`Hematogen metastaz erken dönemde olur`,D:`Lenfatik yayılım hiç görülmez`,E:`Prognozu yalnızca kan grubu belirler`},dogru:`B`,aciklama:`Tümör uzun süre lokal kalır; ilk yayılım bölgesel lenf düğümlerinedir, ileri evrede akciğere hematogen metastaz olur. Prognoz evre, invazyon derinliği ve tümör boyutuyla ilişkilidir. Lenf nodu tutulumu evreyi belirler.`,sik_aciklamalari:{A:`Yanlış: İlk yayılım bölgesel lenf düğümlerinedir.`,B:`Doğru: Lenfatik yayılımı geç hematogen yayılım izler.`,C:`Yanlış: Hematogen yayılım ileri evrededir.`,D:`Yanlış: Lenfatik yayılım ilk basamaktır.`,E:`Yanlış: Prognoz evre ve invazyon derinliğinedir.`},bilgi:[28],benzer_cikmis:[]},{id:`k1-48-vulva-vajen-ve-serviks-hastaliklari-k11-q07`,kazanim:11,zorluk:`orta`,soru:`Vulvar karsinomda prognozu belirleyen faktörler hangileridir?`,secenekler:{A:`Prognozu yalnızca hasta yaşı belirler`,B:`Lenf düğümü tutulumu önemsizdir`,C:`Tümör boyutu prognozu etkilemez`,D:`Evre, derinlik, boyut ve nodal tutulum prognostiktir`,E:`İnvazyon derinliği değerlendirilmez`},dogru:`D`,aciklama:`Evre, invazyon derinliği, tümör boyutu ve lenf düğümü tutulumu prognostiktir. Derin invazyon lenfatik metastaz olasılığını artırır. Bu faktörler tedavi genişliğini belirler.`,sik_aciklamalari:{A:`Yanlış: Yaş tek başına prognostik değildir.`,B:`Yanlış: Nodal tutulum evreyi belirler.`,C:`Yanlış: Boyut prognostik faktörlerdendir.`,D:`Doğru: Dört faktör birlikte prognozu belirler.`,E:`Yanlış: Derinlik en güçlü göstergelerdendir.`},bilgi:[28],benzer_cikmis:[]},{id:`k1-48-vulva-vajen-ve-serviks-hastaliklari-k11-q08`,kazanim:11,zorluk:`kolay`,soru:`"Vulvitin enfeksiyöz etkenleri" ifadesi ile ilgili aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`Çoğu cinsel yolla bulaşır: HPV, HSV-1/HSV-2, Neisseria gonorrhoeae, Treponema pallidum ve Candida türleri.`,D:`Bartholin bezi salgı kanalı tıkanması ağrılı gland genişlemesi (Bartholin kisti) ve sıkça apse oluşumuna yol açar.`,E:`Eski isimleri hiperplastik distrofi ve liken simpleks kronikustur; nedeni şiddetli kaşıntıyı gidermek için ovma/kaşımadır ve lökoplaki görünümü oluşturur.`,B:`Genital organların siğil benzeri lezyonlarıdır; cinsel yolla bulaşan iki temel formu kondiloma lata ve kondiloma akuminatumdur.`,C:`Kronik, sklerozan dermatozdur; düz beyaz plaklar veya papüller (lökoplaki) görülür, zamanla genişler ve birleşir, vajinal açıklık daralabilir, labialar atrofik ve sert hale gelir.`},dogru:`A`,aciklama:`Doğru: Çoğu cinsel yolla bulaşır: HPV, HSV-1/HSV-2, Neisseria gonorrhoeae, Treponema pallidum ve Candida türleri.`,sik_aciklamalari:{A:`Doğru. Çoğu cinsel yolla bulaşır: HPV, HSV-1/HSV-2, Neisseria gonorrhoeae, Treponema pallidum ve Candida türleri.`,D:`Yanlış. Bartholin bezi salgı kanalı tıkanması ağrılı gland genişlemesi (Bartholin kisti) ve sıkça apse oluşumuna yol açar.`,E:`Yanlış. Eski isimleri hiperplastik distrofi ve liken simpleks kronikustur; nedeni şiddetli kaşıntıyı gidermek için ovma/kaşımadır ve lökoplaki görünümü oluşturur.`,B:`Yanlış. Genital organların siğil benzeri lezyonlarıdır; cinsel yolla bulaşan iki temel formu kondiloma lata ve kondiloma akuminatumdur.`,C:`Yanlış. Kronik, sklerozan dermatozdur; düz beyaz plaklar veya papüller (lökoplaki) görülür, zamanla genişler ve birleşir, vajinal açıklık daralabilir, labialar atrofik ve sert hale gelir.`},bilgi:[4],benzer_cikmis:[]},{id:`k1-48-vulva-vajen-ve-serviks-hastaliklari-k11-q09`,kazanim:11,zorluk:`orta`,soru:`"Ekstramammary Paget hastalığı: tanım ve köken" ile ilgili eşleştirmelerden hangisi doğrudur?`,secenekler:{D:`Atipik epitel hücrelerinin intraepidermal proliferasyonudur; vulva derisi (ekstramammary Paget) veya meme ucu derisinde görülür. Olası köken vulva derisi kanallarındaki multipotent hücrelerdir.`,E:`Epidermis incelmesi, rete çıkıntılarının kaybı, hücresiz homojen dermal fibrozis alanı ve bant tarzında mononükleer inflamatuar infiltrat vardır.`,B:`Uzun süre lokal kalma eğilimi vardır; ilk yayılım bölgesel lenf düğümlerine, ileri evrede akciğer ve diğer organlara hematogen metastaz olur.`,C:`Kronik, sklerozan dermatozdur; düz beyaz plaklar veya papüller (lökoplaki) görülür, zamanla genişler ve birleşir, vajinal açıklık daralabilir, labialar atrofik ve sert hale gelir.`,A:`Genital organların siğil benzeri lezyonlarıdır; cinsel yolla bulaşan iki temel formu kondiloma lata ve kondiloma akuminatumdur.`},dogru:`D`,aciklama:`Doğru: Atipik epitel hücrelerinin intraepidermal proliferasyonudur; vulva derisi (ekstramammary Paget) veya meme ucu derisinde görülür. Olası köken vulva derisi kanallarındaki multipotent hücrelerdir.`,sik_aciklamalari:{D:`Doğru. Atipik epitel hücrelerinin intraepidermal proliferasyonudur; vulva derisi (ekstramammary Paget) veya meme ucu derisinde görülür. Olası köken vulva derisi kanallarındaki multipotent hücrelerdir.`,E:`Yanlış. Epidermis incelmesi, rete çıkıntılarının kaybı, hücresiz homojen dermal fibrozis alanı ve bant tarzında mononükleer inflamatuar infiltrat vardır.`,B:`Yanlış. Uzun süre lokal kalma eğilimi vardır; ilk yayılım bölgesel lenf düğümlerine, ileri evrede akciğer ve diğer organlara hematogen metastaz olur.`,C:`Yanlış. Kronik, sklerozan dermatozdur; düz beyaz plaklar veya papüller (lökoplaki) görülür, zamanla genişler ve birleşir, vajinal açıklık daralabilir, labialar atrofik ve sert hale gelir.`,A:`Yanlış. Genital organların siğil benzeri lezyonlarıdır; cinsel yolla bulaşan iki temel formu kondiloma lata ve kondiloma akuminatumdur.`},bilgi:[29],benzer_cikmis:[]},{id:`k1-48-vulva-vajen-ve-serviks-hastaliklari-k11-q10`,kazanim:11,zorluk:`orta`,soru:`"Vulvanın tanımı ve içeriği" ile ilgili eşleştirmelerden hangisi doğrudur?`,secenekler:{E:`Vulva dış kadın genital organıdır; kıllı deri (labia majora) ve mukoza (labia minora) içerir.`,D:`Lateral vajinal duvarda yerleşir ve kalıcı Wolffian kanal kalıntısından gelişir.`,B:`Kronik, sklerozan dermatozdur; düz beyaz plaklar veya papüller (lökoplaki) görülür, zamanla genişler ve birleşir, vajinal açıklık daralabilir, labialar atrofik ve sert hale gelir.`,A:`Uzun süre lokal kalma eğilimi vardır; ilk yayılım bölgesel lenf düğümlerine, ileri evrede akciğer ve diğer organlara hematogen metastaz olur.`,C:`Nadir bir vajinal tümördür (sarkoma botryoides); histogenezi malign embriyonel rabdomiyoblastlardır ve 5 yaşından küçük bebek ve çocuklarda görülür.`},dogru:`E`,aciklama:`Doğru: Vulva dış kadın genital organıdır; kıllı deri (labia majora) ve mukoza (labia minora) içerir.`,sik_aciklamalari:{E:`Doğru. Vulva dış kadın genital organıdır; kıllı deri (labia majora) ve mukoza (labia minora) içerir.`,D:`Yanlış. Lateral vajinal duvarda yerleşir ve kalıcı Wolffian kanal kalıntısından gelişir.`,B:`Yanlış. Kronik, sklerozan dermatozdur; düz beyaz plaklar veya papüller (lökoplaki) görülür, zamanla genişler ve birleşir, vajinal açıklık daralabilir, labialar atrofik ve sert hale gelir.`,A:`Yanlış. Uzun süre lokal kalma eğilimi vardır; ilk yayılım bölgesel lenf düğümlerine, ileri evrede akciğer ve diğer organlara hematogen metastaz olur.`,C:`Yanlış. Nadir bir vajinal tümördür (sarkoma botryoides); histogenezi malign embriyonel rabdomiyoblastlardır ve 5 yaşından küçük bebek ve çocuklarda görülür.`},bilgi:[1],benzer_cikmis:[]},{id:`k1-48-vulva-vajen-ve-serviks-hastaliklari-k11-q11`,kazanim:11,zorluk:`zor`,soru:`"Skuamöz hücre hiperplazisi" klinik bağlamda aşağıdakilerden hangisi doğrudur?`,secenekler:{E:`Eski isimleri hiperplastik distrofi ve liken simpleks kronikustur; nedeni şiddetli kaşıntıyı gidermek için ovma/kaşımadır ve lökoplaki görünümü oluşturur.`,D:`Genellikle yaşlı kadınlarda (ortalama yaş ~75), uzun süreli liken skleroz ve skuamöz hücre hiperplazisi zemininde görülür ve HPV ile ilişkili değildir; ön lezyonu dVIN'dir (bazal tabakaya sınırlı anormal keratinizasyon ve sitolojik atipi).`,A:`Her yaşta görülebilir (menopoz sonrası kadınlar, ergenlik öncesi kızlar); patogenezi belirsizdir, subepiteliyal aktif T hücre infiltrasyonu ve otoimmün bozukluklarla birliktelik vardır.`,B:`Nadir bir vajinal tümördür (sarkoma botryoides); histogenezi malign embriyonel rabdomiyoblastlardır ve 5 yaşından küçük bebek ve çocuklarda görülür.`,C:`HSV-1 ve HSV-2 genital herpes etkenidir; ağrılı vezikül ve ülserler ile tekrarlayıcı seyir yapar.`},dogru:`E`,aciklama:`Doğru: Eski isimleri hiperplastik distrofi ve liken simpleks kronikustur; nedeni şiddetli kaşıntıyı gidermek için ovma/kaşımadır ve lökoplaki görünümü oluşturur.`,sik_aciklamalari:{E:`Doğru. Eski isimleri hiperplastik distrofi ve liken simpleks kronikustur; nedeni şiddetli kaşıntıyı gidermek için ovma/kaşımadır ve lökoplaki görünümü oluşturur.`,D:`Yanlış. Genellikle yaşlı kadınlarda (ortalama yaş ~75), uzun süreli liken skleroz ve skuamöz hücre hiperplazisi zemininde görülür ve HPV ile ilişkili değildir; ön lezyonu dVIN'dir (bazal tabakaya sınırlı anormal keratinizasyon ve sitolojik atipi).`,A:`Yanlış. Her yaşta görülebilir (menopoz sonrası kadınlar, ergenlik öncesi kızlar); patogenezi belirsizdir, subepiteliyal aktif T hücre infiltrasyonu ve otoimmün bozukluklarla birliktelik vardır.`,B:`Yanlış. Nadir bir vajinal tümördür (sarkoma botryoides); histogenezi malign embriyonel rabdomiyoblastlardır ve 5 yaşından küçük bebek ve çocuklarda görülür.`,C:`Yanlış. HSV-1 ve HSV-2 genital herpes etkenidir; ağrılı vezikül ve ülserler ile tekrarlayıcı seyir yapar.`},bilgi:[14],benzer_cikmis:[]}],ilgili_cikmis:[]},{no:12,metin:`Ekstramammary Paget hastalığını meme Paget'inden ayırt edebilmek`,sorular:[{id:`k1-48-q34`,kazanim:12,zorluk:`kolay`,soru:`Ekstramammary Paget hastalığının histolojik özelliği hangisidir?`,secenekler:{A:`Clue cells`,B:`Koilositoz`,C:`Homojen dermal fibrozis`,D:`Epidermiste tek tek veya gruplar halinde, bol soluk sitoplazmalı büyük hücreler`,E:`Cowdry A inklüzyonları`},dogru:`D`,aciklama:`Ekstramammary Paget'te epidermis içinde büyük, bol soluk ince granüllü sitoplazmalı atipik hücreler bulunur.`,sik_aciklamalari:{A:`Clue cells bakteriyel vajinozda görülür.`,B:`Koilositoz HPV enfeksiyonunun bulgusudur.`,C:`Dermal fibrozis liken skleroza aittir.`,D:`Doğru: intraepidermal Paget hücreleri tipiktir.`,E:`Cowdry A inklüzyonları herpese aittir.`},bilgi:[30],benzer_cikmis:[]},{id:`k1-48-q35`,kazanim:12,zorluk:`orta`,soru:`Ekstramammary (vulvar) Paget hastalığını meme ucu Paget hastalığından ayıran temel özellik hangisidir?`,secenekler:{A:`Vulvar Paget çoğunlukla primer intraepidermal süreçtir; meme Paget'i her zaman altta yatan duktal karsinomla ilişkilidir`,B:`Vulvar Paget her zaman altta yatan adenokarsinomla ilişkilidir`,C:`Meme Paget'i hiçbir zaman karsinomla ilişkili değildir`,D:`İkisi de HPV ile oluşur`,E:`Vulvar Paget hızla metastaz yapar`},dogru:`A`,aciklama:`Meme ucu Paget hastalığı daima altta yatan duktal karsinoma bağlıdır; vulvar Paget çoğunlukla altta karsinom olmadan intraepidermal kalır.`,sik_aciklamalari:{A:`Doğru: ayırımın temel noktasıdır.`,B:`Vulvar Paget'te altta yatan karsinom çoğunlukla yoktur.`,C:`Meme Paget'i her zaman karsinomla ilişkilidir.`,D:`Paget hastalığı HPV ile ilişkili değildir.`,E:`Vulvar Paget invazyon/metastaz olmadan yıllarca sürebilir.`},bilgi:[29],benzer_cikmis:[]},{id:`k1-48-q36`,kazanim:12,zorluk:`zor`,soru:`Kronik dermatit tanısıyla uzun süre topikal tedavi alan ve yanıt vermeyen yaşlı kadında vulvada kırmızı, pullu, kabuklu plak bulunuyor. Biyopside epidermiste büyük soluk sitoplazmalı atipik hücreler var; dermal invazyon yok.

Bu hastalık için doğru ifade hangisidir?`,secenekler:{A:`Yıllarca invazyonsuz sürebilir; tedavi geniş lokal eksizyondur, dermal invazyon gelişirse prognoz kötüleşir`,B:`Her olguda eşlik eden meme karsinomu aranmalı ve bulunur`,C:`HPV 6/11 ile oluşur`,D:`Kendiliğinden geriler`,E:`Liken sklerozun histolojik varyantıdır`},dogru:`A`,aciklama:`Ekstramammary Paget dermatiti taklit eder, uzun süre intraepidermal kalır; tedavi geniş lokal eksizyondur.`,sik_aciklamalari:{A:`Doğru: klinik seyir ve tedavi doğru tanımlanmıştır.`,B:`Eşlik eden karsinom meme ucu Paget'inin özelliğidir.`,C:`Paget hastalığı HPV ile ilişkili değildir.`,D:`Kendiliğinden gerilemez.`,E:`Liken skleroz ayrı bir non-neoplastik dermatozdur.`},bilgi:[29,30],benzer_cikmis:[]},{id:`k1-48-vulva-vajen-ve-serviks-hastaliklari-k12-q04`,kazanim:12,zorluk:`orta`,soru:`Yaşlı kadında tedaviye yanıtsız kırmızı pullu kabuklu vulvar plak var; biyopside soluk sitoplazmalı büyük hücreler görülüyor. Aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`Paget HPV ile oluşur`,B:`Vulvar Paget hep altta karsinomla birliktedir`,C:`Ekstramammary Paget epidermiste tek/grup bol soluk sitoplazmalı atipik hücrelerdir; meme Paget'i hep altta duktal karsinomla ilişkiliyken vulvar Paget çoğunlukla primer intraepidermaldir`,D:`Kendiliğinden geriler`,E:`Liken skleroz varyantıdır`},dogru:`C`,aciklama:`Vulvar Paget dermatiti taklit eder, yıllarca intraepidermal kalabilir; tedavi geniş eksizyondur.`,sik_aciklamalari:{A:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Ekstramammary Paget epidermiste tek/grup bol soluk sitoplazmalı atipik hücrelerdir; meme Paget'i hep altta duktal karsinomla ilişkiliyken vulvar Paget çoğunlukla primer intraepidermaldir' seçeneğidir.`,B:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Ekstramammary Paget epidermiste tek/grup bol soluk sitoplazmalı atipik hücrelerdir; meme Paget'i hep altta duktal karsinomla ilişkiliyken vulvar Paget çoğunlukla primer intraepidermaldir' seçeneğidir.`,C:`Doğru: Vulvar Paget dermatiti taklit eder, yıllarca intraepidermal kalabilir; tedavi geniş eksizyondur.`,D:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Ekstramammary Paget epidermiste tek/grup bol soluk sitoplazmalı atipik hücrelerdir; meme Paget'i hep altta duktal karsinomla ilişkiliyken vulvar Paget çoğunlukla primer intraepidermaldir' seçeneğidir.`,E:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Ekstramammary Paget epidermiste tek/grup bol soluk sitoplazmalı atipik hücrelerdir; meme Paget'i hep altta duktal karsinomla ilişkiliyken vulvar Paget çoğunlukla primer intraepidermaldir' seçeneğidir.`},bilgi:[29,30],benzer_cikmis:[]},{id:`k1-48-vulva-vajen-ve-serviks-hastaliklari-k12-q05`,kazanim:12,zorluk:`zor`,soru:`Seyir ve tedavi soruluyor. Aşağıdakilerden hangisi yanlıştır?`,secenekler:{A:`Kronik dermatiti taklit eder`,B:`Yıllarca invazyonsuz sürebilir`,C:`Tedavi geniş lokal eksizyondur`,D:`Dermal invazyonda prognoz kötüleşir`,E:`Vulvar Paget meme karsinomu ile hep birliktedir ve HPV 6/11 ile oluşur`},dogru:`A`,aciklama:`Altta karsinom birlikteliği meme Paget'inindir; Paget HPV ile ilişkili değildir.`,sik_aciklamalari:{A:`Doğru: Altta karsinom birlikteliği meme Paget'inindir; Paget HPV ile ilişkili değildir.`,B:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Kronik dermatiti taklit eder' seçeneğidir.`,C:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Kronik dermatiti taklit eder' seçeneğidir.`,D:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Kronik dermatiti taklit eder' seçeneğidir.`,E:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Kronik dermatiti taklit eder' seçeneğidir.`},bilgi:[29,30],benzer_cikmis:[]},{id:`k1-48-vulva-vajen-ve-serviks-hastaliklari-k12-q06`,kazanim:12,zorluk:`orta`,soru:`Ekstramammary Paget ile meme Paget'inin ilişki farkı nedir?`,secenekler:{A:`Vulvar Paget primer intraepidermal; meme altta karsinomludur`,B:`Paget HPV ile oluşur`,C:`Vulvar Paget hep altta karsinomludur`,D:`Paget kendiliğinden geriler`,E:`Liken sklerozun bir varyantıdır`},dogru:`A`,aciklama:`Ekstramammary Paget epidermiste tek veya grup halinde bol soluk sitoplazmalı atipik hücrelerdir. Meme Paget'i hep altta duktal karsinomla ilişkiliyken vulvar Paget çoğunlukla primer intraepidermaldir. HPV ile ilişkili değildir.`,sik_aciklamalari:{A:`Doğru: Vulvar form primerdir, meme formu duktal karsinomludur.`,B:`Yanlış: Paget HPV ilişkili değildir.`,C:`Yanlış: Altta karsinom birlikteliği meme Paget'inindir.`,D:`Yanlış: Tedavisiz yıllarca intraepidermal sürer.`,E:`Yanlış: Paget ayrı bir intraepidermal neoplazidir.`},bilgi:[29,30],benzer_cikmis:[]},{id:`k1-48-vulva-vajen-ve-serviks-hastaliklari-k12-q07`,kazanim:12,zorluk:`orta`,soru:`Ekstramammary Paget'in seyri ve tedavisi nasıldır?`,secenekler:{A:`Vulvar Paget meme karsinomuyla birliktedir`,B:`HPV 6-11 Paget etkenidir`,C:`Dermatiti taklit eder; invazyonda prognoz kötüleşir`,D:`Dar eksizyon her zaman yeterlidir`,E:`İnvazyon prognozu hiç değiştirmez`},dogru:`C`,aciklama:`Vulvar Paget kronik dermatiti taklit eder, yıllarca invazyonsuz sürebilir; tedavi geniş lokal eksizyondur. Dermal invazyonda prognoz kötüleşir. Kırmızı pullu kabuklu plak tipik klinik görünümdür.`,sik_aciklamalari:{A:`Yanlış: Bu birliktelik meme Paget'ine aittir.`,B:`Yanlış: Paget multipotent hücre kökenlidir.`,C:`Doğru: Kronik seyir ve invazyonla kötüleşme tipiktir.`,D:`Yanlış: Tedavi geniş lokal eksizyondur.`,E:`Yanlış: Dermal invazyon prognozu kötüleştirir.`},bilgi:[30],benzer_cikmis:[]},{id:`k1-48-vulva-vajen-ve-serviks-hastaliklari-k12-q08`,kazanim:12,zorluk:`kolay`,soru:`"Kondiloma lata" kavramının tanımı aşağıdakilerden hangisidir?`,secenekler:{C:`Sekonder sifilizde görülür; etkeni Treponema pallidum'dur, düz hafif kabarık lezyonlar yapar.`,B:`Servikal lezyonların çoğu inflamatuvar (servisit) niteliktedir; servikal skuamöz hücreli karsinom dünya çapında kadınlarda en sık görülen kanserlerden biridir ve HPV ilişkisi belirgindir.`,D:`Klinikte kırmızı, pullu, kabuklu plak kronik dermatiti taklit eder; histolojide büyük hücreler, bol soluk ince granüllü sitoplazma ve epidermiste tek tek/gruplar halinde hücreler vardır; invazyon veya metastaz olmaksızın yıllarca sürebilir.`,A:`Çoğu cinsel yolla bulaşır: HPV, HSV-1/HSV-2, Neisseria gonorrhoeae, Treponema pallidum ve Candida türleri.`,E:`Vulvit vulvanın inflamasyonudur; sık görülen, çok nedenli bir durumdur ve sıklıkla yoğun kaşıntı ile seyreder.`},dogru:`C`,aciklama:`Doğru: Sekonder sifilizde görülür; etkeni Treponema pallidum'dur, düz hafif kabarık lezyonlar yapar.`,sik_aciklamalari:{C:`Doğru. Sekonder sifilizde görülür; etkeni Treponema pallidum'dur, düz hafif kabarık lezyonlar yapar.`,B:`Yanlış. Servikal lezyonların çoğu inflamatuvar (servisit) niteliktedir; servikal skuamöz hücreli karsinom dünya çapında kadınlarda en sık görülen kanserlerden biridir ve HPV ilişkisi belirgindir.`,D:`Yanlış. Klinikte kırmızı, pullu, kabuklu plak kronik dermatiti taklit eder; histolojide büyük hücreler, bol soluk ince granüllü sitoplazma ve epidermiste tek tek/gruplar halinde hücreler vardır; invazyon veya metastaz olmaksızın yıllarca sürebilir.`,A:`Yanlış. Çoğu cinsel yolla bulaşır: HPV, HSV-1/HSV-2, Neisseria gonorrhoeae, Treponema pallidum ve Candida türleri.`,E:`Yanlış. Vulvit vulvanın inflamasyonudur; sık görülen, çok nedenli bir durumdur ve sıklıkla yoğun kaşıntı ile seyreder.`},bilgi:[18],benzer_cikmis:[]},{id:`k1-48-vulva-vajen-ve-serviks-hastaliklari-k12-q09`,kazanim:12,zorluk:`orta`,soru:`"Vajinal skuamöz hücreli karsinom" ile ilgili aşağıdakilerden hangisi yanlıştır?`,secenekler:{B:`Son derece nadirdir; neredeyse tüm primer karsinomlar yüksek riskli HPV ile ilişkili skuamöz hücreli karsinomdur; en büyük risk faktörü daha önce serviks veya vulva karsinomu öyküsüdür.`,C:`Klinikte kırmızı, pullu, kabuklu plak kronik dermatiti taklit eder; histolojide büyük hücreler, bol soluk ince granüllü sitoplazma ve epidermiste tek tek/gruplar halinde hücreler vardır; invazyon veya metastaz olmaksızın yıllarca sürebilir.`,A:`Bartholin bezi salgı kanalı tıkanması ağrılı gland genişlemesi (Bartholin kisti) ve sıkça apse oluşumuna yol açar.`,E:`Atipik epitel hücrelerinin intraepidermal proliferasyonudur; vulva derisi (ekstramammary Paget) veya meme ucu derisinde görülür. Olası köken vulva derisi kanallarındaki multipotent hücrelerdir.`,D:`Daha az yaygın formdur, HPV tip 16 ile ilişkilidir, ortalama yaş ~60'tır, sıklıkla sigara içen kadınlarda ve çoğunlukla çok odaklı lezyonlar şeklinde görülür.`},dogru:`B`,aciklama:`Doğru: Son derece nadirdir; neredeyse tüm primer karsinomlar yüksek riskli HPV ile ilişkili skuamöz hücreli karsinomdur; en büyük risk faktörü daha önce serviks veya vulva karsinomu öyküsüdür.`,sik_aciklamalari:{B:`Doğru. Son derece nadirdir; neredeyse tüm primer karsinomlar yüksek riskli HPV ile ilişkili skuamöz hücreli karsinomdur; en büyük risk faktörü daha önce serviks veya vulva karsinomu öyküsüdür.`,C:`Yanlış. Klinikte kırmızı, pullu, kabuklu plak kronik dermatiti taklit eder; histolojide büyük hücreler, bol soluk ince granüllü sitoplazma ve epidermiste tek tek/gruplar halinde hücreler vardır; invazyon veya metastaz olmaksızın yıllarca sürebilir.`,A:`Yanlış. Bartholin bezi salgı kanalı tıkanması ağrılı gland genişlemesi (Bartholin kisti) ve sıkça apse oluşumuna yol açar.`,E:`Yanlış. Atipik epitel hücrelerinin intraepidermal proliferasyonudur; vulva derisi (ekstramammary Paget) veya meme ucu derisinde görülür. Olası köken vulva derisi kanallarındaki multipotent hücrelerdir.`,D:`Yanlış. Daha az yaygın formdur, HPV tip 16 ile ilişkilidir, ortalama yaş ~60'tır, sıklıkla sigara içen kadınlarda ve çoğunlukla çok odaklı lezyonlar şeklinde görülür.`},bilgi:[38],benzer_cikmis:[]},{id:`k1-48-vulva-vajen-ve-serviks-hastaliklari-k12-q10`,kazanim:12,zorluk:`orta`,soru:`"Candida albicans vajiniti" kavramı hakkında verilen aşağıdakilerden hangisi doğrudur?`,secenekler:{C:`Kadınların ~%20'sinde normal vajinal flora üyesidir; semptomatik enfeksiyon yatkınlaştırıcı faktörlere veya virülan bir suşla süperenfeksiyona bağlıdır.`,B:`Vajinanın inflamatuar durumudur; genellikle enfeksiyona bağlı ve geçicidir, temel bulgu vajinal akıntıdır (lökore). Etkenler bakteri, mantar, parazit olup pek çoğu normal kommensal flora üyesidir.`,A:`VIN seyri yüksek dereceli atipi ve karsinoma in situ gelişimidir; invaziv karsinom riski 45 yaşından büyük kadınlarda ve immün sistemi baskılanmış hastalarda artar.`,D:`HPV kondiloma akuminatum etkenidir, VIN ile ilişkilidir ve vulvar skuamöz karsinom alt kümesinde rol oynar.`,E:`Eski isimleri hiperplastik distrofi ve liken simpleks kronikustur; nedeni şiddetli kaşıntıyı gidermek için ovma/kaşımadır ve lökoplaki görünümü oluşturur.`},dogru:`C`,aciklama:`Doğru: Kadınların ~%20'sinde normal vajinal flora üyesidir; semptomatik enfeksiyon yatkınlaştırıcı faktörlere veya virülan bir suşla süperenfeksiyona bağlıdır.`,sik_aciklamalari:{C:`Doğru. Kadınların ~%20'sinde normal vajinal flora üyesidir; semptomatik enfeksiyon yatkınlaştırıcı faktörlere veya virülan bir suşla süperenfeksiyona bağlıdır.`,B:`Yanlış. Vajinanın inflamatuar durumudur; genellikle enfeksiyona bağlı ve geçicidir, temel bulgu vajinal akıntıdır (lökore). Etkenler bakteri, mantar, parazit olup pek çoğu normal kommensal flora üyesidir.`,A:`Yanlış. VIN seyri yüksek dereceli atipi ve karsinoma in situ gelişimidir; invaziv karsinom riski 45 yaşından büyük kadınlarda ve immün sistemi baskılanmış hastalarda artar.`,D:`Yanlış. HPV kondiloma akuminatum etkenidir, VIN ile ilişkilidir ve vulvar skuamöz karsinom alt kümesinde rol oynar.`,E:`Yanlış. Eski isimleri hiperplastik distrofi ve liken simpleks kronikustur; nedeni şiddetli kaşıntıyı gidermek için ovma/kaşımadır ve lökoplaki görünümü oluşturur.`},bilgi:[34],benzer_cikmis:[]},{id:`k1-48-vulva-vajen-ve-serviks-hastaliklari-k12-q11`,kazanim:12,zorluk:`zor`,soru:`"Liken skleroz: histoloji" ile ilgili bir hastada bulunacak aşağıdaki bulgulardan hangisi beklenmez?`,secenekler:{D:`Epidermis incelmesi, rete çıkıntılarının kaybı, hücresiz homojen dermal fibrozis alanı ve bant tarzında mononükleer inflamatuar infiltrat vardır.`,B:`Kronik, sklerozan dermatozdur; düz beyaz plaklar veya papüller (lökoplaki) görülür, zamanla genişler ve birleşir, vajinal açıklık daralabilir, labialar atrofik ve sert hale gelir.`,E:`HPV pozitif tümörler sıklıkla multifokal, siğil benzeri ve genellikle kötü diferansiye; HPV negatif tümörler genellikle unifokal ve iyi diferansiye, keratinize skuamöz hücreli karsinomdur.`,C:`Vulvar kondilomlar kansere dönüşmez ancak vajina ve servikste HPV ilişkili prekanseröz lezyon riski artar.`,A:`Epidermis kalınlaşması (akantoz), hiperkeratoz, dermiste bazen lenfositik infiltrasyon ve sitolojik atipisi olmayan artmış mitotik aktivite gösteren hiperplastik epitel vardır.`},dogru:`D`,aciklama:`Doğru: Epidermis incelmesi, rete çıkıntılarının kaybı, hücresiz homojen dermal fibrozis alanı ve bant tarzında mononükleer inflamatuar infiltrat vardır.`,sik_aciklamalari:{D:`Doğru. Epidermis incelmesi, rete çıkıntılarının kaybı, hücresiz homojen dermal fibrozis alanı ve bant tarzında mononükleer inflamatuar infiltrat vardır.`,B:`Yanlış. Kronik, sklerozan dermatozdur; düz beyaz plaklar veya papüller (lökoplaki) görülür, zamanla genişler ve birleşir, vajinal açıklık daralabilir, labialar atrofik ve sert hale gelir.`,E:`Yanlış. HPV pozitif tümörler sıklıkla multifokal, siğil benzeri ve genellikle kötü diferansiye; HPV negatif tümörler genellikle unifokal ve iyi diferansiye, keratinize skuamöz hücreli karsinomdur.`,C:`Yanlış. Vulvar kondilomlar kansere dönüşmez ancak vajina ve servikste HPV ilişkili prekanseröz lezyon riski artar.`,A:`Yanlış. Epidermis kalınlaşması (akantoz), hiperkeratoz, dermiste bazen lenfositik infiltrasyon ve sitolojik atipisi olmayan artmış mitotik aktivite gösteren hiperplastik epitel vardır.`},bilgi:[11],benzer_cikmis:[]}],ilgili_cikmis:[]},{no:13,metin:`Vajinanın konjenital anomalilerini ve Gartner kanal kistini bilmek`,sorular:[{id:`k1-48-q37`,kazanim:13,zorluk:`kolay`,soru:`Lateral vajinal duvarda yerleşen ve Wolffian kanal kalıntısından gelişen kist hangisidir?`,secenekler:{A:`Gartner kanal kisti`,B:`Bartholin kisti`,C:`Nabothian kisti`,D:`Epidermal inklüzyon kisti`,E:`Endometriotik kist`},dogru:`A`,aciklama:`Gartner kanal kisti kalıcı Wolffian (mezonefrik) kanal kalıntısından gelişir ve lateral vajinal duvardadır.`,sik_aciklamalari:{A:`Doğru: Wolffian kalıntı kistidir.`,B:`Bartholin kisti vulvadaki bez kanalının tıkanmasıyla oluşur.`,C:`Nabothian kisti servikal bezlerin tıkanmasıyla oluşur.`,D:`Epidermal inklüzyon kisti travma sonrası gelişir.`,E:`Endometriotik kist endometrium dokusu içerir.`},bilgi:[32],benzer_cikmis:[]},{id:`k1-48-q38`,kazanim:13,zorluk:`orta`,soru:`Vajinanın konjenital anomalileri ile ilgili aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`Septalı/çift vajinaya sıklıkla septalı serviks, bazen septalı uterus eşlik eder`,B:`Vajinal anomaliler sık görülür`,C:`Vajinanın tam yokluğu tanımlanmamıştır`,D:`Anomaliler her zaman malign transformasyona uğrar`,E:`Gartner kisti konjenital bir septumdur`},dogru:`A`,aciklama:`Nadir vajinal anomaliler tam yokluk, septalı veya çift vajinadır; sıklıkla septalı serviks eşlik eder.`,sik_aciklamalari:{A:`Doğru: Müller kanal füzyon anomalileri birlikte görülür.`,B:`Konjenital vajinal anomaliler nadirdir.`,C:`Tam yokluk tanımlı bir anomalidir.`,D:`Anomaliler malign değildir.`,E:`Gartner kisti Wolffian kalıntı kistidir, septum değildir.`},bilgi:[31],benzer_cikmis:[]},{id:`k1-48-q39`,kazanim:13,zorluk:`zor`,soru:`Gartner kanal kisti ile ilgili aşağıdakilerden hangisi yanlıştır?`,secenekler:{A:`Lateral vajinal duvarda yerleşir`,B:`Kalıcı Wolffian kanal kalıntısından gelişir`,C:`Çoğu benign ve asemptomatiktir`,D:`Büyük boyutta semptom verebilir`,E:`Paramezonefrik (Müller) kanal kalıntısından gelişen malign bir tümördür`},dogru:`E`,aciklama:`Gartner kisti mezonefrik (Wolffian) kanal kalıntısıdır ve benign bir lezyondur.`,sik_aciklamalari:{A:`Doğru ifade: lateral duvar yerleşimlidir.`,B:`Doğru ifade: Wolffian kökenlidir.`,C:`Doğru ifade: çoğu asemptomatiktir.`,D:`Doğru ifade: büyük kistler semptom verebilir.`,E:`Yanlış ifade (aranan cevap): köken Wolffian'dır ve lezyon benigndir.`},bilgi:[32],benzer_cikmis:[]},{id:`k1-48-vulva-vajen-ve-serviks-hastaliklari-k13-q04`,kazanim:13,zorluk:`orta`,soru:`Lateral vajinal duvarda asemptomatik kistik lezyon saptanan genç kadın değerlendiriliyor. Aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`Müller kalıntısıdır`,B:`Malign tümördür`,C:`Septumdur`,D:`Bartholin kistidir`,E:`Gartner kanal kisti kalıcı Wolffian kanal kalıntısındandır ve lateral vajinal duvardadır; çoğu benign-asemptomatiktir`},dogru:`E`,aciklama:`Gartner kisti Wolffian kökenli benign lateral duvar kistidir.`,sik_aciklamalari:{A:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Gartner kanal kisti kalıcı Wolffian kanal kalıntısındandır ve lateral vajinal duvardadır; çoğu benign-asemptomatiktir' seçeneğidir.`,B:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Gartner kanal kisti kalıcı Wolffian kanal kalıntısındandır ve lateral vajinal duvardadır; çoğu benign-asemptomatiktir' seçeneğidir.`,C:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Gartner kanal kisti kalıcı Wolffian kanal kalıntısındandır ve lateral vajinal duvardadır; çoğu benign-asemptomatiktir' seçeneğidir.`,D:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Gartner kanal kisti kalıcı Wolffian kanal kalıntısındandır ve lateral vajinal duvardadır; çoğu benign-asemptomatiktir' seçeneğidir.`,E:`Doğru: Gartner kisti Wolffian kökenli benign lateral duvar kistidir.`},bilgi:[32],benzer_cikmis:[]},{id:`k1-48-vulva-vajen-ve-serviks-hastaliklari-k13-q05`,kazanim:13,zorluk:`zor`,soru:`Konjenital anomaliler (yokluk, septalı/çift vajina) soruluyor. Aşağıdakilerden hangisi yanlıştır?`,secenekler:{A:`Konjenital vajinal anomaliler nadirdir`,B:`Tam yokluk tanımlanmıştır`,C:`Gartner kisti Müller kanal kalıntısından gelişen malign septumdur`,D:`Septalı/çift vajinaya sıklıkla septalı serviks eşlik eder`,E:`Büyük kistler semptom verebilir`},dogru:`D`,aciklama:`Gartner Wolffian kökenli benign kisttir, septum/malign değildir.`,sik_aciklamalari:{A:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Septalı/çift vajinaya sıklıkla septalı serviks eşlik eder' seçeneğidir.`,B:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Septalı/çift vajinaya sıklıkla septalı serviks eşlik eder' seçeneğidir.`,C:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Septalı/çift vajinaya sıklıkla septalı serviks eşlik eder' seçeneğidir.`,D:`Doğru: Gartner Wolffian kökenli benign kisttir, septum/malign değildir.`,E:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Septalı/çift vajinaya sıklıkla septalı serviks eşlik eder' seçeneğidir.`},bilgi:[31,32],benzer_cikmis:[]},{id:`k1-48-vulva-vajen-ve-serviks-hastaliklari-k13-q06`,kazanim:13,zorluk:`orta`,soru:`Gartner kanal kistinin kökeni ve yerleşimi nedir?`,secenekler:{A:`Müller kalıntısından gelişir`,B:`Malign septal tümördür`,C:`Bartholin kanal tıkanmasıdır`,D:`Medial duvarda yerleşir`,E:`Wolffian kalıntısı; lateral duvarda benign kisttir`},dogru:`E`,aciklama:`Gartner kanal kisti kalıcı Wolffian kanal kalıntısındandır ve lateral vajinal duvardadır; çoğu benign ve asemptomatiktir. Büyük kistler semptom verebilir. Müller kalıntısı değildir.`,sik_aciklamalari:{A:`Yanlış: Köken Wolffian (mezanefrik) artığıdır.`,B:`Yanlış: Benign kistik lezyondur.`,C:`Yanlış: Bartholin kisti vulvadadır.`,D:`Yanlış: Tipik yerleşim lateral duvardır.`,E:`Doğru: Wolffian kalıntısı lateral duvarda kistleşir.`},bilgi:[32],benzer_cikmis:[]},{id:`k1-48-vulva-vajen-ve-serviks-hastaliklari-k13-q07`,kazanim:13,zorluk:`orta`,soru:`Vajinanın konjenital anomalileri ve eşlikçi bulguları nelerdir?`,secenekler:{A:`Konjenital anomaliler çok sıktır`,B:`Yokluk, septalı-çift vajina; serviks eşlik edebilir`,C:`Septum hep malign karakterlidir`,D:`Tam yokluk hiç tanımlanmamıştır`,E:`Serviks anomalisi hiç eşlik etmez`},dogru:`B`,aciklama:`Konjenital vajinal anomaliler nadirdir; tam yokluk, septalı veya çift vajina tanımlanmıştır. Septalı-çift vajinaya sıklıkla septalı serviks eşlik eder. Anomaliler Müller kanal füzyon kusurunu yansıtır.`,sik_aciklamalari:{A:`Yanlış: Konjenital anomaliler nadirdir.`,B:`Doğru: Füzyon kusurları vajina ve serviksi birlikte etkiler.`,C:`Yanlış: Septum benign gelişimsel yapıdır.`,D:`Yanlış: Tam yokluk tanımlanmış anomalidendir.`,E:`Yanlış: Septalı serviks sıklıkla eşlik eder.`},bilgi:[31],benzer_cikmis:[]},{id:`k1-48-vulva-vajen-ve-serviks-hastaliklari-k13-q08`,kazanim:13,zorluk:`kolay`,soru:`"Vulvar karsinom yayılımı ve prognozu" kavramının tanımı aşağıdakilerden hangisidir?`,secenekler:{C:`Uzun süre lokal kalma eğilimi vardır; ilk yayılım bölgesel lenf düğümlerine, ileri evrede akciğer ve diğer organlara hematogen metastaz olur.`,B:`1) Bazaloid/siğil benzeri karsinom yüksek riskli HPV ile ilişkilidir. 2) Keratinize skuamöz hücreli karsinom HPV ile ilişkili değildir ve liken skleroz veya skuamöz hücre hiperplazisi zemininde gelişir.`,D:`En yaygın kondilom tipidir; etkeni düşük riskli HPV tip 6 ve 11'dir, cinsel temasla bulaşır ve sıklıkla genç erişkinlerde görülür.`,A:`HPV kondiloma akuminatum etkenidir, VIN ile ilişkilidir ve vulvar skuamöz karsinom alt kümesinde rol oynar.`,E:`Genellikle yaşlı kadınlarda (ortalama yaş ~75), uzun süreli liken skleroz ve skuamöz hücre hiperplazisi zemininde görülür ve HPV ile ilişkili değildir; ön lezyonu dVIN'dir (bazal tabakaya sınırlı anormal keratinizasyon ve sitolojik atipi).`},dogru:`C`,aciklama:`Doğru: Uzun süre lokal kalma eğilimi vardır; ilk yayılım bölgesel lenf düğümlerine, ileri evrede akciğer ve diğer organlara hematogen metastaz olur.`,sik_aciklamalari:{C:`Doğru. Uzun süre lokal kalma eğilimi vardır; ilk yayılım bölgesel lenf düğümlerine, ileri evrede akciğer ve diğer organlara hematogen metastaz olur.`,B:`Yanlış. 1) Bazaloid/siğil benzeri karsinom yüksek riskli HPV ile ilişkilidir. 2) Keratinize skuamöz hücreli karsinom HPV ile ilişkili değildir ve liken skleroz veya skuamöz hücre hiperplazisi zemininde gelişir.`,D:`Yanlış. En yaygın kondilom tipidir; etkeni düşük riskli HPV tip 6 ve 11'dir, cinsel temasla bulaşır ve sıklıkla genç erişkinlerde görülür.`,A:`Yanlış. HPV kondiloma akuminatum etkenidir, VIN ile ilişkilidir ve vulvar skuamöz karsinom alt kümesinde rol oynar.`,E:`Yanlış. Genellikle yaşlı kadınlarda (ortalama yaş ~75), uzun süreli liken skleroz ve skuamöz hücre hiperplazisi zemininde görülür ve HPV ile ilişkili değildir; ön lezyonu dVIN'dir (bazal tabakaya sınırlı anormal keratinizasyon ve sitolojik atipi).`},bilgi:[28],benzer_cikmis:[]},{id:`k1-48-vulva-vajen-ve-serviks-hastaliklari-k13-q09`,kazanim:13,zorluk:`orta`,soru:`"Liken skleroz: histoloji" ile ilgili eşleştirmelerden hangisi doğrudur?`,secenekler:{A:`Epidermis incelmesi, rete çıkıntılarının kaybı, hücresiz homojen dermal fibrozis alanı ve bant tarzında mononükleer inflamatuar infiltrat vardır.`,D:`Lateral vajinal duvarda yerleşir ve kalıcı Wolffian kanal kalıntısından gelişir.`,E:`Gram negatif kokobasildir ve bakteriyel vajinozun ana nedenidir; ince, gri beyaz, kötü kokulu akıntı ve 'balık kokusu' şikayeti görülür.`,C:`Vulvar skuamöz hücreli karsinom riski biraz artmıştır ancak liken skleroz prekanseröz lezyon değildir.`,B:`İki temel tablo liken skleroz ve skuamöz hücre hiperplazisidir; klinik olarak genellikle lökoplaki şeklinde görülürler.`},dogru:`A`,aciklama:`Doğru: Epidermis incelmesi, rete çıkıntılarının kaybı, hücresiz homojen dermal fibrozis alanı ve bant tarzında mononükleer inflamatuar infiltrat vardır.`,sik_aciklamalari:{A:`Doğru. Epidermis incelmesi, rete çıkıntılarının kaybı, hücresiz homojen dermal fibrozis alanı ve bant tarzında mononükleer inflamatuar infiltrat vardır.`,D:`Yanlış. Lateral vajinal duvarda yerleşir ve kalıcı Wolffian kanal kalıntısından gelişir.`,E:`Yanlış. Gram negatif kokobasildir ve bakteriyel vajinozun ana nedenidir; ince, gri beyaz, kötü kokulu akıntı ve 'balık kokusu' şikayeti görülür.`,C:`Yanlış. Vulvar skuamöz hücreli karsinom riski biraz artmıştır ancak liken skleroz prekanseröz lezyon değildir.`,B:`Yanlış. İki temel tablo liken skleroz ve skuamöz hücre hiperplazisidir; klinik olarak genellikle lökoplaki şeklinde görülürler.`},bilgi:[11],benzer_cikmis:[]},{id:`k1-48-vulva-vajen-ve-serviks-hastaliklari-k13-q10`,kazanim:13,zorluk:`orta`,soru:`"Vajinal skuamöz hücreli karsinom" ile ilgili aşağıdakilerden hangisi yanlıştır?`,secenekler:{A:`Son derece nadirdir; neredeyse tüm primer karsinomlar yüksek riskli HPV ile ilişkili skuamöz hücreli karsinomdur; en büyük risk faktörü daha önce serviks veya vulva karsinomu öyküsüdür.`,B:`Sekonder sifilizde görülür; etkeni Treponema pallidum'dur, düz hafif kabarık lezyonlar yapar.`,D:`1) Bazaloid/siğil benzeri karsinom yüksek riskli HPV ile ilişkilidir. 2) Keratinize skuamöz hücreli karsinom HPV ile ilişkili değildir ve liken skleroz veya skuamöz hücre hiperplazisi zemininde gelişir.`,C:`Çoğu cinsel yolla bulaşır: HPV, HSV-1/HSV-2, Neisseria gonorrhoeae, Treponema pallidum ve Candida türleri.`,E:`VIN seyri yüksek dereceli atipi ve karsinoma in situ gelişimidir; invaziv karsinom riski 45 yaşından büyük kadınlarda ve immün sistemi baskılanmış hastalarda artar.`},dogru:`A`,aciklama:`Doğru: Son derece nadirdir; neredeyse tüm primer karsinomlar yüksek riskli HPV ile ilişkili skuamöz hücreli karsinomdur; en büyük risk faktörü daha önce serviks veya vulva karsinomu öyküsüdür.`,sik_aciklamalari:{A:`Doğru. Son derece nadirdir; neredeyse tüm primer karsinomlar yüksek riskli HPV ile ilişkili skuamöz hücreli karsinomdur; en büyük risk faktörü daha önce serviks veya vulva karsinomu öyküsüdür.`,B:`Yanlış. Sekonder sifilizde görülür; etkeni Treponema pallidum'dur, düz hafif kabarık lezyonlar yapar.`,D:`Yanlış. 1) Bazaloid/siğil benzeri karsinom yüksek riskli HPV ile ilişkilidir. 2) Keratinize skuamöz hücreli karsinom HPV ile ilişkili değildir ve liken skleroz veya skuamöz hücre hiperplazisi zemininde gelişir.`,C:`Yanlış. Çoğu cinsel yolla bulaşır: HPV, HSV-1/HSV-2, Neisseria gonorrhoeae, Treponema pallidum ve Candida türleri.`,E:`Yanlış. VIN seyri yüksek dereceli atipi ve karsinoma in situ gelişimidir; invaziv karsinom riski 45 yaşından büyük kadınlarda ve immün sistemi baskılanmış hastalarda artar.`},bilgi:[38],benzer_cikmis:[]},{id:`k1-48-vulva-vajen-ve-serviks-hastaliklari-k13-q11`,kazanim:13,zorluk:`zor`,soru:`"Vulvar skuamöz hücreli karsinomun iki grubu" bilgisini içeren doğru kurulum aşağıdakilerden hangisidir?`,secenekler:{A:`1) Bazaloid/siğil benzeri karsinom yüksek riskli HPV ile ilişkilidir. 2) Keratinize skuamöz hücreli karsinom HPV ile ilişkili değildir ve liken skleroz veya skuamöz hücre hiperplazisi zemininde gelişir.`,C:`En yaygın kondilom tipidir; etkeni düşük riskli HPV tip 6 ve 11'dir, cinsel temasla bulaşır ve sıklıkla genç erişkinlerde görülür.`,B:`Vulvit vulvanın inflamasyonudur; sık görülen, çok nedenli bir durumdur ve sıklıkla yoğun kaşıntı ile seyreder.`,E:`Papiller ekzofitik stromal çekirdekler, üzerinde kalınlaşmış skuamöz epitel ve viral sitopatik değişiklikler (koilositik atipi, büyümüş buruşuk çekirdek, hiperkromazi, sitoplazmik perinükleer halo) vardır.`,D:`HPV pozitif tümörler sıklıkla multifokal, siğil benzeri ve genellikle kötü diferansiye; HPV negatif tümörler genellikle unifokal ve iyi diferansiye, keratinize skuamöz hücreli karsinomdur.`},dogru:`A`,aciklama:`Doğru: 1) Bazaloid/siğil benzeri karsinom yüksek riskli HPV ile ilişkilidir. 2) Keratinize skuamöz hücreli karsinom HPV ile ilişkili değildir ve liken skleroz veya skuamöz hücre hiperplazisi zemininde gelişir.`,sik_aciklamalari:{A:`Doğru. 1) Bazaloid/siğil benzeri karsinom yüksek riskli HPV ile ilişkilidir. 2) Keratinize skuamöz hücreli karsinom HPV ile ilişkili değildir ve liken skleroz veya skuamöz hücre hiperplazisi zemininde gelişir.`,C:`Yanlış. En yaygın kondilom tipidir; etkeni düşük riskli HPV tip 6 ve 11'dir, cinsel temasla bulaşır ve sıklıkla genç erişkinlerde görülür.`,B:`Yanlış. Vulvit vulvanın inflamasyonudur; sık görülen, çok nedenli bir durumdur ve sıklıkla yoğun kaşıntı ile seyreder.`,E:`Yanlış. Papiller ekzofitik stromal çekirdekler, üzerinde kalınlaşmış skuamöz epitel ve viral sitopatik değişiklikler (koilositik atipi, büyümüş buruşuk çekirdek, hiperkromazi, sitoplazmik perinükleer halo) vardır.`,D:`Yanlış. HPV pozitif tümörler sıklıkla multifokal, siğil benzeri ve genellikle kötü diferansiye; HPV negatif tümörler genellikle unifokal ve iyi diferansiye, keratinize skuamöz hücreli karsinomdur.`},bilgi:[23],benzer_cikmis:[]}],ilgili_cikmis:[]},{no:14,metin:`Vajinit etkenlerini ve mikroskobik tanı bulgularını açıklayabilmek`,sorular:[{id:`k1-48-q40`,kazanim:14,zorluk:`kolay`,soru:`Bakteriyel vajinozda mikroskopide görülen, yüzeyi kokobasillerle kaplı yassı epitel hücrelerine ne ad verilir?`,secenekler:{A:`Clue cells (ipucu hücreleri)`,B:`Koilositler`,C:`Paget hücreleri`,D:`Reed-Sternberg hücreleri`,E:`Langhans dev hücreleri`},dogru:`A`,aciklama:`Gardnerella vaginalis'e bağlı bakteriyel vajinozda clue cells ayırt edici bulgudur.`,sik_aciklamalari:{A:`Doğru: clue cells bakteriyel vajinozun tanısal bulgusudur.`,B:`Koilositler HPV'de görülür.`,C:`Paget hücreleri Paget hastalığında görülür.`,D:`Reed-Sternberg hücreleri Hodgkin lenfomada görülür.`,E:`Langhans dev hücreleri granülomatöz hastalıklarda görülür.`},bilgi:[36],benzer_cikmis:[]},{id:`k1-48-q41`,kazanim:14,zorluk:`orta`,soru:`Diyabetik ve yakın zamanda antibiyotik kullanmış kadında kalın, beyaz, peynirimsi akıntı, kaşıntı ve yanma var.

En olası etken ve tanı yöntemi hangisidir?`,secenekler:{A:`Candida albicans; Pap testinde hif formlarının gösterilmesi`,B:`Trichomonas vaginalis; ıslak preparatta hareketli parazit`,C:`Gardnerella vaginalis; clue cells`,D:`HPV; koilositoz`,E:`N. gonorrhoeae; Gram negatif diplokok`},dogru:`A`,aciklama:`Kandida vajiniti peynirimsi akıntı yapar; yatkınlaştırıcılar diyabet ve antibiyotiktir; tanı hif formlarının gösterilmesiyle konur.`,sik_aciklamalari:{A:`Doğru: klinik, risk faktörleri ve tanı uyumludur.`,B:`Trichomonas'ta bol, sulu, gri-yeşil akıntı olur.`,C:`Gardnerella'da ince, gri-beyaz, balık kokulu akıntı olur.`,D:`HPV vajinit yapmaz; koilositoz HPV'nin sitopatik bulgusudur.`,E:`Gonore servisit yapar; bu akıntı tipik değildir.`},bilgi:[33,34],benzer_cikmis:[]},{id:`k1-48-q42`,kazanim:14,zorluk:`zor`,soru:`Vajinit etkenleri ile ilgili aşağıdakilerden hangisi yanlıştır?`,secenekler:{A:`Candida albicans kadınların ~%20'sinde normal floranın üyesidir`,B:`Trichomonas vaginalis dünyada en yaygın viral olmayan CYBE etkenidir`,C:`Trichomonas enfeksiyonlarının çoğu asemptomatiktir`,D:`Gardnerella vaginalis bakteriyel vajinozun ana nedenidir ve balık kokulu akıntı yapar`,E:`Gardnerella vaginalis kamçılı bir protozoondur ve ıslak preparatta hareketli görülür`},dogru:`E`,aciklama:`Gardnerella Gram negatif bir kokobasildir; kamçılı hareketli protozoon Trichomonas vaginalis'tir.`,sik_aciklamalari:{A:`Doğru ifade: kandida kommensal floradadır.`,B:`Doğru ifade: en yaygın viral olmayan CYBE'dir.`,C:`Doğru ifade: çoğu asemptomatiktir.`,D:`Doğru ifade: balık kokusu bakteriyel vajinoz için tipiktir.`,E:`Yanlış ifade (aranan cevap): Gardnerella bakteridir.`},bilgi:[34,35,36],benzer_cikmis:[`97e0c08e589f`]},{id:`k1-48-vulva-vajen-ve-serviks-hastaliklari-k14-q04`,kazanim:14,zorluk:`orta`,soru:`Balık kokulu ince akıntılı hastada mikroskopide clue cells görülüyor. Aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`Clue cells HPV bulgusudur`,B:`Clue cells bakteriyel vajinozun (Gardnerella) ayırt edici bulgusudur; kandida peynirimsi akıntı + hif, trichomonas hareketli parazit ile tanınır`,C:`Koilosit bakteriyel vajinozdur`,D:`Hif trichomonastır`,E:`Hareketli parazit kandidadır`},dogru:`B`,aciklama:`Clue cells Gardnerella, hif Candida, hareketli parazit Trichomonas göstergesidir.`,sik_aciklamalari:{A:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Clue cells bakteriyel vajinozun (Gardnerella) ayırt edici bulgusudur; kandida peynirimsi akıntı + hif, trichomonas hareketli parazit ile tanınır' seçeneğidir.`,B:`Doğru: Clue cells Gardnerella, hif Candida, hareketli parazit Trichomonas göstergesidir.`,C:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Clue cells bakteriyel vajinozun (Gardnerella) ayırt edici bulgusudur; kandida peynirimsi akıntı + hif, trichomonas hareketli parazit ile tanınır' seçeneğidir.`,D:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Clue cells bakteriyel vajinozun (Gardnerella) ayırt edici bulgusudur; kandida peynirimsi akıntı + hif, trichomonas hareketli parazit ile tanınır' seçeneğidir.`,E:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Clue cells bakteriyel vajinozun (Gardnerella) ayırt edici bulgusudur; kandida peynirimsi akıntı + hif, trichomonas hareketli parazit ile tanınır' seçeneğidir.`},bilgi:[34,35,36],benzer_cikmis:[]},{id:`k1-48-vulva-vajen-ve-serviks-hastaliklari-k14-q05`,kazanim:14,zorluk:`zor`,soru:`Etken özellikleri karşılaştırılıyor. Aşağıdakilerden hangisi yanlıştır?`,secenekler:{A:`Trichomonas en yaygın viral olmayan CYBE'dir ve çoğu asemptomatiktir`,B:`Candida ~%20 kadında normal flora üyesidir`,C:`Gardnerella Gram negatif kokobasildir`,D:`Gardnerella kamçılı protozoondur ve ıslak preparatta hareketlidir`,E:`Trichomonasta bol sulu gri-yeşil akıntı olur`},dogru:`B`,aciklama:`Kamçılı hareketli protozoon Trichomonas'tır; Gardnerella bakteridir.`,sik_aciklamalari:{A:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Candida ~%20 kadında normal flora üyesidir' seçeneğidir.`,B:`Doğru: Kamçılı hareketli protozoon Trichomonas'tır; Gardnerella bakteridir.`,C:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Candida ~%20 kadında normal flora üyesidir' seçeneğidir.`,D:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Candida ~%20 kadında normal flora üyesidir' seçeneğidir.`,E:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Candida ~%20 kadında normal flora üyesidir' seçeneğidir.`},bilgi:[33,34,35,36],benzer_cikmis:[]},{id:`k1-48-vulva-vajen-ve-serviks-hastaliklari-k14-q06`,kazanim:14,zorluk:`orta`,soru:`Vajinit etkenlerinin ayırt edici mikroskobik bulguları nelerdir?`,secenekler:{A:`Clue cells HPV bulgusudur`,B:`Koilosit bakteriyel vajinozdur`,C:`Hif trikomonası gösterir`,D:`Clue cells Gardnerella; hif kandida; hareket trikomonastır`,E:`Hareketli parazit kandidadır`},dogru:`D`,aciklama:`Clue cells bakteriyel vajinozun (Gardnerella) ayırt edici bulgusudur; kandida peynirimsi akıntı ve hif, trikomonas hareketli parazit ile tanınır. Balık kokulu ince akıntı bakteriyel vajinoza işaret eder. Her etkenin mikroskopisi farklıdır.`,sik_aciklamalari:{A:`Yanlış: Clue cells Gardnerella'ya bağlıdır.`,B:`Yanlış: Koilosit HPV sitopatisidir.`,C:`Yanlış: Hif kandida psödohifidir.`,D:`Doğru: Üç etkenin mikroskopik imzası farklıdır.`,E:`Yanlış: Hareketli parazit trikomonastır.`},bilgi:[34,35,36],benzer_cikmis:[]},{id:`k1-48-vulva-vajen-ve-serviks-hastaliklari-k14-q07`,kazanim:14,zorluk:`orta`,soru:`Trikomonas, kandida ve gardnerellanın temel özellikleri nasıl ayrılır?`,secenekler:{A:`Trikomonas kamçılı protozoon; kandida normal floradadır`,B:`Gardnerella kamçılı protozoondur`,C:`Trikomonas viral CYBE grubundadır`,D:`Candida normal florada bulunmaz`,E:`Gardnerella Gram pozitif koktur`},dogru:`A`,aciklama:`Trikomonas en yaygın viral olmayan CYBE'dir ve çoğu enfeksiyon asemptomatiktir; kamçılı hareketli protozoondur. Candida kadınların %20'sinde normal flora üyesidir. Gardnerella Gram negatif kokobasil olan bakteriyel vajinoz etkenidir.`,sik_aciklamalari:{A:`Doğru: Hareketli protozoon ile kommensal maya ayrılır.`,B:`Yanlış: Gardnerella bakteriyel kokobasildir.`,C:`Yanlış: Trikomonas protozoal CYBE'dir.`,D:`Yanlış: %20 kadında kommensal bulunur.`,E:`Yanlış: Gardnerella Gram negatif kokobasildir.`},bilgi:[34,35,36],benzer_cikmis:[]},{id:`k1-48-vulva-vajen-ve-serviks-hastaliklari-k14-q08`,kazanim:14,zorluk:`kolay`,soru:`Aşağıdakilerden "Vajinal skuamöz hücreli karsinom" ile ilgili doğru olan seçeneği işaretleyiniz.`,secenekler:{E:`Son derece nadirdir; neredeyse tüm primer karsinomlar yüksek riskli HPV ile ilişkili skuamöz hücreli karsinomdur; en büyük risk faktörü daha önce serviks veya vulva karsinomu öyküsüdür.`,A:`En yaygın kondilom tipidir; etkeni düşük riskli HPV tip 6 ve 11'dir, cinsel temasla bulaşır ve sıklıkla genç erişkinlerde görülür.`,D:`Gram negatif kokobasildir ve bakteriyel vajinozun ana nedenidir; ince, gri beyaz, kötü kokulu akıntı ve 'balık kokusu' şikayeti görülür.`,C:`Vajinanın inflamatuar durumudur; genellikle enfeksiyona bağlı ve geçicidir, temel bulgu vajinal akıntıdır (lökore). Etkenler bakteri, mantar, parazit olup pek çoğu normal kommensal flora üyesidir.`,B:`Lökoplaki yapabilen benign hastalıklar psoriasis ve liken planus; neoplastik lezyonlar skuamöz hücreli karsinoma in situ ve invaziv skuamöz hücreli karsinomdur.`},dogru:`E`,aciklama:`Doğru: Son derece nadirdir; neredeyse tüm primer karsinomlar yüksek riskli HPV ile ilişkili skuamöz hücreli karsinomdur; en büyük risk faktörü daha önce serviks veya vulva karsinomu öyküsüdür.`,sik_aciklamalari:{E:`Doğru. Son derece nadirdir; neredeyse tüm primer karsinomlar yüksek riskli HPV ile ilişkili skuamöz hücreli karsinomdur; en büyük risk faktörü daha önce serviks veya vulva karsinomu öyküsüdür.`,A:`Yanlış. En yaygın kondilom tipidir; etkeni düşük riskli HPV tip 6 ve 11'dir, cinsel temasla bulaşır ve sıklıkla genç erişkinlerde görülür.`,D:`Yanlış. Gram negatif kokobasildir ve bakteriyel vajinozun ana nedenidir; ince, gri beyaz, kötü kokulu akıntı ve 'balık kokusu' şikayeti görülür.`,C:`Yanlış. Vajinanın inflamatuar durumudur; genellikle enfeksiyona bağlı ve geçicidir, temel bulgu vajinal akıntıdır (lökore). Etkenler bakteri, mantar, parazit olup pek çoğu normal kommensal flora üyesidir.`,B:`Yanlış. Lökoplaki yapabilen benign hastalıklar psoriasis ve liken planus; neoplastik lezyonlar skuamöz hücreli karsinoma in situ ve invaziv skuamöz hücreli karsinomdur.`},bilgi:[38],benzer_cikmis:[]},{id:`k1-48-vulva-vajen-ve-serviks-hastaliklari-k14-q09`,kazanim:14,zorluk:`orta`,soru:`"Ekstramammary Paget: klinik, histoloji, seyir" ile ilgili eşleştirmelerden hangisi doğrudur?`,secenekler:{E:`Klinikte kırmızı, pullu, kabuklu plak kronik dermatiti taklit eder; histolojide büyük hücreler, bol soluk ince granüllü sitoplazma ve epidermiste tek tek/gruplar halinde hücreler vardır; invazyon veya metastaz olmaksızın yıllarca sürebilir.`,B:`Bartholin bezi salgı kanalı tıkanması ağrılı gland genişlemesi (Bartholin kisti) ve sıkça apse oluşumuna yol açar.`,C:`Vulvar skuamöz hücreli karsinom riski biraz artmıştır ancak liken skleroz prekanseröz lezyon değildir.`,A:`Vajinanın inflamatuar durumudur; genellikle enfeksiyona bağlı ve geçicidir, temel bulgu vajinal akıntıdır (lökore). Etkenler bakteri, mantar, parazit olup pek çoğu normal kommensal flora üyesidir.`,D:`Reaktif inflamasyon alerjen veya irritan temasına yanıttır; losyon ve sabun katkı maddeleri, antiseptikler ve giysi kimyasalları rol oynar.`},dogru:`E`,aciklama:`Doğru: Klinikte kırmızı, pullu, kabuklu plak kronik dermatiti taklit eder; histolojide büyük hücreler, bol soluk ince granüllü sitoplazma ve epidermiste tek tek/gruplar halinde hücreler vardır; invazyon veya metastaz olmaksızın yıllarca sürebilir.`,sik_aciklamalari:{E:`Doğru. Klinikte kırmızı, pullu, kabuklu plak kronik dermatiti taklit eder; histolojide büyük hücreler, bol soluk ince granüllü sitoplazma ve epidermiste tek tek/gruplar halinde hücreler vardır; invazyon veya metastaz olmaksızın yıllarca sürebilir.`,B:`Yanlış. Bartholin bezi salgı kanalı tıkanması ağrılı gland genişlemesi (Bartholin kisti) ve sıkça apse oluşumuna yol açar.`,C:`Yanlış. Vulvar skuamöz hücreli karsinom riski biraz artmıştır ancak liken skleroz prekanseröz lezyon değildir.`,A:`Yanlış. Vajinanın inflamatuar durumudur; genellikle enfeksiyona bağlı ve geçicidir, temel bulgu vajinal akıntıdır (lökore). Etkenler bakteri, mantar, parazit olup pek çoğu normal kommensal flora üyesidir.`,D:`Yanlış. Reaktif inflamasyon alerjen veya irritan temasına yanıttır; losyon ve sabun katkı maddeleri, antiseptikler ve giysi kimyasalları rol oynar.`},bilgi:[30],benzer_cikmis:[]},{id:`k1-48-vulva-vajen-ve-serviks-hastaliklari-k14-q10`,kazanim:14,zorluk:`orta`,soru:`"Serviks genel bakış" ile ilgili aşağıdakilerden hangisi yanlıştır?`,secenekler:{B:`Servikal lezyonların çoğu inflamatuvar (servisit) niteliktedir; servikal skuamöz hücreli karsinom dünya çapında kadınlarda en sık görülen kanserlerden biridir ve HPV ilişkisi belirgindir.`,A:`Yetişkinlerde nadiren primer hastalık yeridir; daha sık komşu organ kanserlerinin (serviks, mesane, rektum) sekonder tutulumu görülür. Nadir konjenital anomaliler: vajinanın tam yokluğu, septalı veya çift vajina.`,E:`Gram negatif kokobasildir ve bakteriyel vajinozun ana nedenidir; ince, gri beyaz, kötü kokulu akıntı ve 'balık kokusu' şikayeti görülür.`,D:`Son derece nadirdir; neredeyse tüm primer karsinomlar yüksek riskli HPV ile ilişkili skuamöz hücreli karsinomdur; en büyük risk faktörü daha önce serviks veya vulva karsinomu öyküsüdür.`,C:`VIN seyri yüksek dereceli atipi ve karsinoma in situ gelişimidir; invaziv karsinom riski 45 yaşından büyük kadınlarda ve immün sistemi baskılanmış hastalarda artar.`},dogru:`B`,aciklama:`Doğru: Servikal lezyonların çoğu inflamatuvar (servisit) niteliktedir; servikal skuamöz hücreli karsinom dünya çapında kadınlarda en sık görülen kanserlerden biridir ve HPV ilişkisi belirgindir.`,sik_aciklamalari:{B:`Doğru. Servikal lezyonların çoğu inflamatuvar (servisit) niteliktedir; servikal skuamöz hücreli karsinom dünya çapında kadınlarda en sık görülen kanserlerden biridir ve HPV ilişkisi belirgindir.`,A:`Yanlış. Yetişkinlerde nadiren primer hastalık yeridir; daha sık komşu organ kanserlerinin (serviks, mesane, rektum) sekonder tutulumu görülür. Nadir konjenital anomaliler: vajinanın tam yokluğu, septalı veya çift vajina.`,E:`Yanlış. Gram negatif kokobasildir ve bakteriyel vajinozun ana nedenidir; ince, gri beyaz, kötü kokulu akıntı ve 'balık kokusu' şikayeti görülür.`,D:`Yanlış. Son derece nadirdir; neredeyse tüm primer karsinomlar yüksek riskli HPV ile ilişkili skuamöz hücreli karsinomdur; en büyük risk faktörü daha önce serviks veya vulva karsinomu öyküsüdür.`,C:`Yanlış. VIN seyri yüksek dereceli atipi ve karsinoma in situ gelişimidir; invaziv karsinom riski 45 yaşından büyük kadınlarda ve immün sistemi baskılanmış hastalarda artar.`},bilgi:[40],benzer_cikmis:[]},{id:`k1-48-vulva-vajen-ve-serviks-hastaliklari-k14-q11`,kazanim:14,zorluk:`zor`,soru:`"Vajinit tanımı ve yatkınlık" ile ilgili bir hastada bulunacak aşağıdaki bulgulardan hangisi beklenmez?`,secenekler:{A:`Vajinanın inflamatuar durumudur; genellikle enfeksiyona bağlı ve geçicidir, temel bulgu vajinal akıntıdır (lökore). Etkenler bakteri, mantar, parazit olup pek çoğu normal kommensal flora üyesidir.`,C:`Candida vulvit nedeni olmakla birlikte cinsel yolla bulaşmaz; diyabet, antibiyotik kullanımı, gebelik ve immün yetmezlikte yatkınlık artar.`,D:`HSV-1 ve HSV-2 genital herpes etkenidir; ağrılı vezikül ve ülserler ile tekrarlayıcı seyir yapar.`,B:`HPV pozitif tümörler sıklıkla multifokal, siğil benzeri ve genellikle kötü diferansiye; HPV negatif tümörler genellikle unifokal ve iyi diferansiye, keratinize skuamöz hücreli karsinomdur.`,E:`Daha az yaygın formdur, HPV tip 16 ile ilişkilidir, ortalama yaş ~60'tır, sıklıkla sigara içen kadınlarda ve çoğunlukla çok odaklı lezyonlar şeklinde görülür.`},dogru:`A`,aciklama:`Doğru: Vajinanın inflamatuar durumudur; genellikle enfeksiyona bağlı ve geçicidir, temel bulgu vajinal akıntıdır (lökore). Etkenler bakteri, mantar, parazit olup pek çoğu normal kommensal flora üyesidir.`,sik_aciklamalari:{A:`Doğru. Vajinanın inflamatuar durumudur; genellikle enfeksiyona bağlı ve geçicidir, temel bulgu vajinal akıntıdır (lökore). Etkenler bakteri, mantar, parazit olup pek çoğu normal kommensal flora üyesidir.`,C:`Yanlış. Candida vulvit nedeni olmakla birlikte cinsel yolla bulaşmaz; diyabet, antibiyotik kullanımı, gebelik ve immün yetmezlikte yatkınlık artar.`,D:`Yanlış. HSV-1 ve HSV-2 genital herpes etkenidir; ağrılı vezikül ve ülserler ile tekrarlayıcı seyir yapar.`,B:`Yanlış. HPV pozitif tümörler sıklıkla multifokal, siğil benzeri ve genellikle kötü diferansiye; HPV negatif tümörler genellikle unifokal ve iyi diferansiye, keratinize skuamöz hücreli karsinomdur.`,E:`Yanlış. Daha az yaygın formdur, HPV tip 16 ile ilişkilidir, ortalama yaş ~60'tır, sıklıkla sigara içen kadınlarda ve çoğunlukla çok odaklı lezyonlar şeklinde görülür.`},bilgi:[33],benzer_cikmis:[]}],ilgili_cikmis:[{id:`97e0c08e589f`,soru:`Aşağıdakilerden hangisi prokaryottur?`,secenekler:{A:`HPV`,B:`Neisseria gonorrhoeae`,C:`Candida albicans`,D:`Trichomonas vaginalis`,E:`Sarcoptes scabiei`},cevap:`B`}]},{no:15,metin:`Vajinanın malign neoplazmlarını (VAIN, vajinal SCC, embriyonel rabdomiyosarkom) tanımlayabilmek`,sorular:[{id:`k1-48-q43`,kazanim:15,zorluk:`kolay`,soru:`5 yaşından küçük çocuklarda vajinada üzüm salkımı görünümünde polipoid kitle yapan tümör hangisidir?`,secenekler:{A:`Embriyonel rabdomiyosarkom (sarkoma botryoides)`,B:`Vajinal skuamöz hücreli karsinom`,C:`Gartner kanal kisti`,D:`Kondiloma akuminatum`,E:`Leiomyom`},dogru:`A`,aciklama:`Embriyonel rabdomiyosarkom (sarkoma botryoides) malign embriyonel rabdomiyoblastlardan köken alır ve küçük çocuklarda görülür.`,sik_aciklamalari:{A:`Doğru: küçük çocuklarda vajinanın tipik malign tümörüdür.`,B:`Vajinal SCC erişkinlerde ve HPV ile ilişkilidir.`,C:`Gartner kisti benign kistik lezyondur.`,D:`Kondilom HPV'ye bağlı siğildir.`,E:`Leiomyom çocuklukta vajinada tipik değildir.`},bilgi:[39],benzer_cikmis:[]},{id:`k1-48-q44`,kazanim:15,zorluk:`orta`,soru:`Primer vajinal skuamöz hücreli karsinom için en büyük risk faktörü hangisidir?`,secenekler:{A:`Daha önce serviks veya vulva karsinomu öyküsü`,B:`Kandida vajiniti`,C:`Gartner kanal kisti`,D:`Bakteriyel vajinoz`,E:`Septalı vajina`},dogru:`A`,aciklama:`Vajinal SCC'nin en büyük risk faktörü önceki serviks veya vulva karsinomudur; neredeyse tamamı yüksek riskli HPV ile ilişkilidir.`,sik_aciklamalari:{A:`Doğru: ortak HPV alan etkisi riski açıklar.`,B:`Kandida vajiniti karsinom risk faktörü değildir.`,C:`Gartner kisti benigndir.`,D:`Bakteriyel vajinoz bu riskle ilişkilendirilmez.`,E:`Konjenital anomaliler risk faktörü olarak tanımlanmaz.`},bilgi:[38],benzer_cikmis:[]},{id:`k1-48-q45`,kazanim:15,zorluk:`zor`,soru:`Vajinanın malign neoplazmları ile ilgili aşağıdakilerden hangisi yanlıştır?`,secenekler:{A:`VAIN skuamöz hücreli karsinomun öncü lezyonudur`,B:`Vajinal SCC çoğunlukla üst vajinanın arka duvarında yerleşir`,C:`Vajinal SCC bölgesel iliak lenf düğümlerine yayılır`,D:`Embriyonel rabdomiyosarkom idrar kesesi ve safra kanallarında da görülebilir`,E:`Primer vajinal karsinomların çoğu adenokarsinom olup HPV ile ilişkisizdir`},dogru:`E`,aciklama:`Primer vajinal karsinomların neredeyse tamamı yüksek riskli HPV ile ilişkili skuamöz hücreli karsinomdur.`,sik_aciklamalari:{A:`Doğru ifade: VAIN displazi derecesine göre sınıflanan öncül lezyondur.`,B:`Doğru ifade: üst vajina/arka duvar tipik yerleşimdir.`,C:`Doğru ifade: yayılım iliak lenf düğümlerinedir.`,D:`Doğru ifade: diğer yerleşimleri bunlardır.`,E:`Yanlış ifade (aranan cevap): çoğu HPV ilişkili SCC'dir.`},bilgi:[37,38,39],benzer_cikmis:[]},{id:`k1-48-vulva-vajen-ve-serviks-hastaliklari-k15-q04`,kazanim:15,zorluk:`orta`,soru:`Serviks kanseri öykülü kadında üst vajinada kitle saptanıyor. Aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`En sık tümör adenokarsinomdur`,B:`Risk faktörü kandidadır`,C:`Yayılım akciğere erken olur`,D:`Primer vajinal SCC nadirdir, yüksek riskli HPV ile ilişkilidir; en büyük risk faktörü önceki serviks/vulva karsinomudur; yayılım iliak nodülleredir`,E:`VAIN invaziv karsinomdur`},dogru:`D`,aciklama:`VAIN öncü lezyondur; üst vajina yerleşimi tipiktir; prognoz evreye bağlıdır.`,sik_aciklamalari:{A:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Primer vajinal SCC nadirdir, yüksek riskli HPV ile ilişkilidir; en büyük risk faktörü önceki serviks/vulva karsinomudur; yayılım iliak nodülleredir' seçeneğidir.`,B:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Primer vajinal SCC nadirdir, yüksek riskli HPV ile ilişkilidir; en büyük risk faktörü önceki serviks/vulva karsinomudur; yayılım iliak nodülleredir' seçeneğidir.`,C:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Primer vajinal SCC nadirdir, yüksek riskli HPV ile ilişkilidir; en büyük risk faktörü önceki serviks/vulva karsinomudur; yayılım iliak nodülleredir' seçeneğidir.`,D:`Doğru: VAIN öncü lezyondur; üst vajina yerleşimi tipiktir; prognoz evreye bağlıdır.`,E:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Primer vajinal SCC nadirdir, yüksek riskli HPV ile ilişkilidir; en büyük risk faktörü önceki serviks/vulva karsinomudur; yayılım iliak nodülleredir' seçeneğidir.`},bilgi:[37,38],benzer_cikmis:[]},{id:`k1-48-vulva-vajen-ve-serviks-hastaliklari-k15-q05`,kazanim:15,zorluk:`zor`,soru:`4 yaşındaki kızda üzüm salkımı görünümlü vajinal polipoid kitle görülüyor. Aşağıdakilerden hangisi yanlıştır?`,secenekler:{A:`5 yaş altında görülür`,B:`Malign embriyonel rabdomiyoblast kökenlidir`,C:`Rabdomiyosarkom benign Gartner kistidir ve erişkin SCC'sidir`,D:`Diğer yerleşimler mesane ve safra kanallarıdır`,E:`Tanı embriyonel rabdomiyosarkomdur (sarkoma botryoides)`},dogru:`E`,aciklama:`Sarkoma botryoides küçük çocukların malign tümörüdür.`,sik_aciklamalari:{A:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Tanı embriyonel rabdomiyosarkomdur (sarkoma botryoides)' seçeneğidir.`,B:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Tanı embriyonel rabdomiyosarkomdur (sarkoma botryoides)' seçeneğidir.`,C:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Tanı embriyonel rabdomiyosarkomdur (sarkoma botryoides)' seçeneğidir.`,D:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Tanı embriyonel rabdomiyosarkomdur (sarkoma botryoides)' seçeneğidir.`,E:`Doğru: Sarkoma botryoides küçük çocukların malign tümörüdür.`},bilgi:[38,39],benzer_cikmis:[]},{id:`k1-48-vulva-vajen-ve-serviks-hastaliklari-k15-q06`,kazanim:15,zorluk:`orta`,soru:`Primer vajinal skuamöz karsinomun özellikleri ve risk faktörü nedir?`,secenekler:{A:`En sık tümör adenokarsinomdur`,B:`Risk faktörü vajinal kandidadır`,C:`Nadir HPV ilişkili SCC; risk önceki serviks kanseridir`,D:`VAIN invaziv karsinomun kendisidir`,E:`Yayılım akciğere erken hematogendir`},dogru:`C`,aciklama:`Primer vajinal skuamöz karsinom nadirdir ve yüksek riskli HPV ile ilişkilidir; en büyük risk faktörü önceki serviks veya vulva karsinomudur. VAIN skuamöz karsinomun öncü lezyonudur. Yayılım iliak nodülleredir.`,sik_aciklamalari:{A:`Yanlış: Primer tümörlerin neredeyse tümü SCC'dir.`,B:`Yanlış: Risk HPV ve önceki anogenital kanserdir.`,C:`Doğru: Nadirlik, HPV ilişkisi ve risk faktörü tipiktir.`,D:`Yanlış: VAIN intraepiteliyal öncü lezyondur.`,E:`Yanlış: İlk yayılım bölgesel lenf düğümlerinedir.`},bilgi:[37,38],benzer_cikmis:[]},{id:`k1-48-vulva-vajen-ve-serviks-hastaliklari-k15-q07`,kazanim:15,zorluk:`orta`,soru:`Küçük çocukta üzüm salkımı görünümlü vajinal kitlenin tanısı nedir?`,secenekler:{A:`Benign Gartner kisti varyantıdır`,B:`Erişkin skuamöz karsinomudur`,C:`Rabdomiyoblast içermeyen lipomdur`,D:`Yalnızca ergenlikte görülen kisttir`,E:`5 yaş altı üzüm salkımı rabdomiyosarkomdur`},dogru:`E`,aciklama:`Embriyonel rabdomiyosarkom (sarkoma botryoides) 5 yaş altı bebek ve çocuklarda üzüm salkımı görünümlü polipoid kitledir. Histogenezi malign embriyonel rabdomiyoblastlardır. Diğer yerleşimler mesane ve safra kanallarıdır.`,sik_aciklamalari:{A:`Yanlış: Gartner kisti benign Wolffian artığıdır.`,B:`Yanlış: Erişkin malignitesi SCC'dir.`,C:`Yanlış: Tümör malign rabdomiyoblastlardan oluşur.`,D:`Yanlış: 5 yaş altında görülür.`,E:`Doğru: Botryoid görünüm küçük çocukta tipiktir.`},bilgi:[39],benzer_cikmis:[]},{id:`k1-48-vulva-vajen-ve-serviks-hastaliklari-k15-q08`,kazanim:15,zorluk:`kolay`,soru:`"Vajinit tanımı ve yatkınlık" kavramının tanımı aşağıdakilerden hangisidir?`,secenekler:{E:`Vajinanın inflamatuar durumudur; genellikle enfeksiyona bağlı ve geçicidir, temel bulgu vajinal akıntıdır (lökore). Etkenler bakteri, mantar, parazit olup pek çoğu normal kommensal flora üyesidir.`,D:`Genellikle yaşlı kadınlarda (ortalama yaş ~75), uzun süreli liken skleroz ve skuamöz hücre hiperplazisi zemininde görülür ve HPV ile ilişkili değildir; ön lezyonu dVIN'dir (bazal tabakaya sınırlı anormal keratinizasyon ve sitolojik atipi).`,A:`Candida vulvit nedeni olmakla birlikte cinsel yolla bulaşmaz; diyabet, antibiyotik kullanımı, gebelik ve immün yetmezlikte yatkınlık artar.`,C:`Vulva dış kadın genital organıdır; kıllı deri (labia majora) ve mukoza (labia minora) içerir.`,B:`Sekonder sifilizde görülür; etkeni Treponema pallidum'dur, düz hafif kabarık lezyonlar yapar.`},dogru:`E`,aciklama:`Doğru: Vajinanın inflamatuar durumudur; genellikle enfeksiyona bağlı ve geçicidir, temel bulgu vajinal akıntıdır (lökore). Etkenler bakteri, mantar, parazit olup pek çoğu normal kommensal flora üyesidir.`,sik_aciklamalari:{E:`Doğru. Vajinanın inflamatuar durumudur; genellikle enfeksiyona bağlı ve geçicidir, temel bulgu vajinal akıntıdır (lökore). Etkenler bakteri, mantar, parazit olup pek çoğu normal kommensal flora üyesidir.`,D:`Yanlış. Genellikle yaşlı kadınlarda (ortalama yaş ~75), uzun süreli liken skleroz ve skuamöz hücre hiperplazisi zemininde görülür ve HPV ile ilişkili değildir; ön lezyonu dVIN'dir (bazal tabakaya sınırlı anormal keratinizasyon ve sitolojik atipi).`,A:`Yanlış. Candida vulvit nedeni olmakla birlikte cinsel yolla bulaşmaz; diyabet, antibiyotik kullanımı, gebelik ve immün yetmezlikte yatkınlık artar.`,C:`Yanlış. Vulva dış kadın genital organıdır; kıllı deri (labia majora) ve mukoza (labia minora) içerir.`,B:`Yanlış. Sekonder sifilizde görülür; etkeni Treponema pallidum'dur, düz hafif kabarık lezyonlar yapar.`},bilgi:[33],benzer_cikmis:[]},{id:`k1-48-vulva-vajen-ve-serviks-hastaliklari-k15-q09`,kazanim:15,zorluk:`orta`,soru:`"Vajinit tanımı ve yatkınlık" ile ilgili eşleştirmelerden hangisi doğrudur?`,secenekler:{E:`Vajinanın inflamatuar durumudur; genellikle enfeksiyona bağlı ve geçicidir, temel bulgu vajinal akıntıdır (lökore). Etkenler bakteri, mantar, parazit olup pek çoğu normal kommensal flora üyesidir.`,B:`Son derece nadirdir; neredeyse tüm primer karsinomlar yüksek riskli HPV ile ilişkili skuamöz hücreli karsinomdur; en büyük risk faktörü daha önce serviks veya vulva karsinomu öyküsüdür.`,D:`Nadir bir vajinal tümördür (sarkoma botryoides); histogenezi malign embriyonel rabdomiyoblastlardır ve 5 yaşından küçük bebek ve çocuklarda görülür.`,A:`1) Bazaloid/siğil benzeri karsinom yüksek riskli HPV ile ilişkilidir. 2) Keratinize skuamöz hücreli karsinom HPV ile ilişkili değildir ve liken skleroz veya skuamöz hücre hiperplazisi zemininde gelişir.`,C:`Vulvar kondilomlar kansere dönüşmez ancak vajina ve servikste HPV ilişkili prekanseröz lezyon riski artar.`},dogru:`E`,aciklama:`Doğru: Vajinanın inflamatuar durumudur; genellikle enfeksiyona bağlı ve geçicidir, temel bulgu vajinal akıntıdır (lökore). Etkenler bakteri, mantar, parazit olup pek çoğu normal kommensal flora üyesidir.`,sik_aciklamalari:{E:`Doğru. Vajinanın inflamatuar durumudur; genellikle enfeksiyona bağlı ve geçicidir, temel bulgu vajinal akıntıdır (lökore). Etkenler bakteri, mantar, parazit olup pek çoğu normal kommensal flora üyesidir.`,B:`Yanlış. Son derece nadirdir; neredeyse tüm primer karsinomlar yüksek riskli HPV ile ilişkili skuamöz hücreli karsinomdur; en büyük risk faktörü daha önce serviks veya vulva karsinomu öyküsüdür.`,D:`Yanlış. Nadir bir vajinal tümördür (sarkoma botryoides); histogenezi malign embriyonel rabdomiyoblastlardır ve 5 yaşından küçük bebek ve çocuklarda görülür.`,A:`Yanlış. 1) Bazaloid/siğil benzeri karsinom yüksek riskli HPV ile ilişkilidir. 2) Keratinize skuamöz hücreli karsinom HPV ile ilişkili değildir ve liken skleroz veya skuamöz hücre hiperplazisi zemininde gelişir.`,C:`Yanlış. Vulvar kondilomlar kansere dönüşmez ancak vajina ve servikste HPV ilişkili prekanseröz lezyon riski artar.`},bilgi:[33],benzer_cikmis:[]},{id:`k1-48-vulva-vajen-ve-serviks-hastaliklari-k15-q10`,kazanim:15,zorluk:`orta`,soru:`"Kondiloma akuminatum: etken ve epidemi" ile ilgili eşleştirmelerden hangisi doğrudur?`,secenekler:{E:`En yaygın kondilom tipidir; etkeni düşük riskli HPV tip 6 ve 11'dir, cinsel temasla bulaşır ve sıklıkla genç erişkinlerde görülür.`,C:`Atipik epitel hücrelerinin intraepidermal proliferasyonudur; vulva derisi (ekstramammary Paget) veya meme ucu derisinde görülür. Olası köken vulva derisi kanallarındaki multipotent hücrelerdir.`,B:`Vulvit vulvanın inflamasyonudur; sık görülen, çok nedenli bir durumdur ve sıklıkla yoğun kaşıntı ile seyreder.`,A:`Reaktif inflamasyon alerjen veya irritan temasına yanıttır; losyon ve sabun katkı maddeleri, antiseptikler ve giysi kimyasalları rol oynar.`,D:`VIN seyri yüksek dereceli atipi ve karsinoma in situ gelişimidir; invaziv karsinom riski 45 yaşından büyük kadınlarda ve immün sistemi baskılanmış hastalarda artar.`},dogru:`E`,aciklama:`Doğru: En yaygın kondilom tipidir; etkeni düşük riskli HPV tip 6 ve 11'dir, cinsel temasla bulaşır ve sıklıkla genç erişkinlerde görülür.`,sik_aciklamalari:{E:`Doğru. En yaygın kondilom tipidir; etkeni düşük riskli HPV tip 6 ve 11'dir, cinsel temasla bulaşır ve sıklıkla genç erişkinlerde görülür.`,C:`Yanlış. Atipik epitel hücrelerinin intraepidermal proliferasyonudur; vulva derisi (ekstramammary Paget) veya meme ucu derisinde görülür. Olası köken vulva derisi kanallarındaki multipotent hücrelerdir.`,B:`Yanlış. Vulvit vulvanın inflamasyonudur; sık görülen, çok nedenli bir durumdur ve sıklıkla yoğun kaşıntı ile seyreder.`,A:`Yanlış. Reaktif inflamasyon alerjen veya irritan temasına yanıttır; losyon ve sabun katkı maddeleri, antiseptikler ve giysi kimyasalları rol oynar.`,D:`Yanlış. VIN seyri yüksek dereceli atipi ve karsinoma in situ gelişimidir; invaziv karsinom riski 45 yaşından büyük kadınlarda ve immün sistemi baskılanmış hastalarda artar.`},bilgi:[19],benzer_cikmis:[]},{id:`k1-48-vulva-vajen-ve-serviks-hastaliklari-k15-q11`,kazanim:15,zorluk:`zor`,soru:`"Vulvitin enfeksiyöz etkenleri" klinik bağlamda aşağıdakilerden hangisi doğrudur?`,secenekler:{B:`Çoğu cinsel yolla bulaşır: HPV, HSV-1/HSV-2, Neisseria gonorrhoeae, Treponema pallidum ve Candida türleri.`,D:`Epidermis kalınlaşması (akantoz), hiperkeratoz, dermiste bazen lenfositik infiltrasyon ve sitolojik atipisi olmayan artmış mitotik aktivite gösteren hiperplastik epitel vardır.`,C:`Eski isimleri hiperplastik distrofi ve liken simpleks kronikustur; nedeni şiddetli kaşıntıyı gidermek için ovma/kaşımadır ve lökoplaki görünümü oluşturur.`,A:`HPV kondiloma akuminatum etkenidir, VIN ile ilişkilidir ve vulvar skuamöz karsinom alt kümesinde rol oynar.`,E:`Genital organların siğil benzeri lezyonlarıdır; cinsel yolla bulaşan iki temel formu kondiloma lata ve kondiloma akuminatumdur.`},dogru:`B`,aciklama:`Doğru: Çoğu cinsel yolla bulaşır: HPV, HSV-1/HSV-2, Neisseria gonorrhoeae, Treponema pallidum ve Candida türleri.`,sik_aciklamalari:{B:`Doğru. Çoğu cinsel yolla bulaşır: HPV, HSV-1/HSV-2, Neisseria gonorrhoeae, Treponema pallidum ve Candida türleri.`,D:`Yanlış. Epidermis kalınlaşması (akantoz), hiperkeratoz, dermiste bazen lenfositik infiltrasyon ve sitolojik atipisi olmayan artmış mitotik aktivite gösteren hiperplastik epitel vardır.`,C:`Yanlış. Eski isimleri hiperplastik distrofi ve liken simpleks kronikustur; nedeni şiddetli kaşıntıyı gidermek için ovma/kaşımadır ve lökoplaki görünümü oluşturur.`,A:`Yanlış. HPV kondiloma akuminatum etkenidir, VIN ile ilişkilidir ve vulvar skuamöz karsinom alt kümesinde rol oynar.`,E:`Yanlış. Genital organların siğil benzeri lezyonlarıdır; cinsel yolla bulaşan iki temel formu kondiloma lata ve kondiloma akuminatumdur.`},bilgi:[4],benzer_cikmis:[]}],ilgili_cikmis:[]},{no:16,metin:`Serviks patolojisine genel bakışı ve tarama yöntemlerini bilmek`,sorular:[{id:`k1-48-q46`,kazanim:16,zorluk:`kolay`,soru:`Serviks kanseri taramasında kullanılan yöntemler hangileridir?`,secenekler:{A:`Papanicolaou (Pap) testi ve HPV testi`,B:`Serum CA-125 ve CEA`,C:`Mamografi`,D:`Kolonoskopi`,E:`Göğüs grafisi`},dogru:`A`,aciklama:`Servikal tarama Pap testi ve HPV testi ile yapılır.`,sik_aciklamalari:{A:`Doğru: sitoloji ve HPV testi tarama yöntemleridir.`,B:`Serum belirteçleri servikal tarama yöntemi değildir.`,C:`Mamografi meme kanseri taramasıdır.`,D:`Kolonoskopi kolorektal tarama yöntemidir.`,E:`Göğüs grafisi servikal tarama için kullanılmaz.`},bilgi:[40],benzer_cikmis:[]},{id:`k1-48-q47`,kazanim:16,zorluk:`orta`,soru:`Servikal skuamöz hücreli karsinom ile ilgili aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`Dünyada kadınlarda en sık görülen kanserlerden biridir ve HPV ile ilişkisi belirgindir`,B:`Gelişmekte olan ülkelerde mortalitesi çok düşüktür`,C:`Taranabilir bir kanser değildir`,D:`HPV ile ilişkisi yoktur`,E:`Servikal lezyonların çoğunu oluşturur`},dogru:`A`,aciklama:`Servikal SCC kadınlarda sık görülen bir kanserdir, HPV ile ilişkilidir ve Pap/HPV testiyle taranır.`,sik_aciklamalari:{A:`Doğru: sıklığı ve HPV ilişkisi doğru verilmiştir.`,B:`Gelişmekte olan ülkelerde mortalite yüksektir.`,C:`Pap ve HPV testiyle taranabilir.`,D:`HPV ilişkisi belirgindir.`,E:`Servikal lezyonların çoğu inflamatuvardır.`},bilgi:[40],benzer_cikmis:[]},{id:`k1-48-q48`,kazanim:16,zorluk:`zor`,soru:`Servikal sitolojik yaymada doğrudan saptanabilen enfeksiyöz etken/bulgu aşağıdakilerden hangisi değildir?`,secenekler:{A:`Trichomonas vaginalis`,B:`Candida hif formları`,C:`Bakteriyel vajinozda clue cells`,D:`HPV'ye bağlı koilositoz`,E:`Treponema pallidum spiroketleri`},dogru:`E`,aciklama:`Pap yaymasında trichomonas, kandida hifleri, clue cells ve koilositler görülebilir; T. pallidum rutin yaymada gösterilemez.`,sik_aciklamalari:{A:`Trichomonas yaymada görülebilir.`,B:`Kandida tanısı Pap testinde hif formlarıyla konur.`,C:`Clue cells yaymada saptanır.`,D:`Koilositoz HPV'nin sitopatik etkisidir ve yaymada fark edilir.`,E:`Doğru: spiroketler rutin Pap boyasında görülmez; karanlık alan veya seroloji gerekir.`},bilgi:[20,34,36,40],benzer_cikmis:[`e28693ffa242`]},{id:`k1-48-vulva-vajen-ve-serviks-hastaliklari-k16-q04`,kazanim:16,zorluk:`orta`,soru:`Tarama programında Pap ve HPV testi tartışılıyor. Aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`Servikal lezyonların çoğu servisit gibi inflamatuvar süreçlerdir; SCC HPV ile güçlü ilişkilidir; tarama Pap + HPV testi ile yapılır`,B:`Lezyonların çoğu maligndir`,C:`HPV ilişkisi yoktur`,D:`Tarama tümör belirteçleriyle yapılır`,E:`Gelişmekte mortalite düşüktür`},dogru:`A`,aciklama:`Servikste inflamasyon sık; SCC HPV ilişkili; Pap + HPV taraması esastır.`,sik_aciklamalari:{A:`Doğru: Servikste inflamasyon sık; SCC HPV ilişkili; Pap + HPV taraması esastır.`,B:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Servikal lezyonların çoğu servisit gibi inflamatuvar süreçlerdir; SCC HPV ile güçlü ilişkilidir; tarama Pap + HPV testi ile yapılır' seçeneğidir.`,C:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Servikal lezyonların çoğu servisit gibi inflamatuvar süreçlerdir; SCC HPV ile güçlü ilişkilidir; tarama Pap + HPV testi ile yapılır' seçeneğidir.`,D:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Servikal lezyonların çoğu servisit gibi inflamatuvar süreçlerdir; SCC HPV ile güçlü ilişkilidir; tarama Pap + HPV testi ile yapılır' seçeneğidir.`,E:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Servikal lezyonların çoğu servisit gibi inflamatuvar süreçlerdir; SCC HPV ile güçlü ilişkilidir; tarama Pap + HPV testi ile yapılır' seçeneğidir.`},bilgi:[40],benzer_cikmis:[]},{id:`k1-48-vulva-vajen-ve-serviks-hastaliklari-k16-q05`,kazanim:16,zorluk:`zor`,soru:`Servikal SCC epidemiyolojisi soruluyor. Aşağıdakilerden hangisi yanlıştır?`,secenekler:{A:`HPV ilişkisi belirgindir`,B:`Gelişmekte olan ülkelerde mortalite yüksektir`,C:`Servikal SCC dünyada kadınlarda en sık kanserlerdendir`,D:`Servikal SCC HPV'den bağımsızdır ve tarama gereksizdir`,E:`Tarama Pap ve HPV testini içerir`},dogru:`C`,aciklama:`HPV ilişkisi belirgindir; tarama mortaliteyi azaltır.`,sik_aciklamalari:{A:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Servikal SCC dünyada kadınlarda en sık kanserlerdendir' seçeneğidir.`,B:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Servikal SCC dünyada kadınlarda en sık kanserlerdendir' seçeneğidir.`,C:`Doğru: HPV ilişkisi belirgindir; tarama mortaliteyi azaltır.`,D:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Servikal SCC dünyada kadınlarda en sık kanserlerdendir' seçeneğidir.`,E:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Servikal SCC dünyada kadınlarda en sık kanserlerdendir' seçeneğidir.`},bilgi:[40],benzer_cikmis:[]},{id:`k1-48-vulva-vajen-ve-serviks-hastaliklari-k16-q06`,kazanim:16,zorluk:`orta`,soru:`Servikal lezyonların doğası ve tarama yöntemi nedir?`,secenekler:{A:`Lezyonların çoğu maligndir`,B:`Lezyonlar inflamatuvar; tarama Pap ve HPV'dir`,C:`HPV ile ilişki yoktur`,D:`Tarama tümör belirteçleriyle yapılır`,E:`Gelişmekte mortalite düşüktür`},dogru:`B`,aciklama:`Servikal lezyonların çoğu servisit gibi inflamatuvar süreçlerdir; skuamöz karsinom HPV ile güçlü ilişkilidir. Tarama Pap ve HPV testi ile yapılır. Düzenli tarama mortaliteyi belirgin azaltır.`,sik_aciklamalari:{A:`Yanlış: Çoğunluk inflamatuvar servisitlerdir.`,B:`Doğru: İnflamasyon sık, SCC HPV ilişkili, tarama sitolojiktir.`,C:`Yanlış: HPV ilişkisi belirgindir.`,D:`Yanlış: Tarama Pap ve HPV testini içerir.`,E:`Yanlış: Taramasız toplumlarda mortalite yüksektir.`},bilgi:[40],benzer_cikmis:[]},{id:`k1-48-vulva-vajen-ve-serviks-hastaliklari-k16-q07`,kazanim:16,zorluk:`orta`,soru:`Servikal skuamöz karsinomun epidemiyolojisi ve korunma yaklaşımı nedir?`,secenekler:{A:`Servikal SCC HPV'den bağımsızdır`,B:`Tarama gereksiz ve etkisizdir`,C:`Mortalite her yerde eşit düşüktür`,D:`Sık kanser; HPV ilişkili; Pap-HPV taranır`,E:`Aşı taramayı tamamen gereksiz kılar`},dogru:`D`,aciklama:`Servikal skuamöz karsinom dünyada kadınlarda en sık kanserlerdendir; HPV ilişkisi belirgindir ve tarama Pap ile HPV testini içerir. Gelişmekte olan ülkelerde tarama eksikliği mortaliteyi yükseltir. Aşılama ve tarama birlikte korunma sağlar.`,sik_aciklamalari:{A:`Yanlış: HPV onkogenezi E6-E7 üzerinden yürür.`,B:`Yanlış: Tarama preinvaziv lezyonu yakalar.`,C:`Yanlış: Taramasız bölgelerde mortalite yüksektir.`,D:`Doğru: Sıklık, HPV ilişkisi ve tarama üçlüsü esastır.`,E:`Yanlış: Aşı taramayı tamamlar, ortadan kaldırmaz.`},bilgi:[40],benzer_cikmis:[`93fada718ad4`]},{id:`k1-48-vulva-vajen-ve-serviks-hastaliklari-k16-q08`,kazanim:16,zorluk:`kolay`,soru:`"Kondiloma akuminatum: etken ve epidemi" kavramının tanımı aşağıdakilerden hangisidir?`,secenekler:{D:`En yaygın kondilom tipidir; etkeni düşük riskli HPV tip 6 ve 11'dir, cinsel temasla bulaşır ve sıklıkla genç erişkinlerde görülür.`,B:`Papiller ekzofitik stromal çekirdekler, üzerinde kalınlaşmış skuamöz epitel ve viral sitopatik değişiklikler (koilositik atipi, büyümüş buruşuk çekirdek, hiperkromazi, sitoplazmik perinükleer halo) vardır.`,C:`Vulvar kondilomlar kansere dönüşmez ancak vajina ve servikste HPV ilişkili prekanseröz lezyon riski artar.`,A:`Dünya çapında en yaygın viral olmayan cinsel yolla bulaşan enfeksiyondur; çoğu enfeksiyon asemptomatiktir.`,E:`Atipik epitel hücrelerinin intraepidermal proliferasyonudur; vulva derisi (ekstramammary Paget) veya meme ucu derisinde görülür. Olası köken vulva derisi kanallarındaki multipotent hücrelerdir.`},dogru:`D`,aciklama:`Doğru: En yaygın kondilom tipidir; etkeni düşük riskli HPV tip 6 ve 11'dir, cinsel temasla bulaşır ve sıklıkla genç erişkinlerde görülür.`,sik_aciklamalari:{D:`Doğru. En yaygın kondilom tipidir; etkeni düşük riskli HPV tip 6 ve 11'dir, cinsel temasla bulaşır ve sıklıkla genç erişkinlerde görülür.`,B:`Yanlış. Papiller ekzofitik stromal çekirdekler, üzerinde kalınlaşmış skuamöz epitel ve viral sitopatik değişiklikler (koilositik atipi, büyümüş buruşuk çekirdek, hiperkromazi, sitoplazmik perinükleer halo) vardır.`,C:`Yanlış. Vulvar kondilomlar kansere dönüşmez ancak vajina ve servikste HPV ilişkili prekanseröz lezyon riski artar.`,A:`Yanlış. Dünya çapında en yaygın viral olmayan cinsel yolla bulaşan enfeksiyondur; çoğu enfeksiyon asemptomatiktir.`,E:`Yanlış. Atipik epitel hücrelerinin intraepidermal proliferasyonudur; vulva derisi (ekstramammary Paget) veya meme ucu derisinde görülür. Olası köken vulva derisi kanallarındaki multipotent hücrelerdir.`},bilgi:[19],benzer_cikmis:[]},{id:`k1-48-vulva-vajen-ve-serviks-hastaliklari-k16-q09`,kazanim:16,zorluk:`orta`,soru:`"Kondiloma lata" ile ilgili eşleştirmelerden hangisi doğrudur?`,secenekler:{B:`Sekonder sifilizde görülür; etkeni Treponema pallidum'dur, düz hafif kabarık lezyonlar yapar.`,D:`Eski isimleri hiperplastik distrofi ve liken simpleks kronikustur; nedeni şiddetli kaşıntıyı gidermek için ovma/kaşımadır ve lökoplaki görünümü oluşturur.`,C:`Çoğu cinsel yolla bulaşır: HPV, HSV-1/HSV-2, Neisseria gonorrhoeae, Treponema pallidum ve Candida türleri.`,A:`Lateral vajinal duvarda yerleşir ve kalıcı Wolffian kanal kalıntısından gelişir.`,E:`Genital organların siğil benzeri lezyonlarıdır; cinsel yolla bulaşan iki temel formu kondiloma lata ve kondiloma akuminatumdur.`},dogru:`B`,aciklama:`Doğru: Sekonder sifilizde görülür; etkeni Treponema pallidum'dur, düz hafif kabarık lezyonlar yapar.`,sik_aciklamalari:{B:`Doğru. Sekonder sifilizde görülür; etkeni Treponema pallidum'dur, düz hafif kabarık lezyonlar yapar.`,D:`Yanlış. Eski isimleri hiperplastik distrofi ve liken simpleks kronikustur; nedeni şiddetli kaşıntıyı gidermek için ovma/kaşımadır ve lökoplaki görünümü oluşturur.`,C:`Yanlış. Çoğu cinsel yolla bulaşır: HPV, HSV-1/HSV-2, Neisseria gonorrhoeae, Treponema pallidum ve Candida türleri.`,A:`Yanlış. Lateral vajinal duvarda yerleşir ve kalıcı Wolffian kanal kalıntısından gelişir.`,E:`Yanlış. Genital organların siğil benzeri lezyonlarıdır; cinsel yolla bulaşan iki temel formu kondiloma lata ve kondiloma akuminatumdur.`},bilgi:[18],benzer_cikmis:[]},{id:`k1-48-vulva-vajen-ve-serviks-hastaliklari-k16-q10`,kazanim:16,zorluk:`orta`,soru:`"Candida enfeksiyonu (vulva)" kavramı hakkında verilen aşağıdakilerden hangisi doğrudur?`,secenekler:{D:`Candida vulvit nedeni olmakla birlikte cinsel yolla bulaşmaz; diyabet, antibiyotik kullanımı, gebelik ve immün yetmezlikte yatkınlık artar.`,E:`Vulvar kondilomlar kansere dönüşmez ancak vajina ve servikste HPV ilişkili prekanseröz lezyon riski artar.`,B:`Son derece nadirdir; neredeyse tüm primer karsinomlar yüksek riskli HPV ile ilişkili skuamöz hücreli karsinomdur; en büyük risk faktörü daha önce serviks veya vulva karsinomu öyküsüdür.`,A:`Her yaşta görülebilir (menopoz sonrası kadınlar, ergenlik öncesi kızlar); patogenezi belirsizdir, subepiteliyal aktif T hücre infiltrasyonu ve otoimmün bozukluklarla birliktelik vardır.`,C:`Reaktif inflamasyon alerjen veya irritan temasına yanıttır; losyon ve sabun katkı maddeleri, antiseptikler ve giysi kimyasalları rol oynar.`},dogru:`D`,aciklama:`Doğru: Candida vulvit nedeni olmakla birlikte cinsel yolla bulaşmaz; diyabet, antibiyotik kullanımı, gebelik ve immün yetmezlikte yatkınlık artar.`,sik_aciklamalari:{D:`Doğru. Candida vulvit nedeni olmakla birlikte cinsel yolla bulaşmaz; diyabet, antibiyotik kullanımı, gebelik ve immün yetmezlikte yatkınlık artar.`,E:`Yanlış. Vulvar kondilomlar kansere dönüşmez ancak vajina ve servikste HPV ilişkili prekanseröz lezyon riski artar.`,B:`Yanlış. Son derece nadirdir; neredeyse tüm primer karsinomlar yüksek riskli HPV ile ilişkili skuamöz hücreli karsinomdur; en büyük risk faktörü daha önce serviks veya vulva karsinomu öyküsüdür.`,A:`Yanlış. Her yaşta görülebilir (menopoz sonrası kadınlar, ergenlik öncesi kızlar); patogenezi belirsizdir, subepiteliyal aktif T hücre infiltrasyonu ve otoimmün bozukluklarla birliktelik vardır.`,C:`Yanlış. Reaktif inflamasyon alerjen veya irritan temasına yanıttır; losyon ve sabun katkı maddeleri, antiseptikler ve giysi kimyasalları rol oynar.`},bilgi:[7],benzer_cikmis:[]},{id:`k1-48-vulva-vajen-ve-serviks-hastaliklari-k16-q11`,kazanim:16,zorluk:`zor`,soru:`"HPV pozitif/negatif vulvar karsinom farkları" klinik bağlamda aşağıdakilerden hangisi doğrudur?`,secenekler:{D:`HPV pozitif tümörler sıklıkla multifokal, siğil benzeri ve genellikle kötü diferansiye; HPV negatif tümörler genellikle unifokal ve iyi diferansiye, keratinize skuamöz hücreli karsinomdur.`,A:`Genital organların siğil benzeri lezyonlarıdır; cinsel yolla bulaşan iki temel formu kondiloma lata ve kondiloma akuminatumdur.`,E:`Kronik, sklerozan dermatozdur; düz beyaz plaklar veya papüller (lökoplaki) görülür, zamanla genişler ve birleşir, vajinal açıklık daralabilir, labialar atrofik ve sert hale gelir.`,B:`Lökoplaki yapabilen benign hastalıklar psoriasis ve liken planus; neoplastik lezyonlar skuamöz hücreli karsinoma in situ ve invaziv skuamöz hücreli karsinomdur.`,C:`Eski isimleri hiperplastik distrofi ve liken simpleks kronikustur; nedeni şiddetli kaşıntıyı gidermek için ovma/kaşımadır ve lökoplaki görünümü oluşturur.`},dogru:`D`,aciklama:`Doğru: HPV pozitif tümörler sıklıkla multifokal, siğil benzeri ve genellikle kötü diferansiye; HPV negatif tümörler genellikle unifokal ve iyi diferansiye, keratinize skuamöz hücreli karsinomdur.`,sik_aciklamalari:{D:`Doğru. HPV pozitif tümörler sıklıkla multifokal, siğil benzeri ve genellikle kötü diferansiye; HPV negatif tümörler genellikle unifokal ve iyi diferansiye, keratinize skuamöz hücreli karsinomdur.`,A:`Yanlış. Genital organların siğil benzeri lezyonlarıdır; cinsel yolla bulaşan iki temel formu kondiloma lata ve kondiloma akuminatumdur.`,E:`Yanlış. Kronik, sklerozan dermatozdur; düz beyaz plaklar veya papüller (lökoplaki) görülür, zamanla genişler ve birleşir, vajinal açıklık daralabilir, labialar atrofik ve sert hale gelir.`,B:`Yanlış. Lökoplaki yapabilen benign hastalıklar psoriasis ve liken planus; neoplastik lezyonlar skuamöz hücreli karsinoma in situ ve invaziv skuamöz hücreli karsinomdur.`,C:`Yanlış. Eski isimleri hiperplastik distrofi ve liken simpleks kronikustur; nedeni şiddetli kaşıntıyı gidermek için ovma/kaşımadır ve lökoplaki görünümü oluşturur.`},bilgi:[27],benzer_cikmis:[]}],ilgili_cikmis:[{id:`e28693ffa242`,soru:`Tıbbi Patoloji Tıbbi Patoloji Cinsel Yolla Bulaşan Hastalıklar Hangisi servikovajinal yayma sitolojisinde direkt olarak tesbit edilebilir?`,secenekler:{A:`Treponema pallidum`,B:`Neisseria gonorrhoeae`,C:`HerpesSimpleks`,D:`Trichomonas vaginalis`,E:`Chlamydiatrachomatis`},cevap:`B`}]}]};export{e as default};